// Синхронізація одностороння і централізована: будь-яка зміна стану проходить
// через render(), тому syncUrl() наприкінці render() покриває ВСІ переходи без
// правок у кожній кнопці. Зворотний напрям - applyRoute() на старті і popstate.
const ROUTE_TABS=['overview','preview','html','text','links','info','assets','review','activity'];
let routedOnce=false;
function routePath(){if(state.selected)return `/projects/${state.selected.id}/${ROUTE_TABS.includes(state.tab)?state.tab:'overview'}`;if(state.landingSelected)return `/landings/${state.landingSelected.id}`;return '/'+(state.page||'projects')}
function parseRoute(path){const seg=String(path||'').split('/').filter(Boolean);if(seg[0]==='projects'&&seg[1])return {kind:'project',id:seg[1],tab:ROUTE_TABS.includes(seg[2])?seg[2]:'overview'};if(seg[0]==='landings'&&seg[1])return {kind:'landing',id:seg[1]};return {kind:'page',page:seg[0]||'projects'}}
function syncUrl(){if(!state.token)return;const want=routePath();if(location.pathname!==want){routedOnce?history.pushState(null,'',want):history.replaceState(null,'',want)}routedOnce=true}
async function pageData(page){if(page==='infographic')setTimeout(()=>{loadIconLibrary();loadFreeGallery()},0);if(page==='settings')await loadSystem();if(page==='usage')await loadUsage();if(page==='landings')await loadLandings()}
async function applyRoute(){const r=parseRoute(location.pathname);try{
if(r.kind==='project'){if(state.selected?.id!==r.id){state.artifact=null;state.selected=await api(`/api/projects/${r.id}`);state.events=await api(`/api/projects/${r.id}/events`);selectArtifact(null,false)}state.page='projects';state.landingSelected=null;state.tab=r.tab;return}
if(r.kind==='landing'){state.selected=null;state.page='landings';await pageData('landings');if(state.landingSelected?.id!==r.id)state.landingSelected=await api(`/api/landings/${r.id}`);return}
state.selected=null;state.landingSelected=null;state.styleEdit=null;state.page=allowedPages().includes(r.page)?r.page:(allowedPages()[0]||'projects');await pageData(state.page)
}catch(x){toast(x.message,true);state.selected=null;state.landingSelected=null;state.page='projects'}}
addEventListener('popstate',async()=>{if(!state.token)return;await applyRoute();render()});

async function boot(){bindKeys();if(!state.token){render();loadAuthMethods();return}bootScreen();try{await loadAll();await applyRoute()}catch(x){toast(x.message,true)}render();startLive()}
async function loadAll(){const core=await Promise.all([api('/api/me'),api('/api/projects'),api('/api/styles'),api('/api/models'),api('/api/assets'),api('/api/palettes').catch(()=>[])]);[state.me,state.projects,state.styles,state.models,state.assets,state.palettes]=core;if(can('usage.view'))await loadUsage();if(can('users.manage'))state.users=await api('/api/users').catch(()=>[]);await loadSecrets();if(state.selected)await refreshSelected()}
async function loadUsage(){if(!can('usage.view'))return;state.usage=await api(`/api/usage?days=${state.usageDays}&user_id=${encodeURIComponent(state.usageUser)}`).catch(()=>state.usage||{})}
async function setUsageFilter(days,userId){if(days!=null)state.usageDays=Number(days);if(userId!=null)state.usageUser=userId;await loadUsage();render()}
function niceCeil(v){if(v<=0)return 1;const p=Math.pow(10,Math.floor(Math.log10(v)));const n=v/p;return (n<=1?1:n<=2?2:n<=5?5:10)*p}
function usageChart(){const d=state.usage.by_day||[];if(!d.length)return '<p class="muted-note">Немає запусків у вибраному періоді.</p>';const max=niceCeil(Math.max(...d.map(x=>x.cost)));const fmt=v=>'$'+(max<1?v.toFixed(2):max<10?v.toFixed(1):Math.round(v));const lines=[1,.75,.5,.25,0];return `<div class="uchart"><div class="uaxis">${lines.map(f=>`<small style="bottom:calc(${f*100}% - 6px)">${fmt(max*f)}</small>`).join('')}</div><div class="uplot"><div class="ubars-zone">${lines.map(f=>`<i class="ugrid ${f===0?'zero':''}" style="bottom:${f*100}%"></i>`).join('')}<div class="ubars">${d.map(x=>`<div class="ubar-wrap" title="${x.day}: ${money(x.cost)} · ${x.projects} проєкт(и)"><div class="ubar" style="height:${Math.max(2,x.cost/max*100)}%"></div></div>`).join('')}</div></div><div class="ulabels">${d.map(x=>`<small>${x.day.slice(x.day.length>7?5:2)}</small>`).join('')}</div></div></div>`}
function usageStagePanel(){const st=state.usage.by_stage||{};const rowsDef=[['extract','Аналіз товару','безкоштовна проба + AI-розбір фактів'],['content','Текст сторінок','майстер-макет, мобільне перекомпонування'],['images','Зображення','Hero/Feature та їх перегенерації'],['other','Переклади, рецензії, виправлення','+ Мова, AI-рецензент, авто-фікс']];const total=rowsDef.reduce((a,[k])=>a+(st[k]||0),0);if(!total)return '';return `<section class="panel"><h2>Куди йдуть гроші</h2><div class="stagebars">${rowsDef.map(([k,label,note])=>{const v=st[k]||0;const pct=Math.round(v/total*100);return `<div class="stagerow" title="${note}"><span>${label}</span><div class="stagetrack"><i style="width:${Math.max(v>0?2:0,pct)}%"></i></div><b>${money(v)}</b><small>${pct}%</small></div>`}).join('')}</div><p class="muted-note">Розбивка рахується з поетапних кошторисів проєктів у вибраному зрізі (період і фільтр користувача діють).</p></section>`}
function usageUserTable(){const list=state.usage.by_user||[];if(!list.length)return '';return `<section class="panel"><h2>По користувачах</h2><div class="table-wrap"><table><thead><tr><th>Користувач</th><th>Проєкти</th><th>Вартість</th><th>Токени (вх/вих)</th><th>Зображення</th><th>Схвалено</th></tr></thead><tbody>${list.map(u=>`<tr class="${state.usageUser===u.user_id?'urow-active':''}" onclick="setUsageFilter(null,state.usageUser==='${u.user_id}'?'':'${u.user_id}')"><td>${esc(u.name)}</td><td>${u.projects}</td><td>${money(u.cost)}</td><td>${u.input_tokens} / ${u.output_tokens}</td><td>${u.images}</td><td>${u.approved}</td></tr>`).join('')}</tbody></table></div><p class="muted-note">Клік по рядку фільтрує картки та графік за цим користувачем; повторний клік знімає фільтр.</p></section>`}
async function refreshSelected(){const [p,e]=await Promise.all([api(`/api/projects/${state.selected.id}`),api(`/api/projects/${state.selected.id}/events`)]);state.selected=p;state.events=e;selectArtifact(state.artifact?.id,false)}
let live,liveSig='',liveFails=0;
function liveSignature(){return JSON.stringify({page:state.page,tab:state.tab,projects:state.projects.map(x=>[x.id,x.status,x.stage,x.progress,x.estimated_cost,x.name,x.sku,x.product_category]),sel:state.selected?[state.selected.id,state.selected.status,state.selected.stage,state.selected.progress,state.selected.estimated_cost,(state.selected.artifacts||[]).length,(state.selected.critics||[]).length,state.events[0]?.id]:null,assets:state.page==='media'?state.assets.length:0,lands:state.page==='landings'?state.landings.map(x=>[x.id,x.status,x.stage,x.estimated_cost]):0,lsel:state.landingSelected?[state.landingSelected.id,state.landingSelected.status,state.landingSelected.stage]:null})}
function startLive(){clearInterval(live);liveSig=liveSignature();live=setInterval(async()=>{if(!state.token)return;try{state.projects=await api('/api/projects');if(state.selected)await refreshSelected();else if(state.page==='media')state.assets=await api('/api/assets');else if(state.page==='landings'){state.landings=await api('/api/landings');if(state.landingSelected)state.landingSelected=await api(`/api/landings/${state.landingSelected.id}`)}liveFails=0;setOffline(false);const sig=liveSignature();if(sig===liveSig)return;const active=document.activeElement;const userIsInteracting=document.querySelector('dialog[open]')||document.querySelector('.dd.open')||active?.matches('input,textarea,select,iframe,.dd-btn')||(state.selected&&['preview','html'].includes(state.tab));if(userIsInteracting)return;liveSig=sig;const y=scrollY;render();scrollTo(0,y)}catch{liveFails++;if(liveFails>=2)setOffline(true)}},2500)}
async function loadAuthMethods(){try{state.authMethods=await api('/api/auth/methods')}catch{state.authMethods={}}render()}
async function login(e){e.preventDefault();const f=new FormData(e.target);try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});state.token=d.access_token;localStorage.setItem('token',state.token);await boot()}catch(x){toast(x.message,true)}}
function logout(){localStorage.removeItem('token');location.reload()}
function loginView(){root.innerHTML=`<div class="auth"><canvas class="pixel-bg"></canvas><img class="auth-logo" src="${LOGO}" alt="ARTLINE"><form onsubmit="login(event)"><h1>Вхід до робочого простору</h1><p>Генерація та керування rich-контентом.</p><label>Email<input name="email" type="email" required></label><label>Пароль<input name="password" type="password" required></label><button class="btn primary">Увійти</button>${(state.authMethods?.github||state.authMethods?.google)?`<div class="auth-or">або</div>`:''}${state.authMethods?.github?`<button type="button" class="btn secondary" onclick="location.href='/api/auth/github'">Увійти через GitHub</button>`:''}${state.authMethods?.google?`<button type="button" class="btn secondary" onclick="location.href='/api/auth/google'">Увійти через Google</button>`:''}</form></div>`;startPixelField(document.querySelector('.auth .pixel-bg'))}
// Access is driven by effective permissions (role defaults + per-user overrides),
// resolved by the API and returned in state.me.permissions. The UI mirrors them.
const can=p=>(state.me?.permissions||[]).includes(p);
const allowedPages=()=>['projects','landings',...(can('project.create')?['infographic']:[]),...(can('style.manage')?['styles']:[]),...(can('media.view')?['media']:[]),...(can('usage.view')?['usage']:[]),...(can('users.manage')?['users']:[]),...(can('settings.view')?['settings']:[])];
function allowedTabs(){const t=['overview','preview'];if(can('project.edit_html'))t.push('html');t.push('text');if(can('project.edit_html'))t.push('links');if(can('project.create'))t.push('info');if(can('media.view'))t.push('assets');if(can('review.request_changes')||can('review.approve'))t.push('review');t.push('activity');return t}
function shell(content){const pages=allowedPages(),nav=[['projects','Проєкти'],['landings','Лендінги'],['infographic','Інфографіка'],['styles','Стилі'],['media','Медіа'],['usage','Використання'],['users','Користувачі'],['settings','Налаштування']].filter(x=>pages.includes(x[0]));root.innerHTML=`<div class="shell"><aside><div class="brand-lockup"><img src="${LOGO}" alt="ARTLINE"><small>Rich Studio</small></div><nav>${nav.map(([k,v])=>`<button class="${state.page===k?'active':''}" onclick="go('${k}')">${v}</button>`).join('')}</nav><div class="userbox"><b>${esc(state.me?.name||state.me?.email)}</b><small>${ROLE_LABEL[state.me?.role]||esc(state.me?.role)}</small><button onclick="logout()">Вийти</button></div></aside><main><div class="appbar"><span>Платформа AI rich-контенту</span><span class="api-state">${state.models.source==='openai+configuration'?'Моделі OpenAI синхронізовано':'Моделі з конфігурації'}</span></div><div class="container">${content}</div></main></div>`}
function go(page){state.page=page;state.selected=null;state.styleEdit=null;state.landingSelected=null;pageData(page).then(render);render()}
// Категорії приїжджають із чужих сторінок двома мовами і в різних числах:
// «3D принтери» і «3D принтеры», «Монітори» і «Мониторы» - це ОДНА категорія.
// Ключ згортає кирилицю до спільної основи, тож у фільтрі лишається один пункт.
const catKey=v=>String(v||'').toLowerCase().replace(/ё/g,'е').replace(/[ъь’']/g,'').replace(/[иіый]/g,'i').replace(/[еєэ]/g,'e').replace(/ґ/g,'г').replace(/[^a-zа-я0-9]+/g,'').replace(/(i|a|я|e|у|ю|о)$/,'');
// Буває, що замість категорії витягнулась назва товару («Монітор 27" Qube
// Overlord G27Q300H»). Такі пункти не викидаємо, але виносимо в окрему групу,
// щоб не топити ними справжні категорії.
const catIsProductName=(cat,p)=>{const c=catKey(cat),n=catKey(p?.name);return !!c&&(c===n||(c.length>22&&n.includes(c)))};
function projectCategoryGroups(){const map=new Map();for(const p of state.projects){const raw=(p.product_category||'').trim();if(!raw)continue;const key=catKey(raw);if(!key)continue;const row=map.get(key)||{key,labels:new Map(),count:0,junk:0};row.count++;row.labels.set(raw,(row.labels.get(raw)||0)+1);if(catIsProductName(raw,p))row.junk++;map.set(key,row)}
const rows=[...map.values()].map(r=>({key:r.key,count:r.count,junk:r.junk===r.count,label:[...r.labels.entries()].sort((a,b)=>b[1]-a[1]||(/[іїєґ]/i.test(b[0])?1:0)-(/[іїєґ]/i.test(a[0])?1:0)||a[0].localeCompare(b[0],'uk'))[0][0]}));
const by=(a,b)=>a.label.localeCompare(b.label,'uk');
return {main:rows.filter(r=>!r.junk).sort(by),rare:rows.filter(r=>r.junk).sort(by)}}
const projectStyles=()=>[...new Set(state.projects.map(x=>(x.style_name||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'uk'));
const projectModels=()=>[...new Set(state.projects.map(x=>(x.text_model||'').trim()).filter(Boolean))].sort();
function filtered(){let rows=[...state.projects];
// Пошук: кожне слово має знайтись хоч десь - так «qube 27» знаходить монітор,
// а не вимагає точного порядку слів.
const haystack=x=>[x.name,x.source_url,x.text_model,x.sku,x.product_category,x.style_name].join(' ').toLowerCase();
const words=state.search.toLowerCase().trim().split(/\s+/).filter(Boolean);
if(words.length)rows=rows.filter(x=>{const h=haystack(x);return words.every(w=>h.includes(w))});
if(state.status!=='all')rows=rows.filter(x=>x.status===state.status);
if(state.category!=='all')rows=rows.filter(x=>state.category==='none'?!(x.product_category||'').trim():catKey(x.product_category)===state.category);
if(state.styleFilter!=='all')rows=rows.filter(x=>(x.style_name||'')===state.styleFilter);
if(state.modelFilter!=='all')rows=rows.filter(x=>(x.text_model||'')===state.modelFilter);
if(state.period!=='all'){const days=Number(state.period)||0,edge=Date.now()-days*86400000;rows=rows.filter(x=>new Date(x.created_at||0).getTime()>=edge)}
// Швидкі фільтри складаються (І), бо оператор шукає перетин: «мої» + «з помилкою».
if(state.quick.has('mine'))rows=rows.filter(x=>x.owner_id&&state.me&&x.owner_id===state.me.id);
if(state.quick.has('error'))rows=rows.filter(x=>x.status==='error'||!!x.error);
if(state.quick.has('review'))rows=rows.filter(x=>x.status==='review');
if(state.quick.has('running'))rows=rows.filter(x=>['processing','queued'].includes(x.status));
if(state.quick.has('nosku'))rows=rows.filter(x=>!(x.sku||'').trim());
if(state.quick.has('nocat'))rows=rows.filter(x=>!(x.product_category||'').trim()||catIsProductName(x.product_category,x));
const split=state.sort.lastIndexOf('_'),key=state.sort.slice(0,split),dir=state.sort.slice(split+1);
rows.sort((a,b)=>{let av,bv;
if(key==='name'){av=(a.name||'').toLowerCase();bv=(b.name||'').toLowerCase();const c=av.localeCompare(bv,'uk');return c*(dir==='asc'?1:-1)}
else if(key==='category'){av=(a.product_category||'￿').toLowerCase();bv=(b.product_category||'￿').toLowerCase();const c=av.localeCompare(bv,'uk');return c*(dir==='asc'?1:-1)||(a.name||'').localeCompare(b.name||'','uk')}
else if(key==='style'){av=(a.style_name||'￿').toLowerCase();bv=(b.style_name||'￿').toLowerCase();const c=av.localeCompare(bv,'uk');return c*(dir==='asc'?1:-1)||(a.name||'').localeCompare(b.name||'','uk')}
else if(key==='cost'){av=a.estimated_cost||0;bv=b.estimated_cost||0}
else if(key==='duration'){av=a.duration_seconds||0;bv=b.duration_seconds||0}
else if(key==='progress'){av=a.progress||0;bv=b.progress||0}
else{av=new Date(a[key]||0).getTime();bv=new Date(b[key]||0).getTime()}
return (av>bv?1:av<bv?-1:0)*(dir==='asc'?1:-1)});
return rows}
const QUICK_FILTERS=[['mine','Мої'],['running','У роботі'],['review','На перевірці'],['error','З помилкою'],['nosku','Без артикула'],['nocat','Категорія не визначена']];
function activeFilterChips(){const out=[];
if(state.search.trim())out.push(['search',`пошук: «${state.search.trim()}»`,`setFilter('search','')`]);
if(state.status!=='all')out.push(['status',STATUS[state.status]||state.status,`setFilter('status','all')`]);
if(state.category!=='all'){const g=projectCategoryGroups();const found=[...g.main,...g.rare].find(c=>c.key===state.category);out.push(['category',state.category==='none'?'без категорії':(found?found.label:state.category),`setFilter('category','all')`])}
if(state.styleFilter!=='all')out.push(['style',state.styleFilter,`setFilter('styleFilter','all')`]);
if(state.modelFilter!=='all')out.push(['model',state.modelFilter,`setFilter('modelFilter','all')`]);
if(state.period!=='all')out.push(['period',`за ${state.period} дн.`,`setFilter('period','all')`]);
for(const [k,label] of QUICK_FILTERS)if(state.quick.has(k))out.push([k,label,`toggleQuick('${k}')`]);
return out}

function badge(s){return `<span class="badge ${s}">${STATUS[s]||s}</span>`}
// Progress with motion. render() rebuilds the DOM, so a bare CSS transition has
// nothing to animate - the bar is born at its final width. We remember the last
// shown value per project, render at the OLD width and let animateProgressBars()
// move it to the new one on the next frame, so the browser tweens for real.
const PROGRESS_MEMO={};
function progress(p,active=false,id=''){const pct=Math.max(0,Math.min(100,Number(p)||0));const prev=(id&&id in PROGRESS_MEMO)?PROGRESS_MEMO[id]:pct;const dot=active&&pct>0&&pct<100?`<b class="phead" style="left:${prev}%" data-left="${pct}"></b>`:'';return `<div class="progress ${active?'run':''}"><i style="width:${prev}%" data-w="${pct}" data-pid="${esc(id)}"></i>${dot}</div>`}
function animateProgressBars(){requestAnimationFrame(()=>{document.querySelectorAll('.progress i[data-w]').forEach(el=>{el.style.width=el.dataset.w+'%';if(el.dataset.pid)PROGRESS_MEMO[el.dataset.pid]=Number(el.dataset.w)});document.querySelectorAll('.progress .phead[data-left]').forEach(el=>{el.style.left=el.dataset.left+'%'});const mk=Object.keys(PROGRESS_MEMO);for(let i=0;i<mk.length-100;i++)delete PROGRESS_MEMO[mk[i]]})}
function setProjectView(view){state.projectView=view;localStorage.setItem('projectView',view);render()}
function primeEstimate(){const f=document.querySelector('#newProject form');if(f)updateEstimate(f)}
function projectCreateActions(){if(!can('project.create'))return '';return `<div class="row"><button class="btn secondary" onclick="openBulkImportDialog()">Імпорт CSV</button><button class="btn primary" onclick="state.uploads=[];state.uploads360=false;newProject.showModal();primeEstimate()">+ Новий проєкт</button></div>`}
function projectsPage(){const rows=filtered(),groups=projectCategoryGroups(),chips=activeFilterChips(),
sortOptions=[['finished_at_desc','Нещодавно завершені'],['created_at_desc','Спочатку нові'],['created_at_asc','Спочатку старі'],['name_asc','За назвою А→Я'],['name_desc','За назвою Я→А'],['category_asc','За категорією'],['style_asc','За стилем'],['cost_desc','Найдорожчі'],['cost_asc','Найдешевші'],['duration_desc','Найдовші'],['progress_desc','За прогресом']],
periods=[['all','За весь час'],['7','За 7 днів'],['30','За 30 днів'],['90','За 90 днів']],
catOption=c=>`<option value="${esc(c.key)}" ${state.category===c.key?'selected':''}>${esc(c.label)} (${c.count})</option>`;
shell(`<header class="pagehead"><div><small class="eyebrow">КЕРУВАННЯ КОНТЕНТОМ ARTLINE</small><h1>Проєкти</h1><p>Вставте посилання на товар — назва визначиться автоматично.</p></div>${projectCreateActions()}</header>
<section class="toolbar project-toolbar"><input placeholder="Пошук за назвою, артикулом, URL, моделлю або стилем" value="${esc(state.search)}" oninput="setFilter('search',this.value)">
<select onchange="setFilter('status',this.value)"><option value="all">Усі статуси</option>${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${state.status===k?'selected':''}>${v}</option>`).join('')}</select>
<select onchange="setFilter('category',this.value)"><option value="all">Усі категорії</option>${groups.main.map(catOption).join('')}<option value="none" ${state.category==='none'?'selected':''}>Без категорії</option>${groups.rare.length?`<optgroup label="Схоже на назву товару">${groups.rare.map(catOption).join('')}</optgroup>`:''}</select>
<select onchange="setFilter('styleFilter',this.value)"><option value="all">Усі стилі</option>${projectStyles().map(x=>`<option value="${esc(x)}" ${state.styleFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select>
<select onchange="setFilter('modelFilter',this.value)"><option value="all">Усі моделі</option>${projectModels().map(x=>`<option value="${esc(x)}" ${state.modelFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select>
<select onchange="setFilter('period',this.value)">${periods.map(([v,l])=>`<option value="${v}" ${state.period===v?'selected':''}>${l}</option>`).join('')}</select>
<select onchange="setFilter('sort',this.value)">${sortOptions.map(([value,label])=>`<option value="${value}" ${state.sort===value?'selected':''}>${label}</option>`).join('')}</select>
<div class="view-switch" aria-label="Вигляд проєктів"><button class="${state.projectView==='cards'?'active':''}" onclick="setProjectView('cards')">Картки</button><button class="${state.projectView==='list'?'active':''}" onclick="setProjectView('list')">Список</button></div></section>
<section class="filter-row"><div class="quick-chips">${QUICK_FILTERS.map(([k,label])=>`<button class="${state.quick.has(k)?'on':''}" onclick="toggleQuick('${k}')">${label}</button>`).join('')}</div>
<div class="filter-summary"><b>${rows.length}</b> із ${state.projects.length}${chips.length?` · ${chips.map(([k,label,action])=>`<span class="chip">${esc(label)}<i onclick="${action}" title="Прибрати">×</i></span>`).join('')}<button class="link" onclick="resetFilters()">Скинути все</button>`:''}</div></section>
<section class="project-grid ${state.projectView==='list'?'list-view':''}">${rows.map(p=>`<article class="project" role="button" tabindex="0" onclick="openProject('${p.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openProject('${p.id}')}" ><div class="project-top">${badge(p.status)}<small title="${dt(p.created_at)}">${rel(p.created_at)}</small></div><h3 title="${esc(p.name)}">${esc(p.name)}</h3><p>${esc(p.source_url)}</p><p class="project-sku">Артикул: <b>${p.sku?esc(p.sku):'—'}</b></p><div class="stage-row"><span>${STAGE[p.stage]||'Опрацювання'}</span><b>${p.progress||0}%</b></div>${progress(p.progress,['processing','queued'].includes(p.status),p.id)}<div class="project-style">${p.product_category?`<span class="cat-chip" onclick="event.stopPropagation();setFilter('category','${esc(catKey(p.product_category))}')" title="Показати цю категорію">${esc(p.product_category)}</span>`:''}Стиль: <b>${esc(p.style_name||'Не визначено')}</b></div><div class="project-meta"><span title="Текстова модель">${esc(p.text_model)}</span><span title="Вартість запуску">${money(p.estimated_cost)}</span><span title="Час виконання">${dur(p.duration_seconds)}</span></div></article>`).join('')||emptyProjects()}</section>${projectDialog()}${bulkImportDialogTpl()}`)}

function emptyProjects(){const hasFilters=state.search||state.status!=='all'||state.category!=='all';if(hasFilters&&state.projects.length)return `<div class="empty"><b>Нічого не знайдено</b><p>Змініть пошук або фільтри — проєкти є, але вони приховані поточними умовами.</p><button class="btn secondary" onclick="state.search='';state.status='all';state.category='all';render()">Скинути фільтри</button></div>`;return `<div class="empty"><b>Проєктів поки немає</b><p>Вставте посилання на сторінку товару або імпортуйте CSV — система збере факти й характеристики, підготує зображення та згенерує rich-контент кількома мовами.</p>${can('project.create')?`<div class="row empty-actions"><button class="btn secondary" onclick="openBulkImportDialog()">Імпорт CSV</button><button class="btn primary" onclick="newProject.showModal()">+ Створити перший проєкт</button></div>`:''}</div>`}
function options(items,selected){return items.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}
function dataList(id,items){return `<datalist id="${id}">${items.map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist>`}
const QUICK_LANGS=['ua','ru','pl'];
function languagePicker(selected=['ua','ru']){const chosen=new Set(selected||[]),custom=[...chosen].filter(x=>!QUICK_LANGS.includes(x)),extra=[...LANGUAGE_OPTIONS.filter(x=>!QUICK_LANGS.includes(x)),'bg','lt','lv','et','uk'];return `<fieldset class="language-fieldset"><legend>Мови результату</legend><div class="language-grid">${QUICK_LANGS.map(code=>`<label class="check"><input type="checkbox" name="language" value="${code}" ${chosen.has(code)?'checked':''}> ${LANG[code]}</label>`).join('')}</div><label class="custom-language">Додати інші мови <em>почніть вводити код: en, de, fr, es, bg, en-GB…</em><input name="custom_languages" value="${esc(custom.join(', '))}" placeholder="en, de, fr, es, it, cs…" list="extraLangs"></label>${dataList('extraLangs',extra)}</fieldset>`}
function collectLanguages(form){const values=[...form.querySelectorAll('[name=language]:checked')].map(x=>x.value),custom=String(new FormData(form).get('custom_languages')||'').split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean);return [...new Set([...values,...custom])]}
// Cost presets. The dialog had six knobs, of which four only moved the price.
// Simple mode folds those four into one choice; content decisions (URL, languages)
// stay visible in both modes because they are not a cost trade-off.
const PRESETS={
  eco:{name:'Економний',note:'Чернетка: подивитись на структуру й текст, не платячи за картинки',text:['gpt-5-mini','gpt-4.1-mini'],image:['gpt-image-1-mini','gemini-2.5-flash-image','gpt-image-1'],quality:'low'},
  std:{name:'Стандарт',note:'Робочий режим для більшості карток',text:['gpt-5-mini','gpt-4.1-mini'],image:['gemini-2.5-flash-image','gpt-image-1'],quality:'medium'},
  max:{name:'Максимум',note:'Флагманські товари, максимальна деталізація',text:['gpt-5','gpt-5-mini'],image:['gpt-image-2','gpt-image-1','gemini-3-pro-image-preview'],quality:'high'},
};
// Токени на ОДИН вихід (мова x формат): медіана останніх проєктів з /api/models
// (usage_profile), поки історії немає - стартові 7.5k/3.5k. Лише для кошторису
// в діалозі, списання іде за фактом. Зашиті 30k/14k брехали втричі на gpt-5.
const EST_TOKENS_PER_OUTPUT={input:7500,output:3500};
function estTokens(outputs){const p=state.models.usage_profile;const per=p&&p.input?p:EST_TOKENS_PER_OUTPUT;const n=Math.max(1,outputs||4);return {input:per.input*n,output:per.output*n}}
// Скільки виходів замовлено в діалозі: мови x формати; без форми - 2x2.
function dialogOutputs(form){form=form||document.querySelector('#newProject form');if(!form)return 4;const langs=collectLanguages(form).length||2,variants=form.querySelectorAll('[name=variant]:checked').length||2;return langs*variants}
const firstAvailable=(wanted,have,fallback)=>wanted.find(x=>(have||[]).includes(x))||fallback||(have||[])[0]||'';
function resolvePreset(key){const p=PRESETS[key]||PRESETS.std;return {key,...p,text_model:firstAvailable(p.text,state.models.text_models,state.models.default_text_model),image_model:firstAvailable(p.image,state.models.image_models,state.models.default_image_model)}}
function imageRate(model,quality){const row=(state.models.image_pricing||{})[model];if(!row)return 0.07;const v=row[quality];return Number(v!=null?v:(row.medium!=null?row.medium:0.07))}
function textRate(model,outputs){const row=(state.models.text_pricing||{})[model];const t=estTokens(outputs);if(!row)return (t.input*1.0+t.output*4.0)/1e6;return (t.input*Number(row.input||0)+t.output*Number(row.output||0))/1e6}
// Hero desktop + Hero mobile + Feature when both formats are on; two otherwise.
function estimateCost(textModel,imageModel,quality,variants,outputs){return imageRate(imageModel,quality)*(variants>1?3:2)+textRate(textModel,outputs)}
const estLabel=n=>`≈ $${n.toFixed(2)}`;
// render() rebuilds the whole document, so whatever the user typed into the dialog
// lives only in the DOM and dies with it. Carry their own input across the re-render.
// Model/quality/style are deliberately NOT carried: the preset owns those, and
// restoring them would undo the very click that triggered the re-render.
const KEEP_FIELDS=['source_url','style_id','custom_languages','custom_hero_url','custom_feature_url'];
const KEEP_CHECKS=['language','variant'];
function formSnapshot(form){if(!form)return null;const d={v:{},c:{}};for(const el of form.elements){if(!el.name)continue;if(KEEP_FIELDS.includes(el.name))d.v[el.name]=el.value;else if(KEEP_CHECKS.includes(el.name))d.c[el.name+'='+el.value]=el.checked}return d}
function formRestore(form,d){if(!form||!d)return;for(const el of form.elements){if(!el.name)continue;if(el.name in d.v){el.value=d.v[el.name];continue}const k=el.name+'='+el.value;if(k in d.c)el.checked=d.c[k]}}
function rerenderProjectDialog(){const dlg=document.getElementById('newProject'),open=dlg&&dlg.open,snap=formSnapshot(dlg&&dlg.querySelector('form'));render();const next=document.getElementById('newProject');if(open&&next){next.showModal();formRestore(next.querySelector('form'),snap);primeEstimate()}}
function setProjectMode(m){state.projectMode=m;localStorage.setItem('projectMode',m);rerenderProjectDialog()}


function updateEstimate(form){if(!form)return;refreshPresetCards(form);const out=document.getElementById('advEstimate');if(!out)return;const f=new FormData(form),variants=form.querySelectorAll('[name=variant]:checked').length;out.textContent=variants?estLabel(estimateCost(f.get('text_model'),pickedImageModel(f),f.get('image_quality'),variants,dialogOutputs(form))):'—'}
// Картки пресетів теж рахують від замовлених мов і форматів - перемальовуємо при зміні.
function estNote(){const p=state.models.usage_profile;return p&&p.calibrated?`Кошторис — за медіаною токенів ${p.projects} останніх проєктів, з урахуванням обраних мов і форматів.`:'Кошторис стартовий: історії проєктів ще замало для калібрування.'}
function refreshPresetCards(form){const grid=(form||document).querySelector('.preset-grid');if(!grid)return;const html=['eco','std','max'].map(presetCard).join('');if(grid.innerHTML!==html)grid.innerHTML=html}
function advancedFields(){return `<div class="form-grid"><label>Стиль<select name="style_id" onchange="renderProbe();renderFaqOption()">${productStyles().map(s=>`<option value="${s.id}" ${s.is_default?'selected':''} data-tag="${[s.is_default?'базовий':'',s.has_faq?'з FAQ':''].filter(Boolean).join(' · ')}">${esc(s.name)}</option>`).join('')}</select></label>${paletteSelect('',true)}<label><span class="lbl">Текстова модель ${hint('Модель для аналізу товару, генерації та перекладу тексту. Впливає на якість тексту й вартість токенів.')}</span><select name="text_model">${options([...new Set([state.models.default_text_model,...(state.models.text_models||[])].filter(Boolean))],state.models.default_text_model)}</select></label><label><span class="lbl">Модель зображень ${hint('Модель для генерації Hero/Feature зображень із реального фото товару. Разом із «Якість» визначає вартість зображень.')}</span>${imageModelField()}</label><label><span class="lbl">Якість ${hint('Деталізація й роздільність AI-зображень Hero та Feature і їх вартість. gpt-image-1: low ≈ $0.02, medium ≈ $0.07, high ≈ $0.19 за зображення. Діє лише коли стиль генерує зображення (є Hero/Feature промпти й знайдено фото товару).')}</span><select name="image_quality"><option>low</option><option selected>medium</option><option>high</option></select></label></div><div class="form-grid"><label>Власне Hero URL <em>необов’язково</em><input name="custom_hero_url" type="url" placeholder="https://..."></label><label>Власне Feature URL <em>необов’язково</em><input name="custom_feature_url" type="url" placeholder="https://..."></label></div><p class="est-line">Орієнтовна вартість запуску: <b id="advEstimate">—</b>${hint('Оцінка до старту: три зображення за обраною моделлю та якістю плюс типовий обсяг тексту. Фактична вартість рахується після завершення за реальними токенами.')}</p>`}
function presetCard(k){const p=resolvePreset(k),form=document.querySelector('#newProject form'),variants=form?(form.querySelectorAll('[name=variant]:checked').length||2):2,cost=estimateCost(p.text_model,p.image_model,p.quality,variants,dialogOutputs(form));const photo=IMAGE_MODEL_NOTES[p.image_model]||p.image_model;return `<button type="button" class="preset ${state.preset===k?'active':''}" data-k="${k}" onclick="pickPresetCard('${k}')"><span class="preset-top"><b>${esc(PRESETS[k].name)}</b><span class="preset-cost">${estLabel(cost)}</span></span><small>${esc(PRESETS[k].note)}</small><span class="preset-facts"><span><i>Фото</i>${esc(photo)}</span><span><i>Якість</i>${esc(p.quality)} · ${esc(p.image_model)}</span><span><i>Текст</i>${esc(p.text_model)}</span></span></button>`}
function simpleFields(){const p=resolvePreset(state.preset),def=(productStyles().find(x=>x.is_default)||productStyles()[0]||{}).id||'';return `<label>Стиль<select name="style_id" onchange="renderProbe();renderFaqOption()">${productStyles().map(x=>`<option value="${x.id}" ${x.id===def?'selected':''} data-tag="${[x.is_default?'базовий':'',x.has_faq?'з FAQ':''].filter(Boolean).join(' · ')}">${esc(x.name)}</option>`).join('')}</select></label>${paletteSelect('',true)}<fieldset><legend>Режим генерації</legend><div class="preset-grid">${['eco','std','max'].map(presetCard).join('')}</div><p class="est-line muted-note">Моделі та якість обирає пресет. Потрібен інший набір — перемкніть на «Розширений». ${estNote()}</p></fieldset><input type="hidden" name="text_model" value="${esc(p.text_model)}"><input type="hidden" name="image_model" value="${esc(p.image_model)}"><input type="hidden" name="image_quality" value="${esc(p.quality)}">`}
// Card click updates in place: a full render() would rebuild the dialog and eat
// whatever the operator already typed into it.
function pickPresetCard(k){state.preset=k;localStorage.setItem('projectPreset',k);const f=document.querySelector('#newProject form');if(!f)return;const p=resolvePreset(k);for(const [name,val] of [['text_model',p.text_model],['image_model',p.image_model],['image_quality',p.quality]]){const el=f.querySelector(`input[type=hidden][name=${name}]`);if(el)el.value=val}f.querySelectorAll('.preset-grid .preset').forEach(b=>b.classList.toggle('active',b.dataset.k===k))}

// Bulk import is deliberately a separate, two-step workflow. The first request
// only validates the CSV; the second sends the exact payload that was previewed,
// so changing a select cannot silently change a paid batch after confirmation.
const BULK_CSV_LIMIT=512*1024;
function freshBulkState(){return {csvText:'',fileName:'',fileBytes:0,busy:false,preview:null,result:null,snapshot:null,error:''}}
function bulkCreatedCount(result){return Number(result?.created_count??(result?.created||[]).length??0)}
function bulkValidCount(result){return Number(result?.valid_count??result?.ready_count??result?.accepted_count??(result?.rows||[]).length??0)}
function bulkErrorCount(result){return Number(result?.invalid_count??result?.error_count??(result?.errors||[]).length??0)}
function openBulkImportDialog(){state.bulk=freshBulkState();const dialog=document.getElementById('bulkProjectDialog'),form=dialog?.querySelector('form');if(!dialog||!form)return;form.reset();dialog.showModal();renderBulkImportUI()}
function bulkImportDialogClosed(){const changed=bulkCreatedCount(state.bulk?.result)>0;state.bulk=freshBulkState();if(changed)render()}
function downloadBulkTemplate(){const blob=new Blob(['\ufeffsource_url,name\n'],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rich-studio-products.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function readBulkCSV(input){const file=input.files?.[0];state.bulk.preview=null;state.bulk.result=null;state.bulk.snapshot=null;state.bulk.error='';state.bulk.csvText='';state.bulk.fileName='';state.bulk.fileBytes=0;if(!file){renderBulkImportUI();return}if(file.size>BULK_CSV_LIMIT){state.bulk.error='CSV більший за 512 КБ';input.value='';renderBulkImportUI();return}try{const data=await file.arrayBuffer(),text=new TextDecoder('utf-8',{fatal:true}).decode(data);state.bulk.csvText=text;state.bulk.fileName=file.name;state.bulk.fileBytes=file.size}catch{state.bulk.error='Не вдалося прочитати CSV як UTF-8. Збережіть файл у кодуванні UTF-8 і спробуйте знову.';input.value=''}renderBulkImportUI()}
function invalidateBulkPreview(){if(state.bulk.busy||(!state.bulk.preview&&!state.bulk.result&&!state.bulk.snapshot))return;state.bulk.preview=null;state.bulk.result=null;state.bulk.snapshot=null;state.bulk.error='';renderBulkImportUI()}
function editBulkImport(){if(state.bulk.busy)return;state.bulk.preview=null;state.bulk.result=null;state.bulk.snapshot=null;state.bulk.error='';renderBulkImportUI()}
function bulkPayload(form,validateOnly){const f=new FormData(form),preset=resolvePreset(String(f.get('bulk_preset')||'std')),variants=[...form.querySelectorAll('[name=bulk_variant]:checked')].map(x=>x.value),languages=[...form.querySelectorAll('[name=bulk_language]:checked')].map(x=>x.value),custom=String(f.get('bulk_custom_languages')||'').split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean);if(!state.bulk.csvText)throw Error('Оберіть CSV-файл');if(!variants.length)throw Error('Оберіть щонайменше один формат');const allLanguages=[...new Set([...languages,...custom])];if(!allLanguages.length)throw Error('Оберіть щонайменше одну мову');return {csv_text:state.bulk.csvText,style_id:f.get('bulk_style_id')||null,languages:allLanguages,variants,text_model:preset.text_model,image_model:preset.image_model,image_quality:preset.quality,skip_existing:f.get('bulk_skip_existing')==='on',validate_only:!!validateOnly}}
async function previewBulkImport(e){e.preventDefault();if(state.bulk.busy)return;let payload;try{payload=bulkPayload(e.currentTarget,true)}catch(x){state.bulk.error=x.message;renderBulkImportUI();return}state.bulk.busy=true;state.bulk.error='';renderBulkImportUI();try{const result=await api('/api/projects/bulk-import',{method:'POST',body:JSON.stringify(payload)}),batchId=String(result?.batch_id||'').trim();if(!batchId)throw Error('Сервер не повернув ідентифікатор пакета. Оновіть сторінку й повторіть перевірку CSV.');state.bulk.preview=result;state.bulk.snapshot=Object.freeze({...payload,languages:Object.freeze([...payload.languages]),variants:Object.freeze([...payload.variants]),validate_only:false,batch_id:batchId})}catch(x){state.bulk.error=x.message}finally{state.bulk.busy=false;renderBulkImportUI()}}
async function commitBulkImport(){if(state.bulk.busy||!state.bulk.snapshot)return;state.bulk.busy=true;state.bulk.error='';renderBulkImportUI();try{const payload=state.bulk.snapshot,result=await api('/api/projects/bulk-import',{method:'POST',body:JSON.stringify(payload)});state.bulk.result=result;state.bulk.snapshot=null;state.projects=await api('/api/projects').catch(()=>state.projects)}catch(x){state.bulk.error=x.message}finally{state.bulk.busy=false;renderBulkImportUI()}}
function bulkFileSummaryTpl(){if(!state.bulk.fileName)return '<span>Файл ще не вибрано</span>';return `<b>${esc(state.bulk.fileName)}</b><span>${fmtBytes(state.bulk.fileBytes)}</span>`}
function bulkErrorRowsTpl(errors){if(!errors?.length)return '';return `<div class="table-wrap bulk-table"><table><thead><tr><th>Рядок</th><th>URL / проєкт</th><th>Причина</th></tr></thead><tbody>${errors.map(x=>`<tr class="bulk-error-row"><td>${esc(x.row??'—')}</td><td>${esc(x.source_url||x.project_id||x.field||'—')}</td><td>${esc(x.error||x.reason||x.detail||x.message||x.code||'Помилка')}</td></tr>`).join('')}</tbody></table></div>`}
function bulkPreviewRowsTpl(rows){if(!rows?.length)return '';const list=(values,labels)=>Array.isArray(values)&&values.length?values.map(x=>esc(labels[x]||languageLabel(x))).join(', '):'—';return `<div class="table-wrap bulk-table"><table><thead><tr><th>Рядок</th><th>Назва</th><th>URL</th><th>Стиль</th><th>Мови</th><th>Формати</th><th>Оцінка</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.row??'—')}</td><td>${esc(x.name||'Визначиться автоматично')}</td><td class="bulk-url">${esc(x.source_url||'—')}</td><td>${esc(x.style||'—')}</td><td>${list(x.languages,{})}</td><td>${list(x.variants,VARIANT)}</td><td>${money(x.estimated_cost)}</td></tr>`).join('')}</tbody></table></div>`}
function bulkCreatedRowsTpl(rows,validRows=[]){if(!rows?.length)return '';const rowByUrl=new Map(validRows.map(x=>[x.source_url,x.row]));return `<div class="table-wrap bulk-table"><table><thead><tr><th>Рядок</th><th>Проєкт</th><th>URL</th><th>Статус</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(rowByUrl.get(p.source_url)??'—')}</td><td>${esc(p.name||'Визначення товару…')}</td><td class="bulk-url">${esc(p.source_url||'—')}</td><td>${badge(p.status||'queued')}</td></tr>`).join('')}</tbody></table></div>`}
function bulkEstimate(result){const direct=Number(result?.estimated_cost??result?.estimated_total);if(Number.isFinite(direct)&&direct>=0)return direct;const p=state.bulk.snapshot;if(!p)return 0;return bulkValidCount(result)*estimateCost(p.text_model,p.image_model,p.image_quality,(p.variants||[]).length)}
function bulkResultTpl(){if(state.bulk.error)return `<div class="bulk-alert bad"><b>Імпорт не виконано</b><p>${esc(state.bulk.error)}</p></div>`;if(state.bulk.busy)return '<div class="bulk-alert"><b>Опрацьовуємо CSV…</b><p>Не закривайте це вікно.</p></div>';const result=state.bulk.result;if(result){const created=bulkCreatedCount(result),queued=Number(result.queued_count||0),errors=bulkErrorCount(result),skipped=Number(result.skipped_count||0),dispatchPending=Number(result.dispatch_pending_count??result.dispatch_failed_count??0);return `<div class="bulk-summary"><div><small>Створено</small><b>${created}</b></div><div><small>У черзі</small><b>${queued}</b></div><div><small>Пропущено</small><b>${skipped}</b></div><div><small>Некоректних</small><b>${errors}</b></div><div><small>Очікує воркера</small><b>${dispatchPending}</b></div></div>${created?`<h3>Створені проєкти</h3>${bulkCreatedRowsTpl(result.projects||[],result.valid_rows||[])}`:''}${errors?`<h3>Некоректні рядки</h3>${bulkErrorRowsTpl(result.errors||[])}`:''}${skipped?`<h3>Пропущені рядки</h3>${bulkErrorRowsTpl(result.skipped||[])}`:''}${dispatchPending?`<h3>Автоматична повторна передача</h3>${bulkErrorRowsTpl(result.dispatch_failures||[])}`:''}`}const preview=state.bulk.preview;if(!preview)return '';const valid=bulkValidCount(preview),errors=bulkErrorCount(preview),skipped=Number(preview.skipped_count||0),cost=bulkEstimate(preview);return `<div class="bulk-summary"><div><small>Готово до запуску</small><b>${valid}</b></div><div><small>Некоректних</small><b>${errors}</b></div><div><small>Пропущено</small><b>${skipped}</b></div><div><small>Орієнтовна вартість</small><b>${estLabel(cost)}</b></div></div>${bulkPreviewRowsTpl(preview.valid_rows||[])}${errors?`<h3>Некоректні рядки</h3>${bulkErrorRowsTpl(preview.errors||[])}`:''}${skipped?`<h3>Пропущені рядки</h3>${bulkErrorRowsTpl(preview.skipped||[])}`:''}`}
function bulkActionsTpl(){if(state.bulk.busy)return '<button type="button" class="btn primary" disabled>Опрацювання…</button>';if(state.bulk.result)return '<button type="button" class="btn primary" onclick="document.getElementById(\'bulkProjectDialog\').close()">Готово</button>';if(state.bulk.preview){const valid=bulkValidCount(state.bulk.preview);return `<button type="button" class="btn secondary" onclick="editBulkImport()">Змінити файл або налаштування</button><button type="button" class="btn primary" onclick="commitBulkImport()" ${valid?'':'disabled'}>Створити проєкти · ${valid}</button>`}return `<button type="submit" class="btn primary" ${state.bulk.csvText?'':'disabled'}>Перевірити CSV</button>`}
function renderBulkImportUI(){const dialog=document.getElementById('bulkProjectDialog');if(!dialog)return;const file=document.getElementById('bulkFileSummary'),result=document.getElementById('bulkResult'),actions=document.getElementById('bulkActions'),close=document.getElementById('bulkClose');if(file)file.innerHTML=bulkFileSummaryTpl();if(result)result.innerHTML=bulkResultTpl();if(actions)actions.innerHTML=bulkActionsTpl();if(close)close.disabled=state.bulk.busy;const locked=state.bulk.busy||!!state.bulk.snapshot||!!state.bulk.result;dialog.querySelectorAll('[data-bulk-setting],#bulkCsvFile').forEach(el=>el.disabled=locked)}
function bulkImportDialogTpl(){const def=(productStyles().find(x=>x.is_default)||productStyles()[0]||{}).id||'',extra=[...LANGUAGE_OPTIONS.filter(x=>!QUICK_LANGS.includes(x)),'bg','lt','lv','et','uk'];return `<dialog id="bulkProjectDialog" aria-labelledby="bulkProjectDialogTitle" aria-describedby="bulkProjectDialogNote" oncancel="if(state.bulk.busy)event.preventDefault()" onclose="bulkImportDialogClosed()"><form onsubmit="previewBulkImport(event)" oninput="if(event.target.name!=='bulk_csv')invalidateBulkPreview()" onchange="if(event.target.name!=='bulk_csv')invalidateBulkPreview()"><div class="dialog-head"><div><small class="eyebrow">МАСОВЕ СТВОРЕННЯ</small><h2 id="bulkProjectDialogTitle">Імпорт проєктів із CSV</h2></div><button id="bulkClose" type="button" aria-label="Закрити" onclick="document.getElementById('bulkProjectDialog').close()">×</button></div><p id="bulkProjectDialogNote" class="dialog-note">Обов’язкова колонка: <code>source_url</code> (також можна <code>url</code>). Необов’язково: <code>name</code>, <code>style</code>, <code>languages</code>, <code>variants</code>, моделі, якість та Hero/Feature URL. Порожні клітинки успадковують налаштування нижче. До 100 товарів, файл до 512 КБ.</p><div class="bulk-file-row"><input id="bulkCsvFile" class="bulk-file-input" name="bulk_csv" type="file" accept=".csv,text/csv,text/plain" aria-label="Вибрати CSV-файл" aria-describedby="bulkFileSummary" data-bulk-setting onchange="readBulkCSV(this)"><button type="button" class="btn ghost" onclick="downloadBulkTemplate()">Завантажити шаблон</button><div id="bulkFileSummary" class="bulk-file-summary">${bulkFileSummaryTpl()}</div></div><div class="form-grid bulk-defaults"><label>Стиль за замовчуванням<select name="bulk_style_id" data-bulk-setting>${productStyles().map(x=>`<option value="${esc(x.id)}" ${x.id===def?'selected':''}>${esc(x.name)}${x.is_default?' · базовий':''}</option>`).join('')}</select></label><label>Режим генерації<select name="bulk_preset" data-bulk-setting>${Object.entries(PRESETS).map(([key,p])=>`<option value="${key}" ${key===state.preset?'selected':''}>${esc(p.name)} · ${esc(p.quality)}</option>`).join('')}</select></label></div><fieldset><legend>Мови результату</legend><div class="language-grid">${QUICK_LANGS.map(code=>`<label class="check"><input type="checkbox" name="bulk_language" value="${code}" ${['ua','ru'].includes(code)?'checked':''} data-bulk-setting> ${LANG[code]}</label>`).join('')}</div><label class="custom-language">Інші мови <em>через кому</em><input name="bulk_custom_languages" placeholder="en, de, fr…" list="bulkExtraLangs" data-bulk-setting></label>${dataList('bulkExtraLangs',extra)}</fieldset><fieldset><legend>Формати</legend><div class="language-grid"><label class="check"><input type="checkbox" name="bulk_variant" value="desktop" checked data-bulk-setting> Десктоп</label><label class="check"><input type="checkbox" name="bulk_variant" value="mobile" checked data-bulk-setting> Мобільна</label></div></fieldset><label class="check"><input type="checkbox" name="bulk_skip_existing" checked data-bulk-setting> Пропускати URL, для яких проєкт уже існує</label><div id="bulkResult" class="bulk-result" aria-live="polite">${bulkResultTpl()}</div><div id="bulkActions" class="bulk-actions">${bulkActionsTpl()}</div></form></dialog>`}
// Page probe: a free scrape that shows what the run will be built from before it
// starts. Vital for Showcase, whose layout is fuelled by real gallery frames.
function isShowcaseSelected(){const f=document.querySelector('#newProject form');const id=f?new FormData(f).get('style_id'):null;const st=state.styles.find(x=>x.id===id)||state.styles.find(x=>x.is_default)||state.styles[0];return /showcase/i.test(st?.name||'')}
async function probePage(){const f=document.querySelector('#newProject form');const url=(f&&new FormData(f).get('source_url')||'').trim();if(!url||!/^https?:\/\//.test(url))return;if(state.probe?.url===url||state.probeBusy)return;state.probeBusy=true;renderProbe();try{const r=await api('/api/projects/probe',{method:'POST',body:JSON.stringify({source_url:url})});state.probe={url,name:r.name,frames:(r.gallery||[]).map(u=>({url:u,on:true})),prior:r.prior?{...r.prior,images:r.prior.images.map(x=>({...x,on:true}))}:null,usePrior:!!r.prior}}catch(x){state.probe={url,error:x.message,frames:[]}}state.probeBusy=false;renderProbe()}
function frameError(i){const f=state.probe?.frames?.[i];if(!f||f.dead)return;f.dead=true;f.on=false;renderProbe()}
function togglePrior(i){const x=state.probe?.prior?.images?.[i];if(!x)return;x.on=!x.on;renderProbe()}
function clearRoleEverywhere(role){(state.uploads||[]).forEach(x=>{if(x.role===role)x.role=''});(state.probe?.frames||[]).forEach(x=>{if(x.role===role)x.role=''})}
function toggleFrame(i){const x=state.probe?.frames?.[i];if(!x)return;x.on=!x.on;if(!x.on)x.role='';renderProbe()}
function setFrameRole(i,role){const x=state.probe?.frames?.[i];if(!x||x.dead)return;if(x.role===role){x.role=''}else{clearRoleEverywhere(role);x.role=role;x.on=true}renderProbe();renderUploadGrid()}
function selectedFrames(){return (state.probe?.frames||[]).filter(x=>x.on&&!x.dead).map(x=>x.url)}
function probeBoxTpl(){if(state.probeBusy)return '<div class="probe-note">Читаємо сторінку…</div>';const pr=state.probe;if(!pr)return '<div class="probe-note muted-note">Вставте посилання — студія покаже назву товару і кадри галереї ще до запуску.</div>';if(pr.error)return `<div class="probe-note quality-bad">Не вдалося прочитати сторінку: ${esc(pr.error)}</div>`;const n=selectedFrames().length;const showcase=isShowcaseSelected();const verdict=showcase?(n>=4?`<span class="verdict ok">${n} кадрів — достатньо для Showcase</span>`:`<span class="verdict bad">${n} кадр(и) — для Showcase замало, макет виродиться. Краще ARTLINE Engineering</span>`):`<span class="verdict">${n} кадрів галереї</span>`;const PRIOR_LABEL={'hero-desktop-generated':'Hero Desktop','hero-mobile-generated':'Hero Mobile','feature-generated':'Feature','hero-custom':'Hero (власне)','feature-custom':'Feature (власне)'};const prior=pr.prior?`<div class="prior-strip"><label class="check"><input type="checkbox" ${pr.usePrior?'checked':''} onchange="state.probe.usePrior=this.checked;renderProbe()"> Використати готові AI-зображення з попередньої генерації <b>без витрат</b></label>${pr.usePrior?`<div class="prior-thumbs">${pr.prior.images.map((x,i)=>`<button type="button" class="prior-thumb ${x.on?'':'off'}" onclick="togglePrior(${i})" title="${x.on?'Клік — перегенерувати це зображення заново':'Клік — використати готове'}"><img src="${esc(x.url)}" alt="${esc(PRIOR_LABEL[x.label]||x.label)}" loading="lazy"><i>${esc(PRIOR_LABEL[x.label]||x.label)}</i></button>`).join('')}</div><p class="muted-note probe-note">Зібрано з усіх попередніх генерацій цього товару. Вимкнене зображення буде згенеровано заново (платно), решта копіюються без витрат.</p>`:''}</div>`:'';return `<div class="probe-head"><b>${esc(pr.name||'Без назви')}</b>${verdict}</div>${prior}<div class="probe-grid">${pr.frames.map((x,i)=>`<div class="uwrap"><button type="button" class="frame ${x.dead?'dead':''} ${x.on?'':'off'}" onclick="toggleFrame(${i})" title="${x.on?'Клік — виключити кадр':'Клік — повернути кадр'}"><img src="${esc(x.url)}" alt="Кадр ${i+1}" loading="lazy" onerror="frameError(${i})"></button>${x.dead?``:`<div class="role-row"><button type="button" class="role-chip ${x.role==='hero'?'active':''}" title="Цей кадр стане головним Hero без AI-генерації" onclick="setFrameRole(${i},'hero')">Hero</button><button type="button" class="role-chip ref ${x.role==='reference'?'active':''}" title="З цього кадру AI генерує Hero і Feature (за замовчуванням — перший придатний кадр)" onclick="setFrameRole(${i},'reference')">AI</button><button type="button" class="role-chip ${x.role==='feature'?'active':''}" title="Цей кадр стане Feature-блоком без AI-генерації" onclick="setFrameRole(${i},'feature')">Фіча</button></div>`}</div>`).join('')}</div><p class="muted-note probe-note">Клік по кадру виключає його з генерації. Вимкнені кадри не потраплять у Showcase.</p>`}
function renderProbe(){const box=document.getElementById('probeBox');if(box)box.innerHTML=probeBoxTpl()}
function selectedProjectStyle(){const f=document.querySelector('#newProject form');const id=f?new FormData(f).get('style_id'):null;return (state.styles||[]).find(x=>x.id===id)||(state.styles||[]).find(x=>x.is_default)||(state.styles||[])[0]||null}
function faqOptionTpl(){const st=selectedProjectStyle();if(!st||!st.has_faq)return '<em class="muted-note">Цей стиль не містить блока FAQ. Він є у Showcase (базовий, Dark, Promo) і в усіх Podium.</em>';const on=state.faqOn!==false;return `<label class="check"><input type="checkbox" name="faq" ${on?'checked':''} onchange="state.faqOn=this.checked"> Додати блок «Питання і відповіді» після фінального блока — 4-6 питань, які розгортаються кліком</label>`}
function renderFaqOption(){const box=document.getElementById('faqBox');if(box)box.innerHTML=faqOptionTpl()}
function uploadGridTpl(){const list=state.uploads||[];if(!list.length)return '<p class="muted-note">Ще нічого не завантажено — це необов\'язковий крок.</p>';return list.map((u,i)=>`<div class="uwrap"><div class="frame ${u.on?'':'off'}" title="${esc(u.name||'')}" onclick="toggleUpload(${i})">${u.busy?'<span class="upload-busy">…</span>':`<img src="${u.url}" loading="lazy" alt="">`}${state.uploads360?`<b class="frame-num">${i+1}</b>`:``}<button type="button" class="frame-x" aria-label="Прибрати" onclick="event.stopPropagation();removeUpload(${i})">×</button></div>${state.uploads360?``:`<div class="role-row"><button type="button" class="role-chip ${u.role==='hero'?'active':''}" title="Це фото стане головним Hero без AI-генерації" onclick="setUploadRole(${i},'hero')">Hero</button><button type="button" class="role-chip ref ${u.role==='reference'?'active':''}" title="З цього фото AI генерує Hero і Feature" onclick="setUploadRole(${i},'reference')">AI</button><button type="button" class="role-chip ${u.role==='feature'?'active':''}" title="Це фото стане Feature-блоком без AI-генерації" onclick="setUploadRole(${i},'feature')">Фіча</button></div>`}</div>`).join('')}
function renderUploadGrid(){const g=document.getElementById('uploadGrid');if(g)g.innerHTML=uploadGridTpl();const h=document.getElementById('upload360Hint');if(h)h.innerHTML=upload360HintTpl()}
function upload360HintTpl(){if(!state.uploads360)return '';const n=(state.uploads||[]).filter(u=>u.on&&u.url).length;if(n<2)return `<p class="critic-note">Для обертання потрібно щонайменше 2 кадри (зараз ${n}). Комфортний мінімум — 12.</p>`;if(n<12)return `<p class="muted-note">${n} кадр(ів): обертання буде помітно «стрибати». Рекомендовано 12–24 кадри по колу.</p>`;if(n<=48)return `<p class="muted-note">${n} кадр(ів) — цього вистачає для плавного обертання. Перевірте порядок за номерами на мініатюрах.</p>`;return `<p class="muted-note">${n} кадр(ів): сервер рівномірно відбере 48 (крок ~${(360/48).toFixed(1)}°) — дуже плавно і без зайвої ваги сторінки.</p>`}
function toggleUploads360(on){state.uploads360=on;if(on){const sel=document.querySelector('#newProject select[name=style_id]');const current=(state.styles||[]).find(x=>x.id===sel?.value);const rotational=current&&['ARTLINE Podium 3D 360','ARTLINE Podium 3D 360 Dark','ARTLINE Podium 3D Scroll'].includes(current.name);const s360=(state.styles||[]).find(x=>x.name==='ARTLINE Podium 3D 360');if(!rotational&&s360&&sel){sel.value=s360.id;if(typeof renderProbe==='function')renderProbe();toast('Стиль переключено на ARTLINE Podium 3D 360 (є ще варіант Scroll — обертання від прокрутки)')}}renderUploadGrid()}
function toggleUpload(i){const u=(state.uploads||[])[i];if(!u||u.busy)return;u.on=!u.on;if(!u.on)u.role='';renderUploadGrid()}
function setUploadRole(i,role){const list=state.uploads||[],u=list[i];if(!u||u.busy)return;if(u.role===role){u.role=''}else{clearRoleEverywhere(role);u.role=role;u.on=true}renderUploadGrid();renderProbe()}
function removeUpload(i){(state.uploads||[]).splice(i,1);renderUploadGrid()}
async function uploadRefs(input){const files=[...(input.files||[])];input.value='';const jobs=[];for(const file of files){if((state.uploads||[]).length+jobs.length>=200){toast('Максимум 200 фото',true);break}jobs.push({file,slot:{url:'',name:file.name,on:true,busy:true}})}
jobs.forEach(j=>state.uploads.push(j.slot));renderUploadGrid();
const one=async j=>{try{const r=await fetch('/api/uploads/image',{method:'POST',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':'application/octet-stream'},body:j.file});const d=await r.json().catch(()=>null);if(!r.ok)throw Error(d?.detail||`HTTP ${r.status}`);j.slot.url=d.url;j.slot.busy=false}catch(x){state.uploads=state.uploads.filter(s=>s!==j.slot);toast(`${j.file.name}: ${x.message}`,true)}renderUploadGrid()};
for(let i=0;i<jobs.length;i+=4)await Promise.all(jobs.slice(i,i+4).map(one))}
function projectDialog(){return `<dialog id="newProject"><form onsubmit="createProject(event)" oninput="updateEstimate(this.form||this)" onchange="updateEstimate(this.form||this)"><div class="dialog-head"><div><small class="eyebrow">НОВИЙ ПРОЄКТ</small><h2>Створити rich-контент</h2></div><button type="button" aria-label="Закрити" onclick="newProject.close()">×</button></div><div class="view-switch mode-switch" aria-label="Режим створення"><button type="button" class="${state.projectMode==='simple'?'active':''}" onclick="setProjectMode('simple')">Простий</button><button type="button" class="${state.projectMode==='advanced'?'active':''}" onclick="setProjectMode('advanced')">Розширений</button></div><label>Посилання на товар<input name="source_url" type="url" placeholder="https://artline.ua/..." required onblur="probePage()" onchange="probePage()"></label><div id="probeBox" class="probe-box">${probeBoxTpl()}</div><fieldset><legend>Додаткові фото (опційно)</legend><div class="upload-grid" id="uploadGrid">${uploadGridTpl()}</div><div class="row"><label class="btn secondary">Завантажити фото<input type="file" accept="image/*" multiple hidden onchange="uploadRefs(this)"></label><em class="muted-note">Клік по фото вмикає/вимикає його; кнопки Hero/Фіча призначають фото головним у відповідний блок — тоді AI його не генерує.</em></div><label class="check upload-360"><input type="checkbox" ${state.uploads360?'checked':''} onchange="toggleUploads360(this.checked)"> Це 360-серія: кадри зняті по колу (за порядком файлів) — стиль «ARTLINE Podium 3D 360» збере з них справжнє обертання</label><div id="upload360Hint">${upload360HintTpl()}</div><div style="display:none"</div></fieldset>${state.projectMode==='simple'?simpleFields():advancedFields()}<fieldset><legend>Блок FAQ</legend><div id="faqBox">${faqOptionTpl()}</div></fieldset><fieldset><legend>Відео (опційно)</legend><label>Посилання на YouTube-ролик<input name="video_url" type="url" placeholder="https://www.youtube.com/watch?v=… або https://youtu.be/…"></label><em class="muted-note">Є посилання — після фінального блока зʼявиться блок відео з превʼю, ролик грає прямо в річ-контенті. Немає — блока не буде.</em></fieldset>${languagePicker(['ua','ru'])}<fieldset><legend>Формати</legend><div class="language-grid"><label class="check"><input type="checkbox" name="variant" value="desktop" checked> Десктоп</label><label class="check"><input type="checkbox" name="variant" value="mobile" checked> Мобільна</label></div></fieldset><button class="btn primary">Створити й запустити</button></form></dialog>`}
// Native <datalist> popups are drawn by the browser and cannot be styled or grouped.
// A <select> with <optgroup> separates the providers and renders as a normal control;
// the "Інша модель" option keeps the old freedom to type a model ID that is not listed yet.
// What each image model is good at - shown right in the dropdown so choosing
// "the best one for photos" does not require remembering benchmark folklore.
const IMAGE_MODEL_NOTES={
 'gpt-image-1':'еталон деталей і логотипів',
 'gpt-image-1-mini':'чернетки, найдешевша',
 'gpt-image-2':'нове покоління OpenAI',
 'gemini-2.5-flash-image':'найкраще тримає вигляд товару, дешева',
 'gemini-3.1-flash-image-preview':'новіша Nano Banana, баланс якість/ціна',
 'gemini-3-pro-image-preview':'максимальна якість Gemini',
};
const RECOMMENDED_IMAGE_MODELS=['gemini-2.5-flash-image','gpt-image-1'];
const imageModelLabel=x=>`${RECOMMENDED_IMAGE_MODELS.includes(x)?'★ ':''}${x}${IMAGE_MODEL_NOTES[x]?` — ${IMAGE_MODEL_NOTES[x]}`:''}`;
function imageModelField(){const all=state.models.image_models||[],cur=state.models.default_image_model||'';const gem=all.filter(x=>x.startsWith('gemini-')),oai=all.filter(x=>!x.startsWith('gemini-'));const known=all.includes(cur),group=(label,items,disabled)=>items.length?`<optgroup label="${esc(label)}" ${disabled?'disabled':''}>${items.map(x=>`<option value="${esc(x)}" ${!disabled&&cur===x?'selected':''} ${disabled?'disabled':''}>${esc(imageModelLabel(x))}</option>`).join('')}</optgroup>`:'';const gemGroup=gem.length?group('Gemini · Nano Banana',gem):group('Gemini · Nano Banana — потрібен ключ (Налаштування)',state.models.gemini_models||[],true);return `<select name="image_model" onchange="toggleCustomModel(this)">${group('OpenAI',oai)}${gemGroup}<option value="__custom__" ${cur&&!known?'selected':''}>Інша модель…</option></select><input name="image_model_custom" class="custom-model" placeholder="напр. gemini-3-pro-image-preview" spellcheck="false" value="${cur&&!known?esc(cur):''}" ${cur&&!known?'':'hidden'}>`}
function toggleCustomModel(sel){const box=sel.parentElement.querySelector('.custom-model');if(!box)return;const on=sel.value==='__custom__';box.hidden=!on;if(on)box.focus()}
function pickedImageModel(f){const v=f.get('image_model');return v==='__custom__'?(f.get('image_model_custom')||'').trim():v}
async function createProject(e){e.preventDefault();const form=e.currentTarget,f=new FormData(form),paletteChoice=f.get('palette_id')||'',payload={source_url:f.get('source_url'),style_id:f.get('style_id')||null,palette_id:paletteChoice==='__photo__'?null:(paletteChoice||null),photo_palette:paletteChoice==='__photo__',text_model:f.get('text_model'),image_model:pickedImageModel(f),image_quality:f.get('image_quality'),custom_hero_url:(state.probe?.frames||[]).find(x=>x.role==='hero'&&x.on&&!x.dead)?.url||f.get('custom_hero_url')||'',custom_feature_url:(state.probe?.frames||[]).find(x=>x.role==='feature'&&x.on&&!x.dead)?.url||f.get('custom_feature_url')||'',languages:collectLanguages(form),variants:[...form.querySelectorAll('[name=variant]:checked')].map(x=>x.value),uploads:(state.uploads||[]).filter(u=>u.on&&u.url).map(u=>u.url),uploads_360:!!state.uploads360,faq:form.querySelector('[name=faq]')?form.querySelector('[name=faq]').checked:true,video_url:(f.get('video_url')||'').trim(),upload_hero:(state.uploads||[]).find(u=>u.role==='hero'&&u.url)?.url||'',upload_feature:(state.uploads||[]).find(u=>u.role==='feature'&&u.url)?.url||'',reference_url:(state.probe?.frames||[]).find(x=>x.role==='reference'&&x.on&&!x.dead)?.url||'',upload_reference:(state.uploads||[]).find(u=>u.role==='reference'&&u.url)?.url||''};try{if(state.probe&&!state.probe.error&&state.probe.url===payload.source_url){payload.gallery=selectedFrames();if(state.probe.prior&&state.probe.usePrior){const picked=state.probe.prior.images.filter(x=>x.on).map(x=>({project_id:x.project_id,label:x.label}));if(picked.length)payload.adopt_images=picked}}const p=await api('/api/projects',{method:'POST',body:JSON.stringify(payload)});newProject.close();toast('Проєкт додано до черги');await loadAll();await openProject(p.id)}catch(x){toast(x.message,true)}}
async function openProject(id){state.artifact=null;state.selected=await api(`/api/projects/${id}`);state.events=await api(`/api/projects/${id}/events`);state.tab='overview';selectArtifact(null,false);render()}
function selectArtifact(id,rerender=true){const list=state.selected?.artifacts||[],latest=[...list].sort((a,b)=>(b.version-a.version)||(new Date(b.created_at)-new Date(a.created_at)))[0]||null;state.artifact=(id&&list.find(x=>x.id===id))||state.artifact&&list.find(x=>x.id===state.artifact.id)||latest;if(rerender)render()}
function workspace(){const p=state.selected,limit=allowedTabs(),tabs=[['overview','Огляд'],['preview','Перегляд'],['html','HTML'],['text','Текст'],['links','Фото-посилання'],['info','Інфографіка'],['assets','Медіа'],['review','Перевірка'],['activity','Історія']].filter(t=>!limit||limit.includes(t[0]));if(limit&&!limit.includes(state.tab))state.tab=limit[0];const liveState=['processing','queued'].includes(p.status)?'run':p.status==='error'?'bad':['paused','cancelled','changes_requested'].includes(p.status)?'warn':'ok';shell(`<header class="project-head"><div><button class="link" onclick="state.selected=null;render()">← Усі проєкти</button><h1>${esc(p.name)}</h1><a class="source-link" href="${esc(p.source_url)}" target="_blank" rel="noopener noreferrer" title="Відкрити сторінку товару">${esc(p.source_url)} ↗</a></div><div>${projectActions(p)}</div></header><section class="live-card ${liveState}"><div class="live-title"><div><span class="pulse"></span><b>${STAGE[p.stage]||'Опрацювання проєкту'}</b></div><strong>${p.progress||0}%</strong></div>${progress(p.progress,['processing','queued'].includes(p.status),p.id)}<small>${STATUS[p.status]||p.status}</small></section>${p.status==='error'&&p.error?`<section class="error-island"><b>Помилка генерації</b><p>${esc(p.error)}</p>${['admin','editor'].includes(state.me?.role)?`<button class="btn secondary" onclick="queueAction('resume',this)">Спробувати ще раз</button>`:''}</section>`:''}<section class="metrics project-metrics"><div><small>Стиль</small><b>${esc(p.style_name||'Не визначено')}${p.photo_palette?`<small class="lifetime" title="Палітру знято з головного фото товару">палітра з фото ${['accent','dark_soft','light_soft'].map(k=>(p.palette_tokens||{})[k]?`<i style="display:inline-block;width:9px;height:9px;border-radius:50%;vertical-align:-1px;border:1px solid rgba(0,0,0,.15);background:${p.palette_tokens[k]}"></i>`:'').join('')}</small>`:''}</b></div><div><small>Текстова модель</small><b>${esc(p.text_model)}</b></div><div><small>Зображення</small><b>${esc(p.image_model)}</b></div><div><small>Вартість${(p.run_index||1)>1?` · прогін ${p.run_index}`:''}</small><b>${money(p.estimated_cost)}${p.lifetime_cost>p.estimated_cost+0.000001?`<small class="lifetime">разом за проєкт ${money(p.lifetime_cost)}</small>`:''}</b></div><div><small>Час</small><b id="liveTimer">${Number(p.duration_seconds||0).toFixed(0)} с</b></div><div><small>Токени</small><b>${(p.input_tokens||0)+(p.output_tokens||0)}</b></div></section><div class="tabs">${tabs.map(([k,v])=>`<button class="${state.tab===k?'active':''}" onclick="state.tab='${k}';render()">${v}</button>`).join('')}</div>${projectTab()}${rerunProjectDialogTpl()}${translateDialogTpl()}`);startProjectTimer();if(state.tab==='review')setTimeout(updateReviewUI,0);if(state.tab==='text')scheduleTabData(loadArtifactText);if(state.tab==='links')scheduleTabData(loadArtifactImages);if(state.tab==='info')scheduleTabData(loadIconLibrary);if(state.tab==='preview'||state.tab==='review')setTimeout(auditPreviewMedia,0)}
// Хвіст workspace() планує довантаження даних вкладки. Робити це на КОЖЕН
// рендер - запрошення до замкненого кола: досить, щоб завантажувач у кінці
// покликав render(), і пара крутиться нескінченно. DOM тоді перемальовується
// сотні разів на секунду, і клік просто не народжується - кнопка зникає між
// mousedown і mouseup (Playwright у цьому стані каже «element was detached
// from the DOM»). Саме так залипала вкладка «Інфографіка».
//
// Тому ДАНІ вкладки плануються один раз на пару «вкладка + версія». Патчери
// DOM (updateReviewUI, auditPreviewMedia) render() не кличуть і лишаються на
// кожному рендері - їм треба переписувати щойно створені вузли.
let tabDataKey='';
function scheduleTabData(fn){const key=`${state.selected?.id}|${state.tab}|${state.artifact?.id||''}`;if(tabDataKey===key)return;tabDataKey=key;setTimeout(fn,0)}

let projTimer;
function tickTimer(){const el=document.getElementById('liveTimer'),p=state.selected;if(!el||!p){clearInterval(projTimer);return}if(!['processing','queued'].includes(p.status)){el.textContent=`${Number(p.duration_seconds||0).toFixed(0)} с`;clearInterval(projTimer);return}const start=p.started_at?new Date(String(p.started_at).endsWith('Z')?p.started_at:p.started_at+'Z').getTime():Date.now();const sec=Math.max(0,(Date.now()-start)/1000);const m=Math.floor(sec/60),s=Math.floor(sec%60);el.textContent=m?`${m} хв ${s} с`:`${s} с`}
function startProjectTimer(){clearInterval(projTimer);tickTimer();const p=state.selected;if(p&&['processing','queued'].includes(p.status))projTimer=setInterval(tickTimer,1000)}
function projectTab(){if(state.tab==='preview')return preview();if(state.tab==='html')return htmlEditor();if(state.tab==='text')return textPanel();if(state.tab==='links')return imageLinksPanel();if(state.tab==='info')return infographicPanel();if(state.tab==='assets')return projectAssets();if(state.tab==='review')return reviewTab();if(state.tab==='activity')return activity();const p=state.selected;return `<section class="panel"><div class="sku-strip"><div><small>Артикул (SKU)</small><b>${p.sku?esc(p.sku):'—'}</b></div>${p.sku?`<button class="btn ghost" data-copy="${esc(p.sku)}" onclick="copyText(this)">Копіювати</button>`:''}</div><div class="summary-grid"><div><small>Категорія</small><h3>${esc(p.product_category||'Визначається')}</h3></div><div><small>Мови</small><h3>${p.languages.map(languageLabel).join(', ')}</h3></div><div><small>Формати</small><h3>${p.variants.map(x=>VARIANT[x]).join(', ')}</h3></div></div><h2>Останні етапи</h2><div class="timeline">${state.events.slice(0,8).map(e=>`<div><time>${dt(e.created_at)}</time><b>${STAGE[e.stage]||'Опрацювання'}</b><span>${esc(e.message)}</span></div>`).join('')||'<p>Подій поки немає.</p>'}</div></section>${runsPanel(p)}${costPanel(p)}`}
function runsPanel(p){const runs=(p.runs||[]).slice().reverse();if(runs.length<2)return '';const styleName=id=>(state.styles.find(s=>s.id===id)||{}).name||'';return `<section class="panel"><h2>Прогони</h2><div class="table-wrap"><table><thead><tr><th>Прогін</th><th>Завершено</th><th>Стиль і моделі</th><th>Токени</th><th>Зобр.</th><th>Вартість</th></tr></thead><tbody>${runs.map(r=>`<tr class="${r.index===p.run_index?'urow-active':''}"><td><b>#${r.index}</b>${r.index===p.run_index?' <small class="muted-note">поточний</small>':''}</td><td title="${dt(r.finished_at)}">${rel(r.finished_at)}</td><td>${esc(styleName(r.style_id))}<small>${esc(r.text_model||'')} · ${esc(r.image_model||'')}</small></td><td>${(r.input_tokens||0)+(r.output_tokens||0)}</td><td>${r.images||0}</td><td><b>${money(r.cost)}</b>${r.extra?`<small>+${money(r.extra)} доробки</small>`:''}</td></tr>`).join('')}</tbody></table></div><p class="muted-note">Разом за проєкт: <b>${money(p.lifetime_cost)}</b>. Перезапуск обнуляє лічильники поточного прогону, але історія витрат лишається тут.</p></section>`}
function costPanel(p){const b=p.cost_breakdown||{},rows=[['extract','Аналіз товару'],['content','Генерація тексту'],['images','Зображення']],has=rows.some(([k])=>b[k]);return `<section class="panel cost-panel"><h2>Вартість за етапами</h2>${has?`<table class="cost-table"><thead><tr><th>Етап</th><th>Обсяг</th><th>Вартість</th></tr></thead><tbody>${rows.map(([k,label])=>{const s=b[k]||{},detail=k==='images'?`${s.count||0} зобр.`:`${(s.input_tokens||0)+(s.output_tokens||0)} ток.`;return `<tr><td>${label}</td><td>${detail}</td><td>${money(s.cost)}</td></tr>`}).join('')}<tr class="cost-total"><td>Разом</td><td></td><td>${money(b.total||p.estimated_cost)}</td></tr></tbody></table>`:`<p class="muted-note">Деталізація з’явиться під час генерації. Поточна оцінка: <b>${money(p.estimated_cost)}</b>.</p>`}</section>`}
function artifactSelect(){return `<select onchange="selectArtifact(this.value)">${(state.selected.artifacts||[]).map(a=>`<option value="${a.id}" ${state.artifact?.id===a.id?'selected':''}>${a.fallback_reason?'⚠ ':''}${languageLabel(a.language)} · ${VARIANT[a.variant]} · v${a.version}${a.run_index?` · прогін ${a.run_index}`:''}${a.fallback_reason?' · аварійний шаблон':''}</option>`).join('')}</select>`}
function stripVideoEmbedsForPreview(html){return String(html||'').replace(/<iframe[^>]*youtube-nocookie\.com\/embed\/[^>]*><\/iframe>/g,'')}
function previewDocument(html){html=stripVideoEmbedsForPreview(html);return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="${location.origin}/"><style>html,body{margin:0;min-height:100%;background:#fff;color:#101010}body{padding:0;font-family:Roboto,Inter,Arial,sans-serif}</style></head><body>${html}</body></html>`}
function openPreview(){if(!state.artifact?.html)return toast('Немає результату для перегляду',true);const win=window.open('about:blank','_blank');if(!win)return toast('Браузер заблокував нову вкладку',true);win.document.open();win.document.write(previewDocument(state.artifact.html));win.document.close()}
// Media health audit: HEADs every /media URL the current artifact references and
// says out loud whether invisible images are missing files (storage bug) or
// present files that fail to render (preview bug). Ends the guessing.
async function auditPreviewMedia(){const a=state.artifact;if(!a)return;const urls=[...new Set([...(a.html.match(/\/media\/[A-Za-z0-9\-]+\/[A-Za-z0-9._\-]+(?:\?t=[A-Za-z0-9]+)?/g)||[])])].slice(0,8);const key=a.language+a.variant+a.version;if(state.mediaAudit?.key===key)return renderMediaAudit();if(!urls.length){state.mediaAudit={key,results:[]};return renderMediaAudit()}
// HTTP 200 proves nothing: a zero-byte or truncated file answers 200 and renders
// as nothing. Decode each image for real and report its true dimensions.
const results=await Promise.all(urls.map(u=>new Promise(resolve=>{const img=new Image();img.onload=()=>resolve({url:u,ok:img.naturalWidth>0,w:img.naturalWidth,h:img.naturalHeight});img.onerror=()=>resolve({url:u,ok:false,w:0,h:0});img.src=u})));state.mediaAudit={key,results};renderMediaAudit()}
function renderMediaAudit(){const box=document.getElementById('mediaAudit');if(!box)return;const audit=state.mediaAudit;if(!audit||!audit.results.length){box.innerHTML='';return}const bad=audit.results.filter(x=>!x.ok);const name=u=>u.split('/').pop();box.innerHTML=bad.length?`<div class="media-audit bad"><b>Зображення не завантажуються (${bad.length} із ${audit.results.length}):</b> ${bad.map(x=>`<code>${esc(name(x.url))}</code>`).join(' ')} — файл порожній або пошкоджений. Перегенеруйте зображення.</div>`:`<div class="media-audit ok"><b>Зображення справні:</b> ${audit.results.map(x=>`<code>${esc(name(x.url))} ${x.w}×${x.h}</code>`).join(' ')}. Якщо на сторінці їх не видно — це верстка стилю, а не файли.</div>`}
function fallbackBanner(){const a=state.artifact;if(!a?.fallback_reason)return '';return `<div class="fallback-banner"><b>Це не обраний стиль.</b> AI-генерацію цієї сторінки не вдалося виконати, тому показано аварійний шаблон. Публікувати не можна — перегенеруйте проєкт.<span>Причина: ${esc(a.fallback_reason)}</span></div>`}
function preview(){if(!state.artifact)return'<div class="empty">Результат ще не створено.</div>';const variant=state.artifact.variant==='mobile'?'mobile':'desktop';return `<section class="panel preview-panel"><div class="panel-tools">${artifactSelect()}<div class="preview-hint">${variant==='mobile'?'Мобільне полотно · 480 px':'Десктопне полотно · 1240 px'}</div>${state.me?.shots_enabled&&state.artifact?`<button class="btn secondary" onclick="downloadBlocks(this)" title="Кожен блок цієї сторінки окремим PNG (для маркетплейсів, що не приймають HTML)">Блоки в PNG</button>`:''}${state.me?.shots_enabled&&state.artifact?`<button class="btn secondary" onclick="downloadAllBlocks(this)" title="Усі варіанти цієї версії (усі мови й формати) блоками в PNG, одним архівом">Всі варіанти в PNG</button>`:''}<button class="btn secondary" onclick="openPreview()">Відкрити окремо</button></div>${fallbackBanner()}<div id="mediaAudit"></div><div class="preview-stage"><div class="preview-canvas ${variant}"><iframe title="Попередній перегляд rich-контенту" sandbox="allow-same-origin" scrolling="yes" srcdoc="${esc(previewDocument(state.artifact.html))}"></iframe></div></div></section>`}
function htmlEditor(){if(!state.artifact)return'<div class="empty">HTML ще не створено.</div>';return `<section class="panel"><div class="panel-tools">${artifactSelect()}<button class="btn primary" onclick="saveHtml(this)">Зберегти нову версію</button></div><textarea id="htmlEditor" class="code">${esc(state.artifact.html)}</textarea></section>`}
function textPanel(){if(!state.artifact)return'<div class="empty">Сторінку ще не створено.</div>';const t=state.artifactText?.[state.artifact.id];return `<section class="panel"><div class="panel-tools">${artifactSelect()}<button class="btn secondary" data-copy="${t?esc(t.text):''}" onclick="copyText(this)" ${t?'':'disabled'}>Копіювати текст</button><button class="btn primary" onclick="downloadArtifactText()" ${t?'':'disabled'}>Завантажити .txt</button></div><p class="muted-note">Той самий текст, що й у rich-сторінці, але без розмітки — для Allegro та інших майданчиків, які не приймають HTML. Рахується з готової версії: без перегенерації, без витрат і доступно для будь-якого прогону.${t?` <b>${t.chars} символів · ${t.words} слів</b>`:''}</p><textarea id="plainText" class="code" readonly>${t?esc(t.text):'Готуємо текст…'}</textarea></section>`}
async function loadArtifactText(){const a=state.artifact;if(!a)return;state.artifactText=state.artifactText||{};if(state.artifactText[a.id])return;try{const d=await api(`/api/artifacts/${a.id}/text`);state.artifactText[a.id]=d;if(state.tab==='text')render()}catch(x){toast(x.message,true)}}
function downloadArtifactText(){const a=state.artifact,t=state.artifactText?.[a?.id];if(!t)return;const blob=new Blob([t.text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`rich-${t.language}-${t.variant}-v${t.version}.txt`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Текст збережено')}
const LINK_PLACE={img:'у &lt;img&gt;',background:'у фоні',srcset:'у srcset'};
function imageLinksPanel(){if(!state.artifact)return'<div class="empty">Сторінку ще не створено.</div>';const data=state.artifactImages?.[state.artifact.id];if(!data)return `<section class="panel"><div class="panel-tools">${artifactSelect()}</div><p class="muted-note">Читаємо посилання зі сторінки…</p></section>`;const rows=data.images||[];const local=rows.filter(x=>x.local).length;return `<section class="panel"><div class="panel-tools">${artifactSelect()}<button class="btn secondary" data-copy="${esc(rows.filter(x=>x.local).map(x=>location.origin+x.url).join('\n'))}" onclick="copyText(this)">Копіювати адреси студії</button><button class="btn primary" onclick="applyImageLinks(this)">Замінити посилання</button></div><p class="muted-note">Тут видно КОЖНЕ посилання на зображення цієї сторінки і скільки разів воно в ній зустрічається. Завантажте кадр на сервер магазину, вставте нову адресу — і студія підмінить її скрізь сама, зберігши нову версію сторінки. Мапа запамʼятовується: після наступного прогону поля вже будуть заповнені. Знайдено ${rows.length} посилань, з них ${local} лежать у студії.</p><label class="check"><input type="checkbox" id="linkScopeAll" checked> Замінити в усіх свіжих версіях проєкту (усі мови та формати), а не лише в цій</label><div class="link-rows">${rows.map((x,i)=>`<article class="link-row"><div class="link-thumb"><img src="${esc(x.url)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none';this.parentElement.classList.add('media-image-broken');this.parentElement.insertAdjacentHTML('beforeend','<span>кадр не вантажиться</span>')"></div><div class="link-meta"><b>${esc(x.label?(ASSET_LABEL[x.label]||x.label):(x.local?'Зображення студії':'Зовнішнє посилання'))}</b><small>${x.count}× ${x.places.map(pl=>LINK_PLACE[pl]||pl).join(', ')}${x.width&&x.height?` · ${x.width}×${x.height}`:''}</small><div class="row"><input value="${esc(x.url)}" readonly><button class="btn ghost" data-copy="${esc(x.local?location.origin+x.url:x.url)}" onclick="copyText(this)">Копіювати</button>${x.local?`<a class="btn ghost" href="${esc(x.url)}" download>Завантажити</a>`:''}</div></div><div class="link-new"><label>Нова адреса на сервері магазину<input data-old="${esc(x.canonical)}" class="link-target" value="${esc(x.mapped_to||'')}" placeholder="https://artline.ua/upload/... або /upload/..."></label></div></article>`).join('')||'<div class="empty">На сторінці немає зображень.</div>'}</div></section>`}
async function loadArtifactImages(force){const a=state.artifact;if(!a)return;state.artifactImages=state.artifactImages||{};if(state.artifactImages[a.id]&&!force)return;try{const d=await api(`/api/artifacts/${a.id}/images`);state.artifactImages[a.id]=d;if(state.tab==='links')render()}catch(x){toast(x.message,true)}}
async function applyImageLinks(button){const a=state.artifact;if(!a)return;const replacements={};document.querySelectorAll('.link-target').forEach(input=>{const value=input.value.trim();if(value)replacements[input.dataset.old]=value});if(!Object.keys(replacements).length)return toast('Впишіть хоча б одну нову адресу',true);const scope=document.getElementById('linkScopeAll')?.checked?'project':'artifact';const original=button?.textContent;if(button){button.disabled=true;button.textContent='Заміна…'}try{const d=await api(`/api/artifacts/${a.id}/images`,{method:'PUT',body:JSON.stringify({replacements,scope,remember:true})});await refreshSelected();state.artifactImages={};const mine=(d.artifacts||[]).find(x=>x.language===a.language&&x.variant===a.variant);if(mine)state.artifact=(state.selected.artifacts||[]).find(x=>x.id===mine.id)||state.artifact;toast(`Замінено ${d.swapped} посилань · нових версій: ${(d.artifacts||[]).length}`);render();setTimeout(()=>loadArtifactImages(true),0)}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
const IG_TEMPLATES=[['icons-left','Іконки зліва, фото справа'],['icons-right','Фото зліва, іконки справа'],['callouts','Виноски навколо фото'],['strip-bottom','Стрічка під фото']];
function igState(){state.ig=state.ig||{template:'icons-left',title:'',photo:'',logo:'',brand:'ARTLINE',name:'',facts:'',accent:'',items:[{icon:'',title:'',text:''},{icon:'',title:'',text:''},{icon:'',title:'',text:''},{icon:'',title:'',text:''}],result:null};return state.ig}
// Шапка складається з ДВОХ незалежних речей: знака і словесної назви.
// «без знака» прибирало лише картинку - і замість неї виїжджав текст
// ARTLINE, а щоб зняти і його, треба було здогадатись очистити поле «Назва».
// Тому стан шапки тепер один явний вибір із трьох, а не дві приховані ручки.
function igBrandMode(g){if(g.logo==='none'&&!(g.brand||'').trim())return 'off';if(g.logo==='none')return 'text';return 'logo'}
function igSetBrandMode(mode){const g=igState();if(mode==='off'){g.logo='none';g.brand=''}else if(mode==='text'){g.logo='none';if(!(g.brand||'').trim())g.brand='ARTLINE'}else{g.logo='';if(!(g.brand||'').trim())g.brand='ARTLINE'}render()}
function igBrandBlock(g){const mode=igBrandMode(g);const opt=(v,l,t)=>`<button type="button" class="${mode===v&&!(v==='logo'&&g.logo&&g.logo!=='none')?'on':''}" onclick="igSetBrandMode('${v}')" title="${t}">${l}</button>`;
return `<fieldset class="ig-brand"><legend>Бренд у шапці</legend>
<div class="ig-logos">${opt('logo','Знак ARTLINE','Фірмовий лого-напис із сайту; він займає місце назви, тому текст поруч не друкується')}${opt('text','Тільки назва текстом','Без картинки, назва друкується шрифтом')}${opt('off','Без бренду','Шапка лишається тільки із заголовком')}</div>
${mode==='off'?'<p class="muted-note">Шапка без знака й без назви — лишиться тільки заголовок картинки.</p>':`<div class="row" style="margin-top:10px"><label style="flex:1">Назва<input value="${esc(g.brand)}" oninput="igSet('brand',this.value)" placeholder="ARTLINE, QUBE, DEYE…"></label><label style="flex:0 0 auto">Свій логотип<input type="file" accept=".svg,image/svg+xml,image/png,image/jpeg,image/webp" onchange="igLogoUpload(this)"></label></div>
<div class="ig-logos">${(state.igLogos||[]).map(l=>`<span class="ig-logo ${g.logo===l.url?'on':''}"><img src="${esc(l.url)}" alt="${esc(l.name)}" title="${esc(l.name)}" onclick="igSet('logo','${esc(l.url)}')"><b onclick="igLogoDelete('${esc(l.url)}')" title="Прибрати з бібліотеки">×</b></span>`).join('')}</div>
<p class="muted-note">SVG приймається: браузер перетворює його на PNG із прозорістю. Широкий логотип-напис займає місце назви — текст поруч тоді не друкується. Одноколірний знак підганяється під колір полотна; кольоровий знак партнера лишається у своїх кольорах.</p>`}</fieldset>`}
function igItemsBlock(g,icons){return `<div class="ig-items">${g.items.map((it,i)=>`<article class="ig-item"><div class="ig-icon" onclick="igOpenIcons(${i})" title="Обрати іконку з бібліотеки">${it.icon?`<img src="${esc(igIconSrc(it.icon))}" alt="">`:'<span>обрати іконку</span>'}</div><div><label>Іконка<span class="ig-iconrow"><input list="igIcons" value="${esc(it.icon)}" oninput="igItem(${i},'icon',this.value)" placeholder="почніть вводити назву"><button type="button" class="btn ghost" onclick="igOpenIcons(${i})">Бібліотека</button></span></label><label>Підпис<input value="${esc(it.title)}" oninput="igItem(${i},'title',this.value)"></label><label>Уточнення <em>необовʼязково</em><input value="${esc(it.text)}" oninput="igItem(${i},'text',this.value)"></label></div></article>`).join('')}
<datalist id="igIcons">${icons.map(x=>`<option value="${esc(x.slug)}">${esc(x.name)}</option>`).join('')}</datalist>
<div class="row"><button class="btn ghost" onclick="igAdd()" ${g.items.length>=6?'disabled':''}>+ Пункт</button><button class="btn ghost" onclick="igRemove()" ${g.items.length<=1?'disabled':''}>− Пункт</button></div></div>`}
function infographicPanel(){if(!state.selected)return'<div class="empty">Проєкт не обрано.</div>';const g=igState(),icons=state.igIcons||[],gallery=(state.selected?.assets||[]).filter(a=>a.url&&!String(a.label||'').startsWith('infographic'));
return `<section class="panel"><div class="panel-tools"><select onchange="igSet('template',this.value)">${IG_TEMPLATES.map(([v,l])=>`<option value="${v}" ${g.template===v?'selected':''}>${l}</option>`).join('')}</select><button class="btn secondary" onclick="igSuggest(this)" title="Платно: модель прочитає факти товару, напише підписи і підбере іконки">Запропонувати підписи · платно</button><button class="btn primary" onclick="igRender(this)">Зібрати картинку</button></div>
<p class="muted-note">Картинка 2000×2000 WEBP для галереї магазину: фото товару, підписи і фірмові іконки (${icons.length} у бібліотеці). Збірка безкоштовна — перезбирати можна скільки завгодно; платний лише підбір підписів моделлю. Потрібна інфографіка ДО появи картки товару — розділ «Інфографіка» в лівому меню.</p>
<div class="ig-grid"><div><label>Заголовок<input value="${esc(g.title)}" oninput="igSet('title',this.value)" placeholder="Відмінне охолодження компонентів"></label>
${igBrandBlock(g)}
${igColorBlock()}
<label>Фото товару<input id="igPhotoUrl" value="${esc(g.photo)}" oninput="igSet('photo',this.value)" placeholder="/media/... або https://..."></label>
<div class="row"><input type="file" accept="image/*" id="igPhotoFile" onchange="igUpload(this)"><span class="muted-note">або оберіть кадр із галереї нижче</span></div>
<div class="ig-gallery">${gallery.slice(0,12).map(a=>`<img src="${esc(a.url)}" alt="" loading="lazy" class="${g.photo===a.url?'on':''}" onclick="igSet('photo','${esc(a.url)}')">`).join('')||'<span class="muted-note">Кадрів у проєкті ще немає</span>'}</div>
${g.result?`<div class="ig-result"><b>Готово:</b> ${g.result.label||''} · ${Math.round(g.result.bytes/1024)} КБ<div><img src="${esc(g.result.url)}" alt="інфографіка"></div><div class="row"><a class="btn secondary" href="${esc(g.result.url)}" download>Завантажити WEBP</a><a class="btn ghost" href="${esc(g.result.url)}" target="_blank" rel="noopener">Відкрити</a></div></div>`:''}</div>
<div>${igItemsBlock(g,icons)}</div></div></section>
<section class="panel"><h2>Історія генерацій</h2><p class="muted-note">Кожен запис можна відновити у форму й перезібрати — збірка безкоштовна.</p>${igHistoryTpl()}</section>${igIconPickerTpl()}`}
function igSet(key,value){igState()[key]=value;render()}
function igItem(i,key,value){const g=igState();if(g.items[i]){g.items[i][key]=value;if(key!=='icon')return;render()}}
// ————— Видима бібліотека іконок —————
// Було: лише <datalist> на полі вводу. 174 іконки формально «є», але побачити
// їх не можна - треба вгадати slug і почати його друкувати. Тепер сітка з
// пошуком: іконку видно й обирають кліком, а поле вводу лишається для тих,
// хто памʼятає назву.
// Колір іконок: явно вибраний -> акцент палітри проєкту (в тому числі знятий
// з фото) -> фірмовий циан. Той самий порядок, що й на сервері, тому превью
// у формі показує РІВНО те, що потрапить у WEBP.
function igAccent(){const g=igState();if(g.accent)return g.accent;const p=state.selected;const own=p?.palette_tokens?.accent;if(own)return own;const st=(state.styles||[]).find(x=>x.id===p?.style_id);return st?.palette?.accent||'#19BCC9'}
function igIconSrc(slug){const c=igAccent().replace('#','');return `/api/infographic/icon/${encodeURIComponent(slug)}.png?c=${c}`}
function igColorBlock(){const g=igState(),auto=!g.accent,now=igAccent();return `<fieldset class="ig-brand"><legend>Колір іконок</legend><div class="row" style="align-items:center;gap:10px;flex-wrap:wrap"><input type="color" value="${esc(now)}" oninput="igSet('accent',this.value.toUpperCase())" title="Колір іконок і виносок"><code>${esc(now)}</code>${auto?'<span class="muted-note">із палітри проєкту</span>':`<button type="button" class="btn ghost" onclick="igSet('accent','')">Повернути з палітри</button>`}</div><p class="muted-note">Іконки перефарбовуються поворотом відтінку: градієнт і згладжування країв лишаються, змінюється тільки колір.</p></fieldset>`}
async function igIconUpload(input){const file=input.files?.[0];if(!file)return;try{const isSvg=/svg/i.test(file.type)||/\.svg$/i.test(file.name);const blob=isSvg?await svgToPng(file):file;if(!blob)throw Error('Порожній файл');const name=file.name.replace(/\.[^.]+$/,'');const r=await fetch(`/api/infographic/icon?name=${encodeURIComponent(name)}`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':'image/png'},body:blob});const d=await r.json();if(!r.ok)throw Error(d?.detail||'Не вдалося завантажити іконку');state.igIcons=[d,...(state.igIcons||[])];if(state.igPick)state.igPick.q='';toast('Іконку додано до бібліотеки');render();setTimeout(()=>{const dlg=document.getElementById('igIconPicker');if(dlg&&!dlg.open)dlg.showModal()},0)}catch(x){toast(x.message,true)}finally{input.value=''}}
async function igIconDelete(slug){if(!confirm('Прибрати цю іконку з бібліотеки? Уже зібрані картинки не зміняться.'))return;try{await api(`/api/infographic/icon?slug=${encodeURIComponent(slug)}`,{method:'DELETE'});state.igIcons=(state.igIcons||[]).filter(x=>x.slug!==slug);const g=igState();g.items.forEach(it=>{if(it.icon===slug)it.icon=''});toast('Іконку прибрано');render();setTimeout(()=>{const dlg=document.getElementById('igIconPicker');if(dlg&&!dlg.open)dlg.showModal()},0)}catch(x){toast(x.message,true)}}

function igOpenIcons(index){state.igPick={index,q:''};render();setTimeout(()=>{const d=document.getElementById('igIconPicker');if(d&&!d.open)d.showModal();const f=document.getElementById('igIconSearch');if(f)f.focus()},0)}
function igIconSearch(value){if(state.igPick)state.igPick.q=value;const box=document.getElementById('igIconGrid');if(box)box.innerHTML=igIconGridTpl()}
function igIconMatches(){const q=(state.igPick?.q||'').trim().toLowerCase();const all=state.igIcons||[];if(!q)return all;const words=q.split(/\s+/);return all.filter(x=>{const hay=`${x.name} ${x.slug}`.toLowerCase();return words.every(w=>hay.includes(w))})}
function igIconGridTpl(){const rows=igIconMatches();if(!rows.length)return '<p class="muted-note">Нічого не знайшлось. Спробуйте іншу назву або завантажте свою іконку.</p>';return rows.map(x=>`<span class="ig-pickwrap"><button type="button" class="ig-pick" onclick="igPickIcon('${esc(x.slug)}')" title="${esc(x.name)}"><img src="${esc(igIconSrc(x.slug))}" alt="" loading="lazy"><span>${esc(x.name)}</span></button>${x.custom?`<b class="ig-pickdel" onclick="event.stopPropagation();igIconDelete('${esc(x.slug)}')" title="Прибрати з бібліотеки">×</b>`:''}</span>`).join('')}
function igPickIcon(slug){const pick=state.igPick;if(pick){const g=igState();if(g.items[pick.index])g.items[pick.index].icon=slug}igCloseIcons()}
function igCloseIcons(){const d=document.getElementById('igIconPicker');if(d?.open)d.close();state.igPick=null;render()}
function igIconPickerTpl(){if(!state.igPick)return '';const total=(state.igIcons||[]).length;return `<dialog id="igIconPicker" onclose="state.igPick=null"><div class="dialog-head"><div><small class="eyebrow">БІБЛІОТЕКА ІКОНОК</small><h2>Оберіть іконку · ${total} у бібліотеці</h2></div><button type="button" aria-label="Закрити" onclick="igCloseIcons()">×</button></div><label>Пошук<input id="igIconSearch" value="${esc(state.igPick.q||'')}" oninput="igIconSearch(this.value)" placeholder="живлення, гарантія, wi-fi…"></label><div class="ig-picker" id="igIconGrid">${igIconGridTpl()}</div><div class="row" style="flex-wrap:wrap;gap:10px;align-items:center"><button type="button" class="btn ghost" onclick="igPickIcon('')">Без іконки</button><label class="btn secondary" style="cursor:pointer;margin:0">Завантажити свою<input type="file" accept=".svg,image/svg+xml,image/png,image/webp,image/jpeg" style="display:none" onchange="igIconUpload(this)"></label><span class="muted-note">SVG приймається — браузер перетворить його на PNG. Іконка приводиться до вигляду бібліотеки й далі фарбується разом з рештою.</span></div></dialog>`}

// ————— Історія генерацій —————
// Кожна зібрана інфографіка лягає в медіатеку проєкту як ассет
// infographic-N разом із метаданими (макет, підписи, фото, логотип). Тому
// історія - не просто стрічка картинок: будь-який рядок можна ВІДНОВИТИ у
// форму й перезібрати. Збірка безкоштовна, тож це найдешевший шлях до правки.
function igHistoryRows(){return (state.selected?.assets||[]).filter(a=>String(a.label||'').startsWith('infographic')).slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))}
function igHistoryTpl(){const rows=igHistoryRows();if(!rows.length)return '<p class="muted-note">Історія порожня — зберіть першу картинку, і вона зʼявиться тут.</p>';const label=v=>(IG_TEMPLATES.find(t=>t[0]===v)||[,v])[1];return `<div class="ig-lib">${rows.map(a=>`<figure><img src="${esc(a.url)}" alt="${esc(a.label)}" loading="lazy"><figcaption><b>${esc(a.label)}</b><span>${esc(label(a.metadata?.template||''))}${(a.metadata?.items||[]).length?` · ${a.metadata.items.length} підписів`:''}</span><span>${dt(a.created_at)}</span><span class="row"><a href="${esc(a.url)}" download>завантажити</a> · <b class="link-like" onclick="igRestore('${esc(a.id)}')">відновити</b></span></figcaption></figure>`).join('')}</div>`}
function igRestore(id){const a=igHistoryRows().find(x=>x.id===id);if(!a)return toast('Запис не знайдено',true);const m=a.metadata||{};const g=igState();if(m.template)g.template=m.template;if(m.photo_url)g.photo=m.photo_url;if(m.logo_url!==undefined)g.logo=m.logo_url;if(m.brand)g.brand=m.brand;if(m.accent!==undefined)g.accent=m.accent;if(a.prompt)g.title=a.prompt;if(Array.isArray(m.items)&&m.items.length)g.items=m.items.map(x=>({icon:x.icon||'',title:x.title||'',text:x.text||''}));g.result={url:a.url,bytes:0,label:a.label};toast('Налаштування відновлено — правте й перезбирайте');render()}

function igAdd(){const g=igState();if(g.items.length<6){g.items.push({icon:'',title:'',text:''});render()}}
function igRemove(){const g=igState();if(g.items.length>1){g.items.pop();render()}}
// Завантажувач, який ЗАВЖДИ рендерить, у парі з рендером, який ЗАВЖДИ його
// планує (хвіст workspace: tab==='info' -> setTimeout(loadIconLibrary)), дає
// нескінченний цикл. Помилки не видно: сторінка малюється сотні разів на
// секунду, DOM щоразу новий, і клік не встигає народитись - кнопка зникає
// між mousedown і mouseup. Зовні це «вкладка не перемикається».
// Тому рендер лише коли щось СПРАВДІ довантажилось - як у сусідніх
// loadArtifactText/loadArtifactImages.
async function loadIconLibrary(){try{let changed=false;if(!state.igIcons){const d=await api('/api/infographic/icons');state.igIcons=d.icons||[];changed=true}if(!state.igLogos){const l=await api('/api/infographic/logos');state.igLogos=l.logos||[];changed=true}if(changed)render()}catch(x){toast(x.message,true)}}
// SVG у canvas: будь-який фірмовий знак стає PNG із прозорістю просто в браузері,
// тому серверу не потрібен жоден растеризатор. Без width/height беремо viewBox -
// інакше Chrome малює такий SVG нульового розміру.
async function svgToPng(file){const text=await file.text();let markup=text;if(!/<svg[^>]*\swidth=/.test(markup)){const box=/viewBox="([\d.\s-]+)"/.exec(markup);if(box){const p=box[1].trim().split(/\s+/);if(p.length===4)markup=markup.replace('<svg',`<svg width="${p[2]}" height="${p[3]}"`)}}
const url=URL.createObjectURL(new Blob([markup],{type:'image/svg+xml'}));try{const img=new Image();await new Promise((ok,bad)=>{img.onload=ok;img.onerror=()=>bad(Error('Не вдалося прочитати SVG'));img.src=url});const w=img.naturalWidth||img.width||512,h=img.naturalHeight||img.height||512;const scale=768/Math.max(w,h);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(w*scale));canvas.height=Math.max(1,Math.round(h*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return await new Promise(res=>canvas.toBlob(res,'image/png'))}finally{URL.revokeObjectURL(url)}}
async function igLogoUpload(input){const file=input.files?.[0];if(!file)return;try{const isSvg=/svg/i.test(file.type)||/\.svg$/i.test(file.name);const blob=isSvg?await svgToPng(file):file;if(!blob)throw Error('Порожній файл');const name=file.name.replace(/\.[^.]+$/,'');const r=await fetch(`/api/infographic/logo?name=${encodeURIComponent(name)}`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':'image/png'},body:blob});const d=await r.json();if(!r.ok)throw Error(d?.detail||'Не вдалося завантажити логотип');state.igLogos=[...(state.igLogos||[]),d];igSet('logo',d.url);toast('Логотип додано')}catch(x){toast(x.message,true)}finally{input.value=''}}
async function igLogoDelete(url){try{await api(`/api/infographic/logo?url=${encodeURIComponent(url)}`,{method:'DELETE'});state.igLogos=(state.igLogos||[]).filter(l=>l.url!==url);const g=igState();if(g.logo===url)g.logo='';toast('Логотип прибрано');render()}catch(x){toast(x.message,true)}}
async function igUpload(input){const file=input.files?.[0];if(!file)return;try{const r=await fetch('/api/uploads/image',{method:'POST',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':file.type||'application/octet-stream'},body:file});const d=await r.json();if(!r.ok)throw Error(d?.detail||'Не вдалося завантажити');igSet('photo',d.url);toast('Фото завантажено')}catch(x){toast(x.message,true)}}
async function igSuggest(button){const p=state.selected;if(!p)return;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Модель думає…'}try{const d=await api(`/api/projects/${p.id}/infographic/suggest`,{method:'POST'});const g=igState();g.title=d.title||g.title;g.items=(d.items||[]).map(x=>({icon:x.icon||'',title:x.title||'',text:x.text||''}));await refreshSelected();toast(`Підписи готові · $${Number(d.cost||0).toFixed(4)}`);render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function igRender(button){const p=state.selected,g=igState();if(!p)return;if(!g.photo)return toast('Спершу оберіть або завантажте фото',true);if(!g.items.some(x=>x.title.trim()))return toast('Впишіть хоча б один підпис',true);const original=button?.textContent;if(button){button.disabled=true;button.textContent='Збираю…'}try{const d=await api(`/api/projects/${p.id}/infographic`,{method:'POST',body:JSON.stringify({photo_url:g.photo,title:g.title,template:g.template,items:g.items,logo_url:g.logo,brand:g.brand,accent:g.accent})});g.result=d;await refreshSelected();toast('Інфографіку зібрано');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
function infographicPage(){const g=igState(),icons=state.igIcons||[],lib=state.igFree||[];
shell(`<header class="pagehead"><div><small class="eyebrow">ІНФОГРАФІКА</small><h1>Інфографіка на фото</h1><p>Картинка 2000×2000 для галереї магазину — без проєкту і до появи картки товару. Достатньо фото, підписів і фірмових іконок (${icons.length} у бібліотеці).</p></div><div><button class="btn secondary" onclick="igFreeSuggest(this)" title="Платно: модель прочитає вставлені характеристики, напише підписи і підбере іконки">Запропонувати підписи · платно</button><button class="btn primary" onclick="igFreeRender(this)">Зібрати картинку</button></div></header>
<section class="panel"><div class="ig-grid"><div>
<label>Назва товару<input value="${esc(g.name)}" oninput="igSet('name',this.value)" placeholder="Система зберігання енергії SUN-12K"></label>
<label>Характеристики <em>для підказки моделі</em><textarea rows="6" oninput="igSet('facts',this.value)" placeholder="Вставте сюди характеристики: 12 кВт, 48 В, 2 MPPT, батарея 16 кВт·год, гарантія 60 міс…">${esc(g.facts)}</textarea></label>
<label>Заголовок картинки<input value="${esc(g.title)}" oninput="igSet('title',this.value)" placeholder="Відмінне охолодження компонентів"></label>
<label>Макет<select onchange="igSet('template',this.value)">${IG_TEMPLATES.map(([v,l])=>`<option value="${v}" ${g.template===v?'selected':''}>${l}</option>`).join('')}</select></label>
${igBrandBlock(g)}
${igColorBlock()}
<label>Фото товару<input value="${esc(g.photo)}" oninput="igSet('photo',this.value)" placeholder="/media/... або https://..."></label>
<div class="row"><input type="file" accept="image/*" onchange="igUpload(this)"><span class="muted-note">завантажте кадр із комп'ютера</span></div>
${g.photo?`<div class="ig-gallery"><img src="${esc(g.photo)}" alt="" class="on"></div>`:''}
${g.result?`<div class="ig-result"><b>Готово:</b> ${Math.round(g.result.bytes/1024)} КБ<div><img src="${esc(g.result.url)}" alt="інфографіка"></div><div class="row"><a class="btn secondary" href="${esc(g.result.url)}" download>Завантажити WEBP</a><a class="btn ghost" href="${esc(g.result.url)}" target="_blank" rel="noopener">Відкрити</a></div></div>`:''}
</div><div>${igItemsBlock(g,icons)}</div></div></section>
<section class="panel"><h2>Історія генерацій</h2>${lib.length?`<div class="ig-lib">${lib.map(x=>`<figure><img src="${esc(x.url)}" alt="${esc(x.name)}" loading="lazy"><figcaption><b>${esc(x.name)}</b><span>${x.bytes?`${Math.round(x.bytes/1024)} КБ`:''}</span><span>${x.created_at?dt(x.created_at):''}</span><span class="row"><a href="${esc(x.url)}" download>завантажити</a> · <b class="link-like" onclick="igFreeDelete('${esc(x.url)}')">прибрати</b></span></figcaption></figure>`).join('')}</div>`:'<p class="muted-note">Історія порожня — зберіть першу картинку, і вона зʼявиться тут.</p>'}</section>${igIconPickerTpl()}`)}
// Те саме правило: галерея перемальовує лише коли список змінився. Виклик
// після збирання картинки нічого не втрачає - там render() стоїть явно.
async function loadFreeGallery(){try{const d=await api('/api/infographic/gallery');const next=d.items||[];const same=JSON.stringify(next)===JSON.stringify(state.igFree||[]);state.igFree=next;if(!same)render()}catch(x){toast(x.message,true)}}
async function igFreeSuggest(button){const g=igState();if(!g.name.trim()&&!g.facts.trim())return toast('Впишіть назву або характеристики',true);const original=button?.textContent;if(button){button.disabled=true;button.textContent='Модель думає…'}try{const d=await api('/api/infographic/suggest',{method:'POST',body:JSON.stringify({name:g.name,facts:g.facts,count:Math.max(2,Math.min(6,g.items.length||4))})});g.title=d.title||g.title;g.items=(d.items||[]).map(x=>({icon:x.icon||'',title:x.title||'',text:x.text||''}));toast(`Підписи готові · $${Number(d.cost||0).toFixed(4)}`);render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function igFreeRender(button){const g=igState();if(!g.photo)return toast('Спершу завантажте фото',true);if(!g.items.some(x=>x.title.trim()))return toast('Впишіть хоча б один підпис',true);const original=button?.textContent;if(button){button.disabled=true;button.textContent='Збираю…'}try{const d=await api('/api/infographic/render',{method:'POST',body:JSON.stringify({photo_url:g.photo,title:g.title,template:g.template,items:g.items,logo_url:g.logo,brand:g.brand,name:g.name,accent:g.accent})});g.result=d;await loadFreeGallery();toast('Інфографіку зібрано');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function igFreeDelete(url){try{await api(`/api/infographic/render?url=${encodeURIComponent(url)}`,{method:'DELETE'});state.igFree=(state.igFree||[]).filter(x=>x.url!==url);toast('Прибрано');render()}catch(x){toast(x.message,true)}}
function projectAssets(){const a=state.selected.assets||[];return `<section class="media-grid">${a.map(asset=>mediaCard(asset)).join('')||'<div class="empty">Зображень поки немає.</div>'}</section><dialog id="assetDetails"></dialog>`}
function mediaCard(a){const label=assetLabel(a);return `<article class="media-card"><div class="media-image"><img src="${esc(a.url)}" alt="${esc(label)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none';this.parentElement.classList.add('media-image-broken');this.parentElement.insertAdjacentHTML('beforeend','<span>Кадр не завантажився</span>')"></div><div><span class="badge neutral">${esc(label)}</span><h3>${a.width&&a.height?`${a.width} × ${a.height}`:'Зображення'}</h3>${a.project_name?`<p class="media-project" title="${esc(a.project_name)}">${esc(a.project_name)}</p>`:''}<p>${esc(a.model==='source'?'Вихідне фото':a.model||'Джерело')}</p><small>${money(a.cost)} · ${dt(a.created_at)}</small><div class="media-actions"><button class="btn secondary" onclick="showAsset('${a.id}')">Докладніше</button><a class="btn ghost" href="${esc(a.url)}" download>Завантажити</a></div></div></article>`}
function showAsset(id){const a=state.assets.find(x=>x.id===id)||(state.selected?.assets||[]).find(x=>x.id===id);if(!a)return toast('Медіафайл не знайдено',true);const label=assetLabel(a),source=a.metadata?.source_url||a.metadata?.reference_url||'';let dlg=document.getElementById('assetDetails');if(!dlg){dlg=document.createElement('dialog');dlg.id='assetDetails';document.body.appendChild(dlg)}dlg.innerHTML=`<form method="dialog"><div class="dialog-head"><div><small class="eyebrow">МЕДІАФАЙЛ</small><h2>${esc(label)}</h2></div><button aria-label="Закрити">×</button></div><div class="asset-detail-image"><img src="${esc(a.url)}" alt="${esc(label)}" referrerpolicy="no-referrer" onerror="this.style.display='none';this.insertAdjacentHTML('afterend','<p class=\'muted-note\' style=\'padding:22px;text-align:center\'>Кадр лежить на чужому CDN і не вантажиться сюди — локальної копії немає. Відкрийте оригінал кнопкою нижче.</p>')"></div><div class="summary-grid"><div><small>Модель</small><h3>${esc(a.model==='source'?'Вихідне фото':a.model||'Джерело')}</h3></div><div><small>Розмір</small><h3>${a.width&&a.height?`${a.width} × ${a.height}`:'—'}</h3></div><div><small>Вартість</small><h3>${money(a.cost)}</h3></div></div>${source?`<label>Вихідний референс<input value="${esc(source)}" readonly></label>`:''}<label>Промпт<textarea rows="8" readonly>${esc(a.prompt||'Для вихідного фото промпт не використовується')}</textarea></label><div class="row"><a class="btn primary" href="${esc(a.url)}" target="_blank" rel="noopener">Відкрити оригінал</a><a class="btn secondary" href="${esc(a.url)}" download>Завантажити</a></div></form>`;dlg.showModal()}
function criticsPanel(){const critics=state.selected?.critics||[];const llm=critics.find(c=>c.type==='llm');return `<section class="panel"><div class="panel-tools"><h2>AI-перевірка якості</h2>${can('review.request_changes')||can('project.create')?`<button class="btn secondary" onclick="rerunCritic(this)">Перезапустити перевірку</button>${(state.selected?.critics||[]).some(c=>c.type==='llm'&&(c.issues||[]).length)?`<button class="btn secondary" title="Платно: модель виправить ТЕКСТ сторінок за зауваженнями рецензії (нові версії, структура не змінюється); вартість додається до вартості проєкту" onclick="runCriticFix(this)">${llm?.auto_fixed?`Виправити ще раз · платно`:`Виправити за рецензією · платно`}</button>`:''}<button class="btn primary" title="Справжня AI-рецензія: модель читає сторінки проти даних товару. Платно — вартість токенів додається до вартості проєкту (зазвичай $0.01–0.05)" onclick="runLlmCritic(this)">${llm?`Повторити AI-рецензію · платно`:`AI-рецензент · платно`}</button>`:''}</div><p class="critic-note">Це автоматичні евристичні перевірки: структура HTML, наявність назви й фактів товару, alt-тексти й доступність, надмірність маркетингу. Вони швидко підсвічують ризики, але <b>не гарантують якість і не замінюють ручну перевірку</b> — сприймайте оцінки як підказку, а не остаточний вердикт. Кнопка <b>«AI-рецензент · платно»</b> запускає справжню модель, яка звіряє сторінки з даними товару; її вартість <b>додається до вартості проєкту</b> після прогону.</p>${llm?`<p class="muted-note llm-status">🤖 AI-рецензію виконано ${rel(llm.created_at)} <span title="${dt(llm.created_at)}">(${dt(llm.created_at)})</span>${llm.auto_fixed?` · <b>авто-виправлення застосовано</b> — нові версії сторінок у селекторі версій`:(llm.issues||[]).length?` · авто-виправлення ще не запускалось`:` · зауважень немає`}</p>`:''}${critics.length?`<div class="metrics">${critics.map(c=>`<div><small>${CRITIC_LABEL[c.type]||esc(c.type)}</small><b>${Math.round(c.score)}</b></div>`).join('')}</div>${critics.filter(c=>(c.issues||[]).length).map(c=>`<div class="critic-block"><b>${CRITIC_LABEL[c.type]||esc(c.type)}</b><div class="issue-list">${c.issues.map(i=>`<div>${esc(i)}</div>`).join('')}</div></div>`).join('')||'<p class="critic-clean">Критичних зауважень не знайдено.</p>'}`:'<div class="empty">Перевірку ще не виконано.</div>'}</section>`}
const DECISION_LABEL={approve:'Схвалено',request_changes:'Запитано зміни',submit:'Надіслано на перевірку'};
function reviewChecklist(){const p=state.selected||{};return [['facts','Факти та цифри'],['images','Зображення'],['html','HTML і верстка'],...(p.languages||[]).map(l=>[`lang_${l}`,`Мова: ${languageLabel(l)}`]),...(p.variants||[]).map(v=>[`variant_${v}`,`Формат: ${VARIANT[v]||v}`])]}
function reviewHistory(){const rows=state.selected?.reviews||[];if(!rows.length)return '';return `<section class="panel"><h2>Історія перевірок</h2><div class="review-log">${rows.map(r=>{const checked=Object.entries(r.checklist||{}).filter(([,v])=>v).map(([k])=>k);return `<div class="review-entry ${r.decision}"><div class="review-entry-head"><b>${DECISION_LABEL[r.decision]||esc(r.decision)}</b><span>${esc(r.reviewer||'—')} · ${dt(r.created_at)}</span></div>${r.comment?`<p>${esc(r.comment)}</p>`:''}<small>Перевірено пунктів: ${checked.length} з ${Object.keys(r.checklist||{}).length||'—'}</small></div>`}).join('')}</div></section>`}
// Review draft lives in state, keyed to the project: flipping to Перегляд and
// back must not eat the reviewer's checkmarks or comment.
function reviewDraft(){const pid=state.selected?.id;if(!state.reviewDraft||state.reviewDraft.pid!==pid)state.reviewDraft={pid,checks:{},comment:''};return state.reviewDraft}
function reviewCheckToggle(el){reviewDraft().checks[el.value]=el.checked;updateReviewUI()}
function reviewCommentInput(el){reviewDraft().comment=el.value;updateReviewUI()}
// Checkbox clicks update the header and buttons in place: a full render() would
// reload the embedded preview iframe on every tick.
function updateReviewUI(){const d=reviewDraft(),items=reviewChecklist(),done=items.filter(([k])=>d.checks[k]).length;const anyFallback=(state.selected?.artifacts||[]).some(a=>a.fallback_reason);const counter=document.getElementById('reviewCounter');if(counter)counter.textContent=`Відмічено ${done} з ${items.length}`;const approve=document.getElementById('reviewApproveBtn');if(approve){const ready=done===items.length&&!anyFallback;approve.disabled=!ready;approve.title=anyFallback?'Серед версій є аварійний шаблон замість обраного стилю — спершу перегенеруйте':(done===items.length?'':'Схвалення можливе, коли пройдено всі пункти чекліста')}const changes=document.getElementById('reviewChangesBtn');if(changes){const hasComment=d.comment.trim().length>0;changes.disabled=!hasComment;changes.title=hasComment?'':'Опишіть у коментарі, що саме виправити'}}
function reviewTab(){const p=state.selected,canChanges=can('review.request_changes'),canApprove=can('review.approve'),canDecide=canChanges||canApprove;const d=reviewDraft();const variant=state.artifact?.variant==='mobile'?'mobile':'desktop';const changesBanner=p.status==='changes_requested'&&can('project.create')?`<section class="panel review-cta"><b>Зміни запитано.</b> Наступний крок — новий запуск із урахуванням коментаря.<button class="btn primary" onclick="document.getElementById('rerunProjectDialog').showModal()">Повторити генерацію</button></section>`:'';return `${changesBanner}${criticsPanel()}${state.artifact?`<section class="panel preview-panel"><div class="panel-tools">${artifactSelect()}<div class="preview-hint">Перевіряйте прямо тут — вкладку залишати не потрібно</div></div>${fallbackBanner()}<div id="mediaAudit"></div><div class="preview-stage review-stage"><div class="preview-canvas ${variant}"><iframe title="Перегляд для перевірки" sandbox="allow-same-origin" scrolling="yes" srcdoc="${esc(previewDocument(state.artifact.html))}"></iframe></div></div></section>`:''}<section class="panel"><div class="panel-tools"><h2>Контроль якості</h2><b id="reviewCounter" class="muted-note"></b></div><p class="critic-note">Позначайте пункти, звіряючи зі сторінкою вище. Список формується з мов і форматів цього проєкту; позначки зберігаються разом із рішенням в історії перевірок.</p><div class="review-grid">${reviewChecklist().map(([x,label])=>`<label class="check"><input type="checkbox" name="reviewcheck" value="${x}" ${d.checks[x]?'checked':''} onchange="reviewCheckToggle(this)"> ${label}</label>`).join('')}</div><label>Коментар <em>обов'язковий, якщо запитуєте зміни</em><textarea id="reviewComment" rows="4" placeholder="Що саме потрібно виправити або що перевірено" oninput="reviewCommentInput(this)">${esc(d.comment)}</textarea></label>${canDecide?`<div class="panel-tools review-actions">${canChanges?`<button id="reviewChangesBtn" class="btn danger" onclick="review('request_changes',this)">Запросити зміни</button>`:''}${canApprove?`<button id="reviewApproveBtn" class="btn primary" onclick="review('approve',this)">Схвалити</button>`:''}</div>`:'<p class="muted-note">У вас немає прав на рішення щодо перевірки.</p>'}</section>${reviewHistory()}`}
function projectActions(p){const busy=['processing','queued'].includes(p.status),stopped=['paused','cancelled','error'].includes(p.status),canQueue=can('project.create'),btns=[];if(busy&&canQueue){btns.push(`<button class="btn secondary" onclick="queueAction('pause',this)">Пауза</button>`);btns.push(`<button class="btn danger" onclick="queueAction('cancel',this)">Скасувати</button>`)}if(stopped&&canQueue)btns.push(`<button class="btn secondary" onclick="queueAction('resume',this)">Відновити</button>`);btns.push(`<button class="btn secondary" onclick="downloadArchive()">Завантажити ZIP</button>`);if(canQueue)btns.push(`<button class="btn secondary" onclick="document.getElementById('rerunProjectDialog').showModal()">Повторити генерацію</button>`);if(canQueue&&!busy)btns.push(`<button class="btn secondary" onclick="document.getElementById('translateDialog').showModal()">+ Мова</button>`);if(can('project.delete')&&!busy)btns.push(`<button class="btn danger" onclick="deleteProject(this)">Видалити</button>`);return btns.join('')}
async function queueAction(action,button){const original=button?.textContent;if(button){button.disabled=true;button.textContent='…'}try{await api(`/api/projects/${state.selected.id}/queue`,{method:'POST',body:JSON.stringify({action})});toast(action==='pause'?'Проєкт призупинено':action==='cancel'?'Проєкт скасовано':'Проєкт повернуто в чергу');await refreshSelected();state.projects=await api('/api/projects');render()}catch(x){toast(x.message,true);if(button){button.disabled=false;button.textContent=original}}}
async function deleteProject(button){if(!confirm('Видалити проєкт разом з усіма версіями, зображеннями та історією? Дію не можна скасувати.'))return;if(button)button.disabled=true;try{await api(`/api/projects/${state.selected.id}`,{method:'DELETE'});toast('Проєкт видалено');state.selected=null;state.projects=await api('/api/projects');render()}catch(x){toast(x.message,true);if(button)button.disabled=false}}
async function runCriticFix(button){if(!confirm('Платне авто-виправлення: модель перепише текст сторінок за зауваженнями AI-рецензії (створяться нові версії). Продовжити?'))return;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Виправлення…'}try{const r=await api(`/api/projects/${state.selected.id}/critic/fix`,{method:'POST'});await refreshSelected();toast(`Оновлено ${r.updated} стор. · списано $${(r.cost||0).toFixed(4)}, додано до вартості проєкту`);render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function runLlmCritic(button){const original=button?.textContent;if(button){button.disabled=true;button.textContent='Рецензування…'}try{const r=await api(`/api/projects/${state.selected.id}/critic`,{method:'POST',body:JSON.stringify({llm:true})});await refreshSelected();toast(`AI-рецензія готова · списано $${(r.cost||0).toFixed(4)}, додано до вартості проєкту`);render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function rerunCritic(button){const original=button?.textContent;if(button){button.disabled=true;button.textContent='Перевірка…'}try{await api(`/api/projects/${state.selected.id}/critic`,{method:'POST',body:JSON.stringify({auto_fix:false})});await refreshSelected();toast('Перевірку якості оновлено');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
function activity(){return `<section class="panel"><h2>Історія проекта</h2><div class="timeline">${state.events.map(e=>`<div><time>${dt(e.created_at)}</time><b>${STAGE[e.stage]||'Опрацювання'}</b><span>${esc(e.message)}</span></div>`).join('')}</div></section>`}
function translateDialogTpl(){const p=state.selected;if(!p)return '';const have=new Set(String(p.languages||'').split(',').map(x=>x.trim()).filter(Boolean));const src=(String(p.languages||'ua').split(',')[0]||'ua').trim();const quick=['pl','en','de','cs','ro','bg'].filter(x=>!have.has(x));return `<dialog id="translateDialog"><form onsubmit="translateProject(event)"><div class="dialog-head"><div><small class="eyebrow">ДОДАТИ МОВУ</small><h2>Переклад готової версії</h2></div><button type="button" aria-label="Закрити" onclick="translateDialog.close()">×</button></div><p class="muted-note">Не повторний запуск: перекладається лише текст останніх версій ${src.toUpperCase()} — верстка, стилі й зображення лишаються байт-у-байт. Це найдешевший спосіб додати мову (~вартість тексту, без зображень).</p><label>Мова<div class="row" style="flex-wrap:wrap;gap:8px">${quick.map(code=>`<label class="check" style="margin:0"><input type="radio" name="language" value="${code}"> ${LANG[code]||code.toUpperCase()}</label>`).join('')}</div></label><label>Або код мови (ISO/BCP-47)<input name="custom_language" placeholder="напр. lt, lv, hu, en-GB" spellcheck="false"></label><button class="btn primary">Перекласти</button></form></dialog>`}
async function translateProject(e){e.preventDefault();const f=new FormData(e.target);const language=(f.get('custom_language')||'').trim()||f.get('language');if(!language)return toast('Оберіть мову',true);try{const r=await api(`/api/projects/${state.selected.id}/translate`,{method:'POST',body:JSON.stringify({language})});translateDialog.close();toast(`Переклад на ${String(r.language).toUpperCase()} запущено — стежте в Історії`);await refreshSelected();render()}catch(x){toast(x.message,true)}}
function rerunProjectDialogTpl(){const p=state.selected||{},current=p.style_id,variants=p.variants||['desktop','mobile'];return `<dialog id="rerunProjectDialog"><form onsubmit="rerun(event)"><div class="dialog-head"><div><small class="eyebrow">ПОВТОРНА ГЕНЕРАЦІЯ</small><h2>Налаштуйте новий запуск</h2></div><button type="button" aria-label="Закрити" onclick="document.getElementById('rerunProjectDialog').close()">×</button></div><label>Стиль для нової генерації<select name="style_id" required onchange="renderRerunFaq()">${productStyles().map(s=>`<option value="${s.id}" ${s.id===current?'selected':''} data-tag="${[s.is_default?'базовий':'',s.has_faq?'з FAQ':''].filter(Boolean).join(' · ')}">${esc(s.name)}</option>`).join('')}</select></label>${paletteSelect(p.photo_palette?'__photo__':'',true)}<fieldset><legend>Блок FAQ</legend><div id="rerunFaqBox">${rerunFaqTpl()}</div></fieldset><fieldset><legend>Відео (опційно)</legend><label>Посилання на YouTube-ролик<input name="video_url" type="url" value="${esc(p.video_url||'')}" placeholder="https://www.youtube.com/watch?v=…"></label><em class="muted-note">Порожнє поле — блок відео прибирається.</em></fieldset>${languagePicker(p.languages||['ua','ru'])}<fieldset><legend>Формати</legend><div class="language-grid"><label class="check"><input type="checkbox" name="variant" value="desktop" ${variants.includes('desktop')?'checked':''}> Десктоп</label><label class="check"><input type="checkbox" name="variant" value="mobile" ${variants.includes('mobile')?'checked':''}> Мобільна</label></div></fieldset>${referencePickerField(p)}${reuseImagesField()}<p class="dialog-note">Попередні HTML-версії залишаться в історії. Текст буде створено заново за обраним стилем, мовами й форматами.</p><button class="btn primary">Запустити повторно</button></form></dialog>`}
function rerunSelectedStyle(){const f=document.querySelector('#rerunProjectDialog form');const id=f?new FormData(f).get('style_id'):(state.selected||{}).style_id;return (state.styles||[]).find(x=>x.id===id)||null}
function rerunFaqTpl(){const st=rerunSelectedStyle();if(!st||!st.has_faq)return '<em class="muted-note">Цей стиль не містить блока FAQ.</em>';const on=(state.selected||{}).faq!==false;return `<label class="check"><input type="checkbox" name="faq" ${on?'checked':''}> Додати блок «Питання і відповіді» після фінального блока</label>`}
function renderRerunFaq(){const box=document.getElementById('rerunFaqBox');if(box)box.innerHTML=rerunFaqTpl()}
function mediaPath(u){return String(u||'').split('?')[0]}
function referenceCandidates(p){const seen=new Set(),out=[];const push=(url,name)=>{const key=mediaPath(url);if(!url||seen.has(key))return;seen.add(key);out.push({url,name})};(p.assets||[]).filter(a=>a.label==='product-reference').forEach(a=>push(a.url,'Поточний референс'));(p.assets||[]).filter(a=>a.kind==='upload'&&!/360/.test(a.label||'')).forEach(a=>push(a.url,a.label));(p.assets||[]).filter(a=>/^gallery-frame-/.test(a.label||'')).forEach(a=>push(a.url,'Кадр галереї'));let src=[];try{src=JSON.parse(p.source_images||'[]')}catch(_){}src.slice(0,12).forEach(u=>push(u,'Кадр сторінки'));return out}
function referencePickerField(p){const list=referenceCandidates(p);if(!list.length)return '';const cur=mediaPath(p.reference_url||'');return `<fieldset class="language-fieldset"><legend>Референс для AI-зображень</legend><input type="hidden" name="reference_url" value="${esc(p.reference_url||'')}"><div class="probe-grid ref-grid">${list.map((x,i)=>`<button type="button" class="frame refpick ${cur&&mediaPath(x.url)===cur?'picked':''}" title="${esc(x.name)}" onclick="pickReference(this,'${esc(x.url)}')"><img src="${esc(x.url)}" alt="${esc(x.name)}" loading="lazy" onerror="this.closest('.frame').classList.add('dead')"></button>`).join('')}</div><p class="muted-note" style="margin-top:8px" id="refPickNote">${cur?'Обраний кадр підсвічено. Клік по ньому — повернути автопідбір.':'Автопідбір: перший придатний кадр галереї. Клік по кадру — генерувати Hero і Feature саме з нього.'}</p></fieldset>`}
function pickReference(btn,url){const form=btn.closest('form'),field=form.querySelector('[name=reference_url]');const was=btn.classList.contains('picked');form.querySelectorAll('.refpick.picked').forEach(b=>b.classList.remove('picked'));field.value=was?'':url;field.dataset.touched='1';if(!was)btn.classList.add('picked');const reuse=form.querySelector('[name=reuse_images]');if(reuse&&mediaPath(field.value)!==mediaPath(state.selected?.reference_url||'')){reuse.checked=false}const note=document.getElementById('refPickNote');if(note)note.textContent=field.value?'Новий референс: Hero і Feature буде згенеровано заново з цього кадру.':'Автопідбір: перший придатний кадр галереї.'}
function reuseImagesField(){const imgs=(state.selected?.assets||[]).filter(a=>a.kind==='image'&&/^(hero|feature)/.test(a.label||''));if(!imgs.length)return '';const cost=imgs.filter(a=>Number(a.cost)>0).reduce((s,a)=>s+Number(a.cost||0),0);return `<fieldset class="language-fieldset"><legend>Зображення</legend><label class="check"><input type="checkbox" name="reuse_images" checked> Використати наявні зображення (${imgs.length} шт.)</label><p class="muted-note" style="margin-top:8px">Зніміть галочку, щоб створити зображення заново${cost?` — це додасть близько ${money(cost)} до вартості`:''}. З галочкою перегенерується лише текст: швидше й без витрат на зображення.</p></fieldset>`}
async function rerun(e){e.preventDefault();const form=e.currentTarget,button=e.submitter,original=button?.textContent;if(button){button.disabled=true;button.textContent='Запуск…'}try{const data=new FormData(form),paletteChoice=data.get('palette_id')||'',payload={style_id:data.get('style_id'),palette_id:paletteChoice==='__photo__'?'':paletteChoice,photo_palette:paletteChoice==='__photo__',languages:collectLanguages(form),variants:[...form.querySelectorAll('[name=variant]:checked')].map(x=>x.value),reuse_images:!!form.querySelector('[name=reuse_images]:checked'),faq:form.querySelector('[name=faq]')?form.querySelector('[name=faq]').checked:null,video_url:(data.get('video_url')??'').trim()};const refField=form.querySelector('[name=reference_url]');if(refField&&refField.dataset.touched==='1')payload.reference_url=refField.value;await api(`/api/projects/${state.selected.id}/run`,{method:'POST',body:JSON.stringify(payload)});form.closest('dialog').close();toast('Генерацію запущено з новими параметрами');await refreshSelected();state.projects=await api('/api/projects');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function downloadBlocks(button){if(!state.artifact)return;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Рендер…'}try{const response=await fetch(`/api/artifacts/${state.artifact.id}/blocks.zip`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){let detail=`HTTP ${response.status}`;try{detail=(await response.json()).detail||detail}catch{}throw Error(detail)}const blob=await response.blob(),match=/filename="([^"]+)"/.exec(response.headers.get('Content-Disposition')||''),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=match?.[1]||'blocks-png.zip';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Блоки збережено в PNG')}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function downloadAllBlocks(button){if(!state.artifact||!state.selected)return;const original=button?.textContent;const run=state.artifact.run_index||1;if(button){button.disabled=true;button.textContent='Рендер усіх…'}try{const response=await fetch(`/api/projects/${state.selected.id}/blocks-all.zip?run=${run}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){let detail=`HTTP ${response.status}`;try{detail=(await response.json()).detail||detail}catch{}throw Error(detail)}const blob=await response.blob(),match=/filename="([^"]+)"/.exec(response.headers.get('Content-Disposition')||''),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=match?.[1]||'blocks-all-png.zip';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Усі варіанти збережено в PNG')}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function downloadArchive(){if(!state.selected)return;try{toast('Підготовка ZIP-архіву…');const response=await fetch(`/api/projects/${state.selected.id}/archive`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){const text=await response.text();let detail=text;try{detail=JSON.parse(text)?.detail||text}catch{}throw Error(detail||`HTTP ${response.status}`)}const blob=await response.blob(),disposition=response.headers.get('content-disposition')||'',match=disposition.match(/filename="([^"]+)"/),filename=match?.[1]||'artline-rich.zip',url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Архів завантажено')}catch(x){toast(x.message,true)}}
async function saveHtml(button){if(pendingSave)return;pendingSave=true;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Збереження…'}try{const editor=document.getElementById('htmlEditor');const d=await api(`/api/artifacts/${state.artifact.id}`,{method:'PUT',body:JSON.stringify({html:editor.value})});await refreshSelected();state.artifact=(state.selected.artifacts||[]).find(x=>x.id===d.id)||d;toast(`Збережено версію v${d.version}`);render()}catch(x){toast(x.message,true)}finally{pendingSave=false;if(button){button.disabled=false;button.textContent=original}}}
async function review(decision,button){if(pendingSave)return;pendingSave=true;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Збереження…'}try{const d=reviewDraft();const checks=Object.fromEntries(reviewChecklist().map(([k])=>[k,!!d.checks[k]]));const comment=d.comment||'';const d2=await api(`/api/projects/${state.selected.id}/review`,{method:'POST',body:JSON.stringify({decision,comment,checklist:checks})});toast(d2.message||'Рішення збережено');state.reviewDraft=null;await refreshSelected();render()}catch(x){toast(x.message,true)}finally{pendingSave=false;if(button){button.disabled=false;button.textContent=original}}}
// --- Схема сітки зі структурованого промпта (безкоштовно, без AI) ------------
function parseStyleSections(prompt){const lines=String(prompt||'').split('\n');const sections=[];let current=null;let inSet=false;
for(const line of lines){const numbered=line.match(/^\s*(\d+)\.\s+(.+)$/);
if(/SECTION SET|PAGE STRUCTURE|structure, in order/i.test(line)){inSet=true;continue}
if(inSet&&/^[A-Z][A-Z &-]{5,}$/.test(line.trim())&&!numbered){break}
if(numbered){if(!inSet)continue;if(sections.length>=12)break;const head=numbered[2];const name=(head.split(/\s[-—]\s/)[0]||head).trim();current={name:name.slice(0,42),line:line.trim(),raw:head,body:head};sections.push(current);continue}
if(current&&line.trim().startsWith('-')){current.body+=' '+line.trim()}}
return sections.map(x=>{const text=x.body||'';let cols=1;const rep=text.match(/repeat\((\d+)\s*,/);
const auto=text.match(/auto-fit|auto-fill/);const mm=text.match(/minmax\((\d+)px/);
if(rep)cols=Math.min(6,parseInt(rep[1],10)||1);
else if(auto)cols=mm&&parseInt(mm[1],10)<=200?4:3;
else if(/1fr\s*\/?\s*1fr|\.\d+fr|two equal columns|grid \d?\.?\d*fr/i.test(text))cols=2;
else if(/three (equal[- ]height )?(white|soft|dark)?\s?(cards|columns|tiles)|\btrio\b/i.test(text))cols=3;
else if(/responsive grid|grid of (white )?(category |product )?cards/i.test(text))cols=3;
else if(/four (value )?(cards|columns|tiles)/i.test(text))cols=4;
const nameUp=x.name.toUpperCase();const head=(x.raw||'').slice(0,60);
const dark=/LIGHT/.test(nameUp)?false:(/DARK|RECAP|HERO/.test(nameUp)||/\bdark\b/i.test(head));
const photo=/photo|photograph|image slot|gallery frame|full-bleed|render|\bimg\b|category cards: image/i.test(text);
const cleanName=x.name.split('(')[0].trim();
return {name:cleanName.slice(0,34),line:x.line,raw:(x.raw||'').slice(0,220),cols,dark,photo}})}
function styleGridBlueprint(s){const sections=parseStyleSections(s.prompt||'');
if(!sections.length)return '<section class="panel"><h2>Схема сітки</h2><div class="empty">У промпті не знайдено нумерованого «SECTION SET» — додайте секції списком «1. НАЗВА - опис», і схема зʼявиться тут.</div></section>';
const block=(sec,mobile)=>{const cols=mobile?1:sec.cols;const cells=Array.from({length:Math.max(1,cols)}).map(()=>`<i class="${sec.photo?'ph':''}"></i>`).join('');
return `<div class="bp-block ${sec.dark?'dark':''}" title="${esc(sec.raw)}"><small>${esc(sec.name)}</small><div class="bp-cols" style="grid-template-columns:repeat(${Math.max(1,cols)},1fr)">${cells}</div></div>`};
return `<section class="panel"><h2>Схема сітки</h2><p class="critic-note">Миттєва безкоштовна схема, зчитана з тексту промпта: порядок секцій, кількість колонок, темні/світлі полотна, фото-слоти (значок гори). Наведіть на блок — перший рядок його контракту. Мобайл за контрактом стилю — одна колонка. Точний вигляд із реальним товаром — вкладка «Перегляд».</p><div class="bp-wrap"><div class="bp-canvas"><b>Десктоп · 1240px</b>${sections.map(x=>block(x,false)).join('')}</div><div class="bp-canvas bp-mobile"><b>Мобайл · 480px</b>${sections.map(x=>block(x,true)).join('')}</div></div></section>`}
function promptOutline(s){const sections=parseStyleSections(s.prompt||'');if(!sections.length)return '';
return `<div class="prompt-outline"><small class="eyebrow">СЕКЦІЇ</small>${sections.map((x,i)=>`<button type="button" onclick="jumpToSection(${i})" title="Перейти до секції у тексті">${i+1}. ${esc(x.name)}</button>`).join('')}</div>`}
function jumpToSection(i){const ta=document.querySelector('textarea[name=prompt]');if(!ta)return;const sec=parseStyleSections(ta.value)[i];if(!sec)return;const idx=ta.value.indexOf(sec.line);if(idx<0)return;ta.focus();ta.setSelectionRange(idx,idx+sec.line.length);const lineNo=ta.value.slice(0,idx).split('\n').length,total=ta.value.split('\n').length;ta.scrollTop=Math.max(0,ta.scrollHeight*(lineNo-4)/total)}
function baseNewStyleOn(id){const srcStyle=(state.styles||[]).find(x=>x.id===id);state.styleEdit={...(state.styleEdit||{}),description:srcStyle?.description||'',prompt:srcStyle?.prompt||'',hero_prompt:srcStyle?.hero_prompt||'',feature_prompt:srcStyle?.feature_prompt||'',negative_prompt:srcStyle?.negative_prompt||'',palette:srcStyle?.palette||{}};toast(srcStyle?`Основа: «${srcStyle.name}» — правте як власний стиль`:'Порожня основа');render()}
function styleListGroup(title,hint,items,s){if(!items.length)return '';return `<small class="style-group" title="${esc(hint)}">${title}</small>`+items.map(x=>`<button class="${s.id===x.id?'active':''}" onclick="state.styleEdit=state.styles.find(y=>y.id==='${x.id}');render()"><b>${esc(x.name)}</b><small>${[x.is_default?'За замовчуванням':'',MANAGED_STYLE_NAMES.includes(x.name)?'Керований':'Власний',x.has_faq?'FAQ':'',x.has_golden?'★ еталон':'',x.usage_count?`${x.usage_count}\u00d7`:''].filter(Boolean).join(' · ')}</small></button>`).join('')}
function styleContextBar(s){if(!s.id&&!s.name)return `<div class="style-context"><div><b>Новий стиль</b><small>Заповніть «Основне» і «HTML», потім натисніть «Створити стиль»</small></div></div>`;const landing=isLandingStyle(s),managed=MANAGED_STYLE_NAMES.includes(s.name);return `<div class="style-context"><div><b>${esc(s.name)}</b><small>${landing?'Шаблон лендінгів — обирається в діалозі розділу «Лендінги»':'Стиль rich-контенту — обирається при створенні проєкту'}${s.is_default?' · за замовчуванням':''}</small></div><div class="row">${managed?`<span class="badge neutral" title="Синхронізується з кодом при кожному рестарті сервера">Керований</span>${can('style.manage')?`<button class="btn secondary" onclick="cloneStyle('${s.id}')" title="Копія стане власним стилем — правки збережуться назавжди">Створити копію</button>`:''}`:s.id?`<span class="badge neutral" title="Ваш стиль: правки зберігаються назавжди">Власний</span>`:''}</div></div>${managed?`<p class="critic-note">Це керований стиль: після рестарту сервера його текст повертається до вбудованого. Потрібні власні правки назавжди — «Створити копію» і редагуйте копію.</p>`:''}`}
function cloneStyle(id){const s=state.styles.find(x=>x.id===id);if(!s)return;state.styleEdit={name:`${s.name} — копія`,description:s.description||'',prompt:s.prompt||'',hero_prompt:s.hero_prompt||'',feature_prompt:s.feature_prompt||'',negative_prompt:s.negative_prompt||''};state.styleTab='general';toast('Копію підготовлено: перевірте назву і натисніть «Створити стиль»');render()}
function stylesPage(){const s=state.styleEdit||state.styles[0]||{};const tabs=isLandingStyle(s)?[['general','Основне'],['html','Промпт-шаблон'],['grid','Сітка'],['colors','Кольори і форма'],['quality','Якість']]:[['general','Основне'],['html','HTML'],['grid','Сітка'],['colors','Кольори і форма'],['images','Зображення'],['quality','Якість'],['preview','Перегляд']];if(!tabs.some(([k])=>k===state.styleTab))state.styleTab='general';shell(`<header class="pagehead"><div><small class="eyebrow">РУШІЙ СТИЛІВ</small><h1>Стилі</h1><p>Зліва — стилі rich-контенту (картки товарів) і шаблони лендінгів (промо-сторінки). «Керовані» оновлюються з кодом, «власні» — ваші назавжди.</p></div><div><button class="btn secondary" onclick="styleGenerator.showModal()">Згенерувати стиль</button><button class="btn primary" onclick="state.styleEdit={};state.styleTab='general';render()">+ Новий стиль</button></div></header><section class="style-shell"><div class="style-list">${styleListGroup('Rich-контент','Стилі карток товарів — обираються при створенні проєкту',productStyles(),s)}${styleListGroup('Лендінги','Шаблони промо-сторінок — обираються в розділі «Лендінги»',landingStyles(),s)}</div><div>${styleContextBar(s)}<div class="subtabs">${tabs.map(([k,v])=>`<button class="${state.styleTab===k?'active':''}" onclick="state.styleTab='${k}';render()">${v}</button>`).join('')}</div>${styleEditor(s)}</div></section>${styleGeneratorDialog()}`)}
function styleEditor(s){const score=s.score||{};if(state.styleTab==='preview'){if(s.id&&state.stylePreviewFor!==s.id){state.stylePreviewFor=s.id;state.stylePreview=null;state.stylePreviewSource='';state.stylePreviewSample='';state.styleRealMode=false;loadStylePreview(s.id)}const noteMap={demo:'Швидка демонстрація макета без AI — однакова для всіх стилів. Натисніть «Згенерувати AI-приклад», щоб побачити сторінку саме за цим стилем.',saved:'Збережений приклад цього стилю.',generated:'AI-приклад за цим стилем.',real:'Справжній прогін цього стилю — реальна згенерована сторінка цього товару, без витрат.'};if(s.id&&!state.styleSamples.length)loadStyleSamples();const samples=state.styleSamples||[],mine=samples.filter(p=>p.style_id===s.id),others=samples.filter(p=>p.style_id!==s.id),opt=p=>`<option value="${p.id}" ${state.stylePreviewSample===p.id?'selected':''}>${esc(p.name)}</option>`;const sampleSel=`<select onchange="onStyleSample(this.value)" title="Товар для превʼю"><option value="">Демо-товар</option>${mine.length?`<optgroup label="★ Справжні прогони цього стилю">${mine.map(opt).join('')}</optgroup>`:''}${others.length?`<optgroup label="Інші товари — лише дані для превʼю">${others.map(opt).join('')}</optgroup>`:''}</select><div class="view-switch">${[['desktop','Десктоп'],['mobile','Мобільна']].map(([v,l])=>`<button class="${state.stylePreviewVariant===v?'active':''}" onclick="onStyleVariant('${v}')">${l}</button>`).join('')}</div>`;return `<section class="panel"><div class="panel-tools"><h2>Демонстрація стилю</h2><div class="row">${s.id?sampleSel:''}<button class="btn secondary" onclick="runStyleDryRun()" title="Точний текст, що піде в модель — без витрат">Показати промпт</button>${s.id&&can('style.manage')?`<button class="btn primary" onclick="generateStylePreview('${s.id}',this)">Згенерувати AI-приклад (платно)</button>`:''}${s.id&&can('style.manage')?(s.has_golden?`<button class="btn ghost" onclick="clearGolden('${s.id}')" title="Прибрати few-shot еталон формату">★ Прибрати еталон</button>`:`<button class="btn ghost" onclick="pinGolden('${s.id}')" title="Закріпити поточний AI-приклад як еталон формату — модель триматиме структуру краще">Закріпити як еталон</button>`):''}</div></div>${s.has_golden?'<p class="muted-note">★ Для цього стилю закріплено еталон формату — він підмішується у кожну генерацію як приклад верстки.</p>':''}${state.styleDryRun?`<div class="dryrun"><div class="panel-tools"><b>Фінальний промпт${state.styleDryRun.sample_name?` · ${esc(state.styleDryRun.sample_name)}`:''} · ${state.styleDryRun.variant} · ${state.styleDryRun.chars} симв.</b><button class="btn ghost" aria-label="Закрити" onclick="closeDryRun()">×</button></div><pre class="stylediff">${esc(state.styleDryRun.prompt)}</pre><h3 class="critic-block">Механічні гарантії після генерації</h3><ul class="guarantee-list">${(state.styleDryRun.guarantees||[]).map(g=>`<li>${esc(g)}</li>`).join('')}</ul></div>`:''}${state.stylePreview?`<div class="preview-stage style-demo"><div class="preview-canvas ${state.stylePreviewVariant}"><iframe title="Демонстрація стилю" sandbox="allow-same-origin" scrolling="yes" srcdoc="${esc(previewDocument(state.stylePreview))}"></iframe></div></div><p class="muted-note">${noteMap[state.stylePreviewSource]||''}</p>`:s.id?'<div class="empty">Завантаження демонстрації…</div>':'<div class="empty">Спершу збережіть стиль.</div>'}</section>${s.id?abPanel(s):''}`}if(state.styleTab==='quality'){if(s.id&&state.styleStatsFor!==s.id){state.styleStatsFor=s.id;state.styleStats=null;loadStyleStats(s.id)}const st=state.styleStats,rate=v=>v==null?'—':`${v}%`;const proposal=state.styleImproveProposal;return `${s.id&&!isLandingStyle(s)?`<section class="panel"><h2>Реальна якість стилю</h2><p class="critic-note">Це фактичні показники з проєктів цього стилю, а не оцінка тексту промпта. Поправили промпт — за кілька проєктів побачите, чи виріс approve-rate і чи впала частка ручних правок.</p><div class="metrics">${st?`<div><small>Проєктів</small><b>${st.projects}</b></div><div><small>Схвалено з перевірених</small><b class="${(st.approve_rate??100)<70?'quality-bad':''}">${rate(st.approve_rate)}</b></div><div><small>Ручних правок HTML</small><b>${st.manual_edits}</b></div><div><small>Аварійні шаблони</small><b class="${st.fallback_rate>0?'quality-bad':''}">${rate(st.fallback_rate)}</b></div><div><small>AI-рецензент, сер.</small><b>${st.llm_avg==null?'—':st.llm_avg}${st.llm_reviews?` <small>(${st.llm_reviews})</small>`:''}</b></div>`:'<div class="empty">Завантаження…</div>'}</div>${st&&!st.projects?'<p class="muted-note">За цим стилем ще немає проєктів — метрики зʼявляться після перших генерацій.</p>':''}</section>`:''}<section class="panel"><div class="panel-tools"><h2>Лінт промпта</h2><div class="row"><button class="btn secondary" onclick="analyzeStyle()">Перевірити текст</button>${s.id?`<button class="btn ghost" onclick="loadStyleVersions('${s.id}')">Історія версій</button>`:''}</div></div><div class="metrics"><div><small>Узгодженість</small><b>${score.consistency||'—'}</b></div><div><small>Читабельність</small><b>${score.readability||'—'}</b></div><div><small>Відповідність</small><b>${score.brand_fit||'—'}</b></div></div>${state.styleIssues.length?`<div class="issue-list">${state.styleIssues.map(x=>`<div>${esc(x)}</div>`).join('')}</div>`:''}${state.styleVersions.length?`<h3 class="critic-block">Версії <small class="muted-note">клік — diff із поточним</small></h3><div class="version-list">${state.styleVersions.map(v=>`<button class="${state.styleDiffVersion===v.version?'active':''}" onclick="toggleVersionDiff(${v.version})"><b>v${v.version}</b><small>${dt(v.created_at)}</small></button>`).join('')}</div>${state.styleDiffVersion!=null?(()=>{const v=state.styleVersions.find(x=>x.version===state.styleDiffVersion);return v?`${diffHtml(v.prompt,s.prompt)}<div class="row"><button class="btn secondary" onclick="restoreStyleVersion(${v.version})">Відновити v${v.version}</button></div>`:''})():''}`:''}</section>${s.id?`<section class="panel"><h2>Покращити через AI</h2><label>Що покращити<textarea id="improveInstructions" rows="4" placeholder="Наприклад: зробити Hero преміальнішим і зменшити візуальний шум">${proposal?esc(proposal._req||''):''}</textarea></label><button class="btn primary" onclick="improveStyle('${s.id}',this)">Запропонувати зміни (платно)</button>${proposal?`<h3 class="critic-block">Пропозиція AI <small class="muted-note">diff проти поточного</small></h3>${diffHtml(proposal.current?.prompt||'',proposal.style_prompt||'')}<div class="row"><button class="btn primary" onclick="applyImprove()">Застосувати</button><button class="btn ghost" onclick="dismissImprove()">Відхилити</button></div>`:''}</section>`:''}`;}if(state.styleTab==='grid')return styleGridBlueprint(s);
return `<form class="panel style-form" onsubmit="saveStyle(event)" oninput="scheduleStyleAutosave(event)" onchange="scheduleStyleAutosave(event)"><input type="hidden" name="id" value="${esc(s.id||'')}">${state.styleTab==='general'?`${!s.id?`<fieldset><legend>Почати з основи</legend><div class="row" style="flex-wrap:wrap;gap:8px">${(state.styles||[]).filter(x=>MANAGED_STYLE_NAMES.includes(x.name)).map(x=>`<button type="button" class="preset-chip" onclick="baseNewStyleOn('${x.id}')">${esc(x.name)}</button>`).join('')}<button type="button" class="preset-chip" onclick="baseNewStyleOn('')">Порожній</button></div><p class="muted-note">Основа копіює промпти й палітру обраного стилю в новий — далі правте як власний. Вкладка «Сітка» одразу покаже структуру.</p></fieldset>`:''}<label>Назва<input name="name" value="${esc(s.name||'')}" required></label><label>Опис<textarea name="description" rows="5">${esc(s.description||'')}</textarea></label><label class="check"><input type="checkbox" name="is_default" ${s.is_default?'checked':''}> Використовувати за замовчуванням</label>`:''}${state.styleTab==='html'?`${promptOutline(s)}<label>Єдиний Style Prompt <em>${((s.prompt||'').length).toLocaleString('uk')} симв.</em><textarea name="prompt" rows="24">${esc(s.prompt||'')}</textarea></label>`:''}${state.styleTab==='colors'?`<p class="critic-note">Сітка й верстка стилю незмінні — кольори накладаються механічно ПІСЛЯ генерації, тому зламати макет тут неможливо. Порожня схема = фірмові кольори ARTLINE. Похідні відтінки (темніший/світліший акцент, межі) рахуються автоматично.</p>${paletteSwatchStrip(s.palette)}${(state.palettes||[]).length?`<div class="palette-presets"><small class="eyebrow">ПРЕСЕТИ</small><div class="row" style="flex-wrap:wrap;gap:8px">${state.palettes.map(p=>`<button type="button" class="preset-chip" onclick="applyPalettePreset('${p.id}',this)" title="Застосувати «${esc(p.name)}» до цього стилю">${paletteDots(p.tokens).split(',').map(c=>`<i style="background:${c}"></i>`).join('')} ${esc(p.name)}${can('style.manage')&&p.name!=='ARTLINE Cyan'?`<b onclick="event.stopPropagation();deletePalettePreset('${p.id}')" title="Видалити пресет">×</b>`:''}</button>`).join('')}${can('style.manage')?`<button type="button" class="btn ghost" onclick="savePalettePreset(this)">+ Зберегти поточну як пресет</button>`:''}</div></div>`:''}<div class="palette-grid">${Object.entries(PALETTE_LABELS).map(([key,[label,hint]])=>`<label class="palette-item"><span>${label}<small>${hint}</small></span><input type="color" name="palette_${key}" value="${esc((s.palette||{})[key]||PALETTE_DEFAULTS[key])}" oninput="refreshPaletteStrip(this.form)"></label>`).join('')}</div><label class="palette-item radius-item"><span>Скруглення кутів<small>глобально для всіх блоків цього стилю; капсули й кола не змінюються</small></span><span class="radius-control"><input type="range" name="palette_radius" min="0" max="200" step="25" value="${Math.round(((s.palette||{}).radius??1)*100)}" oninput="refreshPaletteStrip(this.form)"><b id="radiusValue">${Math.round(((s.palette||{}).radius??1)*100)}%</b></span></label><p class="muted-note" style="margin-top:4px">0% — гострі кути · 100% — фірмові · 200% — максимально мʼякі</p><div class="row"><button type="button" class="btn ghost" onclick="resetPalette(this)">Скинути до фірмових</button></div><p class="muted-note">Схема діє на НАСТУПНІ генерації цим стилем (rich-сторінки і лендінги). Уже створені сторінки не змінюються.</p>`:''}${state.styleTab==='images'?`<label>Промпт Hero <em>необов’язково</em><textarea name="hero_prompt" rows="10">${esc(s.hero_prompt||'')}</textarea></label><label>Промпт Feature <em>необов’язково</em><textarea name="feature_prompt" rows="10">${esc(s.feature_prompt||'')}</textarea></label><label>Негативний промпт<textarea name="negative_prompt" rows="7">${esc(s.negative_prompt||'')}</textarea></label>`:''}<div class="style-savebar"><span id="styleSaveStatus">${s.id?'Усі зміни зберігаються автоматично':'Заповніть поля та створіть стиль'}</span><div class="row">${s.id?styleDeleteButton(s):`<button class="btn primary">Створити стиль</button>`}</div></div></form>`}
// Always render the delete control, disabled with the reason — a button that simply
// vanishes leaves people hunting for it.
function styleDeleteButton(s){if(!can('style.manage'))return '';let why='';if(MANAGED_STYLE_NAMES.includes(s.name))why='Керований стиль — його відновлює система під час запуску';else if(s.is_default)why='Спершу призначте інший стиль за замовчуванням';return why?`<button type="button" class="btn danger" disabled title="${esc(why)}">Видалити стиль</button><span class="delete-why">${esc(why)}</span>`:`<button type="button" class="btn danger" onclick="deleteStyle('${s.id}')">Видалити стиль</button>`}
async function loadStylePreview(id){try{const d=await api(`/api/styles/${id}/preview`);if(state.stylePreviewFor!==id)return;state.stylePreview=d.html;state.stylePreviewSource=d.source;render()}catch(x){toast(x.message,true)}}
function currentEditStyle(){return state.styleEdit||state.styles[0]||{}}
async function onStyleSample(id){state.stylePreviewSample=id;const s=currentEditStyle(),sample=(state.styleSamples||[]).find(p=>p.id===id);if(id&&sample&&sample.style_id===s.id){await loadRealExample(s.id,id)}else{state.styleRealMode=false;state.stylePreviewSource='saved';loadStylePreview(s.id)}}
function onStyleVariant(v){state.stylePreviewVariant=v;const s=currentEditStyle(),sample=(state.styleSamples||[]).find(p=>p.id===state.stylePreviewSample);if(state.styleRealMode&&sample){loadRealExample(s.id,sample.id)}else{render()}}
async function loadRealExample(styleId,projectId){try{const d=await api(`/api/styles/${styleId}/real-example?project_id=${projectId}&variant=${state.stylePreviewVariant}`);state.stylePreviewFor=styleId;state.stylePreview=d.html;state.stylePreviewSource='real';state.styleRealMode=true;render()}catch(x){toast(x.message,true);state.styleRealMode=false;render()}}
async function generateStylePreview(id,button){const original=button?.textContent;if(button){button.disabled=true;button.textContent='Генерація…'}try{const d=await api(`/api/styles/${id}/preview`,{method:'POST',body:JSON.stringify({sample_project_id:state.stylePreviewSample,variant:state.stylePreviewVariant})});state.stylePreviewFor=id;state.stylePreview=d.html;state.stylePreviewSource=d.source;state.styles=await api('/api/styles');if(state.styleEdit?.id===id)state.styleEdit=state.styles.find(x=>x.id===id)||state.styleEdit;toast(d.source==='generated'?'AI-приклад згенеровано та збережено':'AI недоступний — показано демо-шаблон',d.source!=='generated');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function deleteStyle(id){if(!confirm('Видалити стиль? Проєкти, що його використовують, буде переприв’язано до базового стилю.'))return;try{const d=await api(`/api/styles/${id}`,{method:'DELETE'});state.styles=await api('/api/styles');state.styleEdit=state.styles.find(x=>x.is_default)||state.styles[0]||null;toast(d.reassigned_projects?`Стиль видалено, проєктів переприв’язано: ${d.reassigned_projects}`:'Стиль видалено');render()}catch(x){toast(x.message,true)}}
const paletteDots=t=>{const v=k=>(t&&t[k])||PALETTE_DEFAULTS[k];return `${v('accent')},${v('dark')},${v('light_soft')}`};
function paletteSelect(selected,withPhoto){const opts=[...(state.palettes||[])].sort((a,b)=>(a.name==='ARTLINE Cyan'?-1:b.name==='ARTLINE Cyan'?1:a.name.localeCompare(b.name,'en',{sensitivity:'base'}))).map(p=>`<option value="${p.id}" data-dots="${paletteDots(p.tokens)}" ${selected===p.id?'selected':''}>${esc(p.name)}</option>`).join('');const photo=withPhoto?`<option value="__photo__" data-dots="auto" data-tag="авто" ${selected==='__photo__'?'selected':''}>З фото товару</option>`:'';return `<label><span class="lbl">Кольорова схема ${hint('Бренд-пресет кольорів. «Як у стилі» — діє схема, задана у вкладці «Кольори» стилю. «З фото товару» — акцент і відтінки знімаються з головного фото цього товару перед генерацією; якщо фото без виразного кольору, лишається фірмова схема. Сітку сторінки схема не змінює ніколи.')}</span><select name="palette_id"><option value="" data-dots="${paletteDots(null)}" data-tag="стиль">Як у стилі</option>${photo}${opts}</select></label>`}
const PALETTE_DEFAULTS={accent:'#19BCC9',dark:'#101010',dark_soft:'#1A2128',light_soft:'#F5F7FA'};
const PALETTE_LABELS={accent:['Акцент','цифри, бейджі, кнопки; світлий і темний відтінки виводяться самі'],dark:['Темний фон','полотно Hero та фінального блоку; також колір заголовків на світлому'],dark_soft:['Темні картки','панелі й плитки показників; межі виводяться самі'],light_soft:['Світлі секції','мʼякий фон світлих блоків']};
function collectPalette(f){const base=(state.styleEdit||{}).palette||{};if(state.styleTab!=='colors')return base;const out={};for(const key of Object.keys(PALETTE_DEFAULTS)){const value=String(f.get(`palette_${key}`)||'').trim();if(/^#[0-9a-fA-F]{6}$/.test(value)&&value.toUpperCase()!==PALETTE_DEFAULTS[key].toUpperCase())out[key]=value.toUpperCase()}const radius=parseInt(f.get('palette_radius')||'100',10);if(!isNaN(radius)&&radius!==100)out.radius=radius/100;return out}
function collectStyleForm(f){const base=state.styleEdit||state.styles[0]||{};return {name:f.get('name')||base.name||'Новий стиль',description:f.get('description')??base.description??'',prompt:f.get('prompt')??base.prompt??'',hero_prompt:f.get('hero_prompt')??base.hero_prompt??'',feature_prompt:f.get('feature_prompt')??base.feature_prompt??'',negative_prompt:f.get('negative_prompt')??base.negative_prompt??'',score:base.score||{},palette:collectPalette(f),preview_html:base.preview_html||'',is_default:state.styleTab==='general'?f.get('is_default')==='on':!!base.is_default}}
function paletteSwatchStrip(p){const v=k=>(p&&p[k])||PALETTE_DEFAULTS[k];const rr=Math.round(14*((p&&p.radius!=null)?p.radius:1));return `<div class="palette-strip" id="paletteStrip"><span style="background:${v('dark')};border-radius:${rr}px"><i style="background:${v('accent')}"></i><b style="color:#fff">Темний блок</b></span><span style="background:${v('dark_soft')};border-radius:${rr}px"><i style="background:${v('accent')}"></i><b style="color:#fff">Картка</b></span><span style="background:${v('light_soft')};border:1px solid #D0D7DE;border-radius:${rr}px"><i style="background:${v('accent')}"></i><b style="color:#101010">Світла секція</b></span></div>`}
function refreshPaletteStrip(form){const p={};for(const key of Object.keys(PALETTE_DEFAULTS)){const input=form.querySelector(`input[name=palette_${key}]`);if(input)p[key]=input.value}const slider=form.querySelector('input[name=palette_radius]');if(slider){p.radius=parseInt(slider.value,10)/100;const out=document.getElementById('radiusValue');if(out)out.textContent=`${slider.value}%`}const strip=document.getElementById('paletteStrip');if(strip)strip.outerHTML=paletteSwatchStrip(p)}
function resetPalette(button){const form=button.closest('form');for(const [key,value] of Object.entries(PALETTE_DEFAULTS)){const input=form.querySelector(`input[name=palette_${key}]`);if(input)input.value=value}const slider=form.querySelector('input[name=palette_radius]');if(slider)slider.value=100;refreshPaletteStrip(form);form.dispatchEvent(new Event('input',{bubbles:true}))}
function applyPalettePreset(id,button){const preset=(state.palettes||[]).find(x=>x.id===id);if(!preset)return;const form=button.closest('form');for(const key of Object.keys(PALETTE_DEFAULTS)){const input=form.querySelector(`input[name=palette_${key}]`);if(input)input.value=(preset.tokens||{})[key]||PALETTE_DEFAULTS[key]}const slider=form.querySelector('input[name=palette_radius]');if(slider)slider.value=Math.round(((preset.tokens||{}).radius??1)*100);refreshPaletteStrip(form);form.dispatchEvent(new Event('input',{bubbles:true}));toast(`Схему «${preset.name}» застосовано до стилю`)}
async function savePalettePreset(button){const form=button.closest('form');const name=prompt('Назва пресета (наприклад, назва бренду):');if(!name)return;const tokens={};for(const key of Object.keys(PALETTE_DEFAULTS)){const input=form.querySelector(`input[name=palette_${key}]`);if(input&&input.value.toUpperCase()!==PALETTE_DEFAULTS[key].toUpperCase())tokens[key]=input.value.toUpperCase()}const slider=form.querySelector('input[name=palette_radius]');if(slider&&slider.value!=='100')tokens.radius=parseInt(slider.value,10)/100;try{await api('/api/palettes',{method:'POST',body:JSON.stringify({name,tokens})});state.palettes=await api('/api/palettes');toast('Пресет збережено — тепер його можна обирати при запуску проєктів');render()}catch(x){toast(x.message,true)}}
async function deletePalettePreset(id){if(!confirm('Видалити пресет? Минулі сторінки не зміняться.'))return;try{await api(`/api/palettes/${id}`,{method:'DELETE'});state.palettes=await api('/api/palettes');render()}catch(x){toast(x.message,true)}}
function styleSaveMessage(text,bad=false){const node=document.getElementById('styleSaveStatus');if(node){node.textContent=text;node.classList.toggle('bad',bad)}}
function scheduleStyleAutosave(e){const form=e.currentTarget,id=new FormData(form).get('id'),payload=collectStyleForm(new FormData(form));state.styleEdit={...(state.styleEdit||{}),...payload};if(!id)return;styleSaveRevision+=1;stylePendingSave={id,payload,revision:styleSaveRevision};clearTimeout(styleSaveTimer);styleSaveMessage('Є незбережені зміни…');styleSaveTimer=setTimeout(flushStyleAutosave,850)}
async function flushStyleAutosave(){if(styleSaveBusy||!stylePendingSave)return;const item=stylePendingSave;stylePendingSave=null;styleSaveBusy=true;styleSaveMessage('Збереження…');try{const saved=await api(`/api/styles/${item.id}`,{method:'PUT',body:JSON.stringify(item.payload)});state.styles=state.styles.map(x=>x.id===saved.id?saved:x);if(item.revision===styleSaveRevision)state.styleEdit=saved;styleSaveMessage('Збережено автоматично')}catch(x){styleSaveMessage('Помилка збереження',true);toast(x.message,true)}finally{styleSaveBusy=false;if(stylePendingSave){clearTimeout(styleSaveTimer);styleSaveTimer=setTimeout(flushStyleAutosave,300)}}}
async function saveStyle(e){e.preventDefault();if(pendingSave)return;pendingSave=true;const button=e.submitter;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Збереження…'}const f=new FormData(e.target),id=f.get('id'),payload=collectStyleForm(f);try{const d=await api(id?`/api/styles/${id}`:'/api/styles',{method:id?'PUT':'POST',body:JSON.stringify(payload)});state.styles=await api('/api/styles');state.styleEdit=state.styles.find(x=>x.id===(d.id||id))||state.styles[0];toast('Стиль збережено');render()}catch(x){toast(x.message,true)}finally{pendingSave=false;if(button){button.disabled=false;button.textContent=original}}}
function styleGeneratorDialog(){return `<dialog id="styleGenerator"><form onsubmit="generateStyle(event)"><div class="dialog-head"><div><small class="eyebrow">AI-ГЕНЕРАТОР СТИЛІВ</small><h2>Створити дизайн-стиль</h2></div><button type="button" aria-label="Закрити" onclick="styleGenerator.close()">×</button></div><label>Назва<input name="name" value="ARTLINE Premium" required></label><label>Опис бажаного результату<textarea name="brief" rows="8" placeholder="Категорія товару, настрій, структура блоків, рівень преміальності, обмеження..."></textarea></label><div class="form-grid"><label>Категорія<input name="category" placeholder="3D-принтери, енергетика, ігрові ПК..."></label><label>Настрій<input name="mood" placeholder="Преміальний, технічний, мінімалістичний..."></label></div><label>URL-референс <em>необов’язково</em><input name="reference_url" type="url"></label><label>Модель<input name="model" list="styleModels" value="${esc(state.models.default_text_model||'')}">${dataList('styleModels',state.models.text_models||[])}</label><button class="btn primary">Згенерувати</button></form></dialog>`}
async function generateStyle(e){e.preventDefault();const f=new FormData(e.target),button=e.submitter,original=button?.textContent;if(button){button.disabled=true;button.textContent='Генерація…'}try{const request=Object.fromEntries(f);request.brief=[request.brief,request.category&&`Category: ${request.category}`,request.mood&&`Mood: ${request.mood}`].filter(Boolean).join('\n');const d=await api('/api/styles/generate',{method:'POST',body:JSON.stringify(request)}),payload={name:f.get('name'),description:d.description||'',prompt:d.style_prompt||'',hero_prompt:d.hero_prompt||'',feature_prompt:d.feature_prompt||'',negative_prompt:d.negative_prompt||'',score:d.score||{},preview_html:d.preview_html||'',is_default:false},saved=await api('/api/styles',{method:'POST',body:JSON.stringify(payload)});state.styles=await api('/api/styles');state.styleEdit=state.styles.find(x=>x.id===saved.id)||saved;styleGenerator.close();state.styleTab='preview';toast('Стиль згенеровано та збережено');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
function lineDiff(a,b){const A=(a||'').split('\n'),B=(b||'').split('\n'),n=A.length,m=B.length;const dp=Array.from({length:n+1},()=>new Array(m+1).fill(0));for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)dp[i][j]=A[i]===B[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);const out=[];let i=0,j=0;while(i<n&&j<m){if(A[i]===B[j]){out.push(['ctx',A[i]]);i++;j++}else if(dp[i+1][j]>=dp[i][j+1]){out.push(['del',A[i]]);i++}else{out.push(['add',B[j]]);j++}}while(i<n){out.push(['del',A[i++]])}while(j<m){out.push(['add',B[j++]])}return out}
function diffHtml(a,b){const rows=lineDiff(a,b);if(!rows.some(([t])=>t!=='ctx'))return '<p class="muted-note">Змін немає.</p>';const sign={ctx:' ',add:'+',del:'\u2212'};return `<pre class="stylediff">${rows.map(([t,l])=>`<span class="d-${t}">${sign[t]} ${esc(l)||' '}</span>`).join('\n')}</pre>`}
async function loadStyleStats(id){if(!id){state.styleStats=null;return}try{state.styleStats=await api(`/api/styles/${id}/stats`);state.styleStatsFor=id;render()}catch{state.styleStats=null}}
async function loadStyleSamples(){try{state.styleSamples=await api('/api/styles/sample-products')}catch{state.styleSamples=[]}}
async function runStyleDryRun(){const s=state.styleEdit||{};try{state.styleDryRun=await api('/api/styles/dry-run',{method:'POST',body:JSON.stringify({prompt:s.prompt||'',hero_prompt:s.hero_prompt||'',feature_prompt:s.feature_prompt||'',negative_prompt:s.negative_prompt||'',variant:state.stylePreviewVariant,sample_project_id:state.stylePreviewSample})});render()}catch(x){toast(x.message,true)}}
function closeDryRun(){state.styleDryRun=null;render()}
function toggleVersionDiff(version){state.styleDiffVersion=state.styleDiffVersion===version?null:version;render()}
function dismissImprove(){state.styleImproveProposal=null;render()}
async function applyImprove(){const d=state.styleImproveProposal,s=state.styleEdit;if(!d||!s?.id)return;try{const payload={name:s.name,description:d.description||s.description||'',prompt:d.style_prompt||s.prompt||'',hero_prompt:d.hero_prompt||s.hero_prompt||'',feature_prompt:d.feature_prompt||s.feature_prompt||'',negative_prompt:d.negative_prompt||s.negative_prompt||'',score:s.score||{},preview_html:s.preview_html||'',is_default:!!s.is_default},saved=await api(`/api/styles/${s.id}`,{method:'PUT',body:JSON.stringify(payload)});state.styles=state.styles.map(x=>x.id===saved.id?saved:x);state.styleEdit=saved;state.styleImproveProposal=null;state.styleTab='html';toast('Покращену версію застосовано');render()}catch(x){toast(x.message,true)}}
async function pinGolden(id){if(!id)return;try{await api(`/api/styles/${id}/golden`,{method:'POST'});state.styles=state.styles.map(x=>x.id===id?{...x,has_golden:true}:x);if(state.styleEdit?.id===id)state.styleEdit={...state.styleEdit,has_golden:true};toast('Поточний приклад закріплено як еталон формату');render()}catch(x){toast(x.message,true)}}
async function clearGolden(id){if(!id)return;try{await api(`/api/styles/${id}/golden`,{method:'DELETE'});state.styles=state.styles.map(x=>x.id===id?{...x,has_golden:false}:x);if(state.styleEdit?.id===id)state.styleEdit={...state.styleEdit,has_golden:false};toast('Еталон прибрано');render()}catch(x){toast(x.message,true)}}
async function runStyleAB(button){const s=state.styleEdit;if(!s?.id)return;const versions=state.styleVersions||[];let promptB=s.prompt;if(state.styleImproveProposal){promptB=state.styleImproveProposal.style_prompt||s.prompt}else if(state.styleABVersion){const v=versions.find(x=>String(x.version)===String(state.styleABVersion));if(v)promptB=v.prompt}if(promptB===s.prompt){toast('Оберіть версію або згенеруйте AI-пропозицію для порівняння',true);return}const original=button?.textContent;if(button){button.disabled=true;button.textContent='Два прогони…'}try{state.styleAB=await api(`/api/styles/${s.id}/ab`,{method:'POST',body:JSON.stringify({prompt_a:s.prompt,prompt_b:promptB,variant:state.stylePreviewVariant,sample_project_id:state.stylePreviewSample})});toast('A/B готово');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
function closeAB(){state.styleAB=null;render()}
function abPanel(s){const versions=state.styleVersions||[];const ready=state.styleImproveProposal||state.styleABVersion;return `<section class="panel"><div class="panel-tools"><h2>A/B двох версій</h2><div class="row">${state.styleImproveProposal?'<span class="muted-note">B = AI-пропозиція</span>':`<select onchange="state.styleABVersion=this.value;render()"><option value="">Порівняти з версією…</option>${versions.map(v=>`<option value="${v.version}" ${String(state.styleABVersion)===String(v.version)?'selected':''}>v${v.version}</option>`).join('')}</select>${versions.length?'':`<button class="btn ghost" onclick="loadStyleVersions('${s.id}')">Завантажити версії</button>`}`}<button class="btn primary" ${ready?'':'disabled'} onclick="runStyleAB(this)">Порівняти (2 прогони, платно)</button></div></div><p class="muted-note">Обидва промпти генеруються на ОДНОМУ товарі — видно, який блок кращий. A = поточний, B = обрана версія або AI-пропозиція.</p>${state.styleAB?`<div class="ab-grid"><div><b>A · поточний${state.styleAB.a.fallback?' ⚠ аварійний':''}</b><div class="preview-canvas ${state.styleAB.variant}"><iframe title="A" sandbox="allow-same-origin" srcdoc="${esc(previewDocument(state.styleAB.a.html))}"></iframe></div></div><div><b>B · пропозиція${state.styleAB.b.fallback?' ⚠ аварійний':''}</b><div class="preview-canvas ${state.styleAB.variant}"><iframe title="B" sandbox="allow-same-origin" srcdoc="${esc(previewDocument(state.styleAB.b.html))}"></iframe></div></div></div><div class="row"><button class="btn ghost" onclick="closeAB()">Закрити порівняння</button></div>`:''}</section>`}
async function analyzeStyle(){const s=state.styleEdit||{};try{const d=await api('/api/styles/analyze',{method:'POST',body:JSON.stringify({prompt:s.prompt||'',hero_prompt:s.hero_prompt||'',feature_prompt:s.feature_prompt||'',negative_prompt:s.negative_prompt||''})}),updated={...s,score:d.score};state.styleEdit=updated;state.styleIssues=d.issues||[];if(s.id){const saved=await api(`/api/styles/${s.id}`,{method:'PUT',body:JSON.stringify({name:updated.name,description:updated.description||'',prompt:updated.prompt||'',hero_prompt:updated.hero_prompt||'',feature_prompt:updated.feature_prompt||'',negative_prompt:updated.negative_prompt||'',score:updated.score||{},preview_html:updated.preview_html||'',is_default:!!updated.is_default})});state.styles=state.styles.map(x=>x.id===saved.id?saved:x);state.styleEdit=saved}toast(d.ready?'Стиль перевірено та збережено':'Рекомендації збережено',!d.ready);render()}catch(x){toast(x.message,true)}}
async function loadStyleVersions(id){try{state.styleVersions=await api(`/api/styles/${id}/versions`);render()}catch(x){toast(x.message,true)}}
async function restoreStyleVersion(version){const v=state.styleVersions.find(x=>x.version===version),s=state.styleEdit;if(!v||!s?.id)return;try{const payload={name:s.name,description:s.description||'',prompt:v.prompt||'',hero_prompt:v.hero_prompt||'',feature_prompt:v.feature_prompt||'',negative_prompt:s.negative_prompt||'',score:s.score||{},preview_html:s.preview_html||'',is_default:!!s.is_default},saved=await api(`/api/styles/${s.id}`,{method:'PUT',body:JSON.stringify(payload)});state.styles=state.styles.map(x=>x.id===saved.id?saved:x);state.styleEdit=saved;state.styleTab='html';toast(`Версію v${version} відновлено та збережено`);render()}catch(x){toast(x.message,true)}}
async function improveStyle(id,button){const original=button?.textContent;if(button){button.disabled=true;button.textContent='Аналіз…'}try{const d=await api(`/api/styles/${id}/improve`,{method:'POST',body:JSON.stringify({instructions:improveInstructions.value,model:state.models.default_text_model})});state.styleImproveProposal=d;toast('Пропозицію готово — перегляньте diff і застосуйте');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
function mediaPage(){const filters=[['all','Усі джерела'],['generated','Згенеровані AI'],['source','Вихідні фото товару'],['custom','Власні фото']],roles=[['all','Усі ролі'],['hero','Hero'],['feature','Feature'],['reference','Референси'],['other','Інші']],sorts=[['created_desc','Спочатку нові'],['created_asc','Спочатку старі'],['size_desc','Найбільша роздільність'],['cost_desc','Найвища вартість'],['project_asc','За назвою проєкту'],['role_asc','За типом зображення']],projects=[...new Map(state.assets.filter(x=>x.project_id).map(x=>[x.project_id,x.project_name||x.project_id])).entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1]),'uk'));let rows=[...state.assets];if(state.mediaFilter!=='all')rows=rows.filter(x=>assetCategory(x)===state.mediaFilter);if(state.mediaRole!=='all')rows=rows.filter(x=>assetRole(x)===state.mediaRole);if(state.mediaProject!=='all')rows=rows.filter(x=>x.project_id===state.mediaProject);const q=state.mediaSearch.trim().toLowerCase();if(q)rows=rows.filter(x=>[x.project_name,assetLabel(x),x.model,x.prompt].some(v=>String(v||'').toLowerCase().includes(q)));rows.sort((a,b)=>{if(state.mediaSort==='created_asc')return new Date(a.created_at)-new Date(b.created_at);if(state.mediaSort==='size_desc')return Number(b.width||0)*Number(b.height||0)-Number(a.width||0)*Number(a.height||0);if(state.mediaSort==='cost_desc')return Number(b.cost||0)-Number(a.cost||0);if(state.mediaSort==='project_asc')return String(a.project_name||'').localeCompare(String(b.project_name||''),'uk');if(state.mediaSort==='role_asc')return assetRole(a).localeCompare(assetRole(b))||new Date(b.created_at)-new Date(a.created_at);return new Date(b.created_at)-new Date(a.created_at)});shell(`<header class="pagehead"><div><small class="eyebrow">МЕДІАТЕКА</small><h1>Медіа</h1><p>Знаходьте зображення за проєктом, призначенням, джерелом і параметрами.</p></div></header><section class="toolbar media-toolbar advanced"><input placeholder="Пошук за проєктом, моделлю або промптом" value="${esc(state.mediaSearch)}" oninput="state.mediaSearch=this.value;render()"><select onchange="state.mediaFilter=this.value;render()">${filters.map(([value,label])=>`<option value="${value}" ${state.mediaFilter===value?'selected':''}>${label}</option>`).join('')}</select><select onchange="state.mediaRole=this.value;render()">${roles.map(([value,label])=>`<option value="${value}" ${state.mediaRole===value?'selected':''}>${label}</option>`).join('')}</select><select onchange="state.mediaProject=this.value;render()"><option value="all">Усі проєкти</option>${projects.map(([id,name])=>`<option value="${esc(id)}" ${state.mediaProject===id?'selected':''}>${esc(name)}</option>`).join('')}</select><select onchange="state.mediaSort=this.value;render()">${sorts.map(([value,label])=>`<option value="${value}" ${state.mediaSort===value?'selected':''}>${label}</option>`).join('')}</select><b>${rows.length} файлів</b></section><section class="media-grid">${rows.map(mediaCard).join('')||'<div class="empty">За обраними фільтрами зображень немає.</div>'}</section><dialog id="assetDetails"></dialog>`) }
function usagePage(){const q=state.usage.quality||{};const rate=v=>v==null?'—':`${v}%`;const periods=[[7,'7 днів'],[30,'30 днів'],[90,'90 днів'],[365,'Рік'],[0,'Весь час']];const activeUser=(state.usage.by_user||[]).find(u=>u.user_id===state.usageUser);shell(`<header class="pagehead"><div><small class="eyebrow">ВИКОРИСТАННЯ</small><h1>Використання</h1><p>Час, токени, вартість і довіра до результату${activeUser?` · фільтр: <b>${esc(activeUser.name)}</b>`:''}.</p></div><div><select onchange="setUsageFilter(this.value,null)">${periods.map(([v,l])=>`<option value="${v}" ${state.usageDays===v?'selected':''}>${l}</option>`).join('')}</select>${state.usageUser?`<button class="btn secondary" onclick="setUsageFilter(null,'')">Зняти фільтр користувача</button>`:''}</div></header><section class="metrics large"><div><small>Загальна вартість</small><b>${money(state.usage.total_cost)}</b></div><div><small>Проєкти</small><b>${state.usage.projects||0}</b></div><div><small>Вхідні токени</small><b>${state.usage.input_tokens||0}</b></div><div><small>Вихідні токени</small><b>${state.usage.output_tokens||0}</b></div><div><small>Зображення</small><b>${state.usage.images||0}</b></div></section><section class="panel"><h2>Динаміка витрат</h2>${usageChart()}</section>${usageStagePanel()}${usageUserTable()}<section class="panel quality-panel"><h2>Якість результату</h2><p class="critic-note">Головний показник корисності інструмента: скільки перевірених сторінок команда схвалює і як часто доводиться правити HTML руками. Якщо частка схвалень падає нижче ~70% — генерація потребує уваги.</p><div class="metrics"><div><small>Схвалено з перевірених</small><b class="${(q.approve_rate??100)<70?'quality-bad':''}">${rate(q.approve_rate)}</b></div><div><small>Схвалено без запиту змін</small><b>${rate(q.clean_approve_rate)}</b></div><div><small>Перевірено проєктів</small><b>${q.reviewed_projects||0}</b></div><div><small>Ручних правок HTML</small><b>${q.manual_html_edits||0}</b></div><div><small>Згенеровано сторінок</small><b>${q.generated_pages||0}</b></div></div></section>`)}
function usersPage(){shell(`<header class="pagehead"><div><small class="eyebrow">ДОСТУП</small><h1>Користувачі</h1><p>Створюйте облікові записи безпосередньо або запрошуйте за посиланням.</p></div><div><button class="btn secondary" onclick="inviteDialog.showModal()">Запросити</button><button class="btn primary" onclick="createUserDialog.showModal()">+ Створити користувача</button></div></header><section class="panel table-wrap"><table><thead><tr><th>Користувач</th><th>Роль</th><th>Активний</th><th>Ліміт $/день</th><th>Останній вхід</th><th>Дії</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><b>${esc(u.name||u.email)}</b>${u.is_root?'<span class="cat-chip" style="margin-left:6px">Головний</span>':''}<small>${esc(u.email)}</small></td><td>${u.is_root?`<span class="badge approved">${ROLE_LABEL[u.role]}</span>`:`<select onchange="updateUser('${u.id}','role',this.value)">${['admin','editor','reviewer','viewer'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${ROLE_LABEL[r]}</option>`).join('')}</select>`}</td><td><input type="checkbox" ${u.active?'checked':''} ${u.is_root?'disabled':''} onchange="updateUser('${u.id}','active',this.checked)"></td><td><div class="budget-cell"><input type="number" min="0" max="10000" step="1" value="${u.daily_budget_usd||0}" title="0 = без особистого ліміту" onchange="updateUser('${u.id}','daily_budget_usd',Math.max(0,Number(this.value)||0))"><small>${u.daily_budget_usd>0?`$${(u.today_spend_usd||0).toFixed(2)} сьогодні`:'без ліміту'}</small></div></td><td title="${dt(u.last_login_at)}">${rel(u.last_login_at)}</td><td><div class="row">${u.is_root?'<small class="muted-note">Керується через .env</small>':`<button class="btn ghost" onclick="openPerms('${u.id}')">Доступи</button><button class="btn ghost" onclick="resetPassword('${u.id}')">Пароль</button>${u.id!==state.me.id?`<button class="btn danger" onclick="deleteUser('${u.id}')">Видалити</button>`:''}`}</div></td></tr>`).join('')}</tbody></table></section>${userDialogs()}`)}
function userDialogs(){return `<dialog id="createUserDialog"><form onsubmit="createUser(event)"><div class="dialog-head"><h2>Створити користувача</h2><button type="button" aria-label="Закрити" onclick="createUserDialog.close()">×</button></div><label>Ім’я<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Пароль<input name="password" type="password" minlength="8" required></label><label>Роль<select name="role"><option value="editor">Редактор</option><option value="reviewer">Рев’юер</option><option value="viewer">Перегляд</option><option value="admin">Адміністратор</option></select></label><button class="btn primary">Створити</button></form></dialog><dialog id="inviteDialog"><form onsubmit="inviteUser(event)"><div class="dialog-head"><h2>Запросити користувача</h2><button type="button" aria-label="Закрити" onclick="inviteDialog.close()">×</button></div><label>Email<input name="email" type="email" required></label><label>Роль<select name="role"><option value="editor">Редактор</option><option value="reviewer">Рев’юер</option><option value="viewer">Перегляд</option><option value="admin">Адміністратор</option></select></label><button class="btn primary">Створити посилання</button></form></dialog>`}
async function createUser(e){e.preventDefault();try{await api('/api/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});createUserDialog.close();state.users=await api('/api/users');toast('Користувача створено');render()}catch(x){toast(x.message,true)}}
async function inviteUser(e){e.preventDefault();try{const d=await api('/api/users/invites',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});inviteDialog.close();toast(`Запрошення створено. Попросіть користувача просто увійти через GitHub або Google з email ${d.email||''} — обліковий запис зʼявиться автоматично`);loadAll().then(render)}catch(x){toast(x.message,true)}}
async function updateUser(id,key,value){await api(`/api/users/${id}`,{method:'PATCH',body:JSON.stringify({[key]:value})});state.users=await api('/api/users');render()}
async function resetPassword(id){const password=prompt('Новий пароль (щонайменше 8 символів)');if(!password)return;try{await api(`/api/users/${id}/password`,{method:'POST',body:JSON.stringify({password})});toast('Пароль оновлено')}catch(x){toast(x.message,true)}}
async function deleteUser(id){if(!confirm('Видалити користувача?'))return;try{await api(`/api/users/${id}`,{method:'DELETE'});state.users=await api('/api/users');toast('Користувача видалено');render()}catch(x){toast(x.message,true)}}
async function openPerms(id){const u=state.users.find(x=>x.id===id);if(!u)return;try{if(!state.permCatalog)state.permCatalog=await api('/api/permissions')}catch(x){return toast(x.message,true)}const cat=state.permCatalog,defaults=new Set(cat.role_defaults[u.role]||[]),eff=new Set(u.permissions||[]);let dlg=document.getElementById('permsDialog');if(!dlg){dlg=document.createElement('dialog');dlg.id='permsDialog';document.body.appendChild(dlg)}dlg.innerHTML=`<form onsubmit="savePerms(event,'${u.id}')"><div class="dialog-head"><div><small class="eyebrow">ДОСТУПИ</small><h2>${esc(u.name||u.email)}</h2></div><button type="button" aria-label="Закрити" onclick="permsDialog.close()">×</button></div><p class="muted-note">Роль <b>${ROLE_LABEL[u.role]||u.role}</b> дає базовий набір прав (позначено «за роллю»). Тут можна точково додати або прибрати окремі права саме цьому користувачу.</p><div class="perm-list">${cat.permissions.map(p=>`<label class="check perm-row"><input type="checkbox" name="perm" value="${p.key}" ${eff.has(p.key)?'checked':''}><span><b>${esc(p.label)}</b>${defaults.has(p.key)?'<em class="perm-default">за роллю</em>':''}</span></label>`).join('')}</div><button class="btn primary">Зберегти доступи</button></form>`;dlg.showModal()}
async function savePerms(e,id){e.preventDefault();const u=state.users.find(x=>x.id===id),defaults=new Set(state.permCatalog.role_defaults[u.role]||[]),form=e.currentTarget;const checked=new Set([...form.querySelectorAll('[name=perm]:checked')].map(x=>x.value));const grant=[],revoke=[];state.permCatalog.permissions.forEach(p=>{const on=checked.has(p.key),def=defaults.has(p.key);if(on&&!def)grant.push(p.key);if(!on&&def)revoke.push(p.key)});try{await api(`/api/users/${id}/permissions`,{method:'PATCH',body:JSON.stringify({grant,revoke})});state.users=await api('/api/users');if(id===state.me.id)state.me=await api('/api/me');form.closest('dialog').close();toast('Доступи оновлено');render()}catch(x){toast(x.message,true)}}
const fmtBytes=n=>{if(!n)return '0 Б';const u=['Б','КБ','МБ','ГБ','ТБ'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(n>=10||i===0?0:1)} ${u[i]}`};
const okBadge=(ok,yes='Працює',no='Недоступно')=>`<span class="badge ${ok?'approved':'error'}">${ok?yes:no}</span>`;
const isReasoning=(x,list)=>(list||[]).includes(x);
function modelList(items,reasoning){return `<div class="model-list">${(items||[]).map(x=>`<code class="${isReasoning(x,reasoning)?'is-reasoning':''}" ${isReasoning(x,reasoning)?'title="Витрачає токени на приховані міркування"':''}>${esc(x)}</code>`).join('')||'<small class="muted-note">Порожньо.</small>'}</div>`}
function modelNotes(){const m=state.models||{},gone=m.unavailable||[],np=m.unpriced||[];return `${gone.length?`<p class="critic-note">Налаштовані, але недоступні на цьому ключі: ${gone.map(x=>`<code>${esc(x)}</code>`).join(' ')}. Приберіть їх із <code>.env</code> або перевірте доступ у обліковому записі.</p>`:''}${np.length?`<p class="critic-note">Без відомої ціни: ${np.map(x=>`<code>${esc(x)}</code>`).join(' ')}. Генерація працює, але оцінка вартості для них буде приблизною — ${state.me?.is_root?'додайте тариф у <code>TEXT_PRICING_JSON</code> / <code>IMAGE_PRICING_JSON</code>.':'зверніться до адміністратора.'}</p>`:''}`}
function settingsPage(){const s=state.system;shell(`<header class="pagehead"><div><small class="eyebrow">НАЛАШТУВАННЯ</small><h1>Налаштування</h1><p>Стан системи, конфігурація та доступні моделі. ${state.me?.is_root?'Ключі змінюються тут, решта — у <code>.env</code> на сервері.':'Конфігурацією керує адміністратор.'}</p></div><div><button class="btn secondary" onclick="reloadSystem(this)">Оновити стан</button><button class="btn secondary" onclick="reloadModels()">Оновити моделі</button></div></header>
${s?`<section class="panel"><h2>Стан системи</h2><div class="metrics settings-metrics">${s.version?`<div><small>Версія</small><b>v${esc(s.version)}</b></div>`:''}<div><small>OpenAI API</small><b>${okBadge(s.openai_configured,'Налаштовано','Немає ключа')}</b></div><div><small>Gemini API</small><b>${s.gemini_configured?okBadge(true,'Налаштовано'):'<span class="muted-note">не підключено</span>'}</b></div><div><small>Черга (Redis)</small><b>${okBadge(s.redis_ok)}</b></div><div><small>Worker</small><b>${okBadge(s.worker_ok)}</b></div><div><small>Сторож генерації</small><b>${s.watchdog_minutes} хв</b></div>${s.queued_watchdog_hours?`<div><small>Попередження про довгу чергу</small><b>після ${s.queued_watchdog_hours} год</b></div>`:''}<div><small>Бюджет сьогодні ${hint(state.me?.is_root?'Денна стеля витрат на AI (DAILY_BUDGET_USD у .env). Після вичерпання нові генерації зупиняються до наступної доби; запущені — завершуються.':'Денна стеля витрат на AI. Після вичерпання нові генерації зупиняються до наступної доби; запущені — завершуються.')}</small><b>${s.daily_budget_usd>0?`$${(s.today_spend_usd||0).toFixed(2)} із $${s.daily_budget_usd.toFixed(0)}`:'вимкнено'}</b></div><div><small>Сповіщення</small><b>${s.alerts_telegram||s.alerts_webhook?[s.alerts_telegram?'Telegram':'',s.alerts_webhook?'Webhook':''].filter(Boolean).join(' + '):'<span class="muted-note">вимкнено</span>'}</b></div></div>${!s.openai_configured?'<p class="critic-note">Без ключа OpenAI генерація працює в офлайн-режимі на вбудованому шаблоні.</p>':''}${!s.worker_ok?'<p class="critic-note">Worker не відповідає — нові проєкти застрягнуть у черзі. Перевірте <code>docker compose ps</code> на сервері.</p>':''}</section>
<section class="two"><div class="panel"><h2>Дані</h2><div class="metrics"><div><small>Проєкти</small><b>${s.projects}</b></div><div><small>Стилі</small><b>${s.styles}</b></div><div><small>Користувачі</small><b>${s.users}</b></div></div><div class="metrics"><div><small>Медіафайли</small><b>${s.media_files} · ${fmtBytes(s.media_bytes)}</b></div>${state.me?.is_root?`<div><small>Вільно на диску</small><b class="${s.disk_free_bytes&&s.disk_free_bytes<5*1024**3?'quality-bad':''}">${fmtBytes(s.disk_free_bytes)}</b></div>`:''}${state.me?.is_root?`<div><small>Схема БД</small><b>${esc(s.db_schema)}</b></div>`:''}</div></div><div class="panel"><h2>Моделі за замовчуванням</h2><div class="metrics"><div><small>Текст</small><b>${esc(s.default_text_model)}</b></div><div><small>Зображення</small><b>${esc(s.default_image_model)}</b></div><div><small>Reasoning effort</small><b>${esc(s.reasoning_effort||'—')}</b></div></div><p class="muted-note">Модель для конкретного проєкту можна змінити в діалозі створення.</p></div></section>`:'<section class="panel"><div class="empty">Завантаження стану системи…</div></section>'}
<section class="two"><div class="panel"><h2>Текстові моделі ${hint('Перелік задається у OPENAI_TEXT_MODELS в .env. Тут показані лише ті, що доступні на поточному ключі. Разову модель поза списком можна ввести в діалозі створення проєкту.')}</h2>${modelList(state.models.text_models,state.models.reasoning_models)}<h2>Моделі зображень ${hint('OPENAI_IMAGE_MODELS у .env плюс моделі Gemini, якщо збережено ключ Gemini.')}</h2>${modelList(state.models.image_models)}${modelNotes()}</div><div class="panel"><h2>Моделі міркування ${hint('Це не окремий список моделей, а ті з ваших текстових моделей, що витрачають частину бюджету відповіді на приховані міркування. Обсяг міркувань задається OPENAI_REASONING_EFFORT.')}</h2>${(state.models.reasoning_models||[]).length?modelList(state.models.reasoning_models):'<p class="muted-note">Жодна з обраних текстових моделей не витрачає токени на міркування.</p>'}<p class="muted-note">Джерело переліку: <b>${esc(state.models.source||'—')}</b>${state.models.source==='configuration+verified'?' — перевірено на живому ключі OpenAI':''}</p></div></section>
${secretsPanel()}
<section class="panel"><h2>Довідка</h2>${s?.code_graph_url?`<p class="muted-note"><a class="link" href="${s.code_graph_url}" target="_blank" rel="noopener">Мапа кодової бази (Graphify)</a> — інтерактивний граф модулів і зв'язків проєкту.</p>`:''}${state.me?.is_root?`<p class="muted-note">Посібник редактора — <code>docs/USER_GUIDE.md</code>, деплой і бекапи — <code>docs/DEPLOY.md</code> у репозиторії. Бекап БД створюється автоматично щодня контейнером <code>backup</code>.</p>`:'<p class="muted-note">З питань конфігурації та резервних копій зверніться до адміністратора.</p>'}</section>
${techStrip()}`)}
// Running strip of the technologies behind the studio (settings footer).
// Pure CSS marquee: two identical sequences, keyframes shift the track by -50%,
// so the full-page innerHTML re-render cannot desync it (no JS state to lose).
const TECH_STACK=[
 ['Python','#3776AB','https://www.python.org'],
 ['FastAPI','#009688','https://fastapi.tiangolo.com'],
 ['Celery','#37814A','https://docs.celeryq.dev'],
 ['PostgreSQL','#4169E1','https://www.postgresql.org'],
 ['Alembic','#6E7781','https://alembic.sqlalchemy.org'],
 ['Redis','#FF4438','https://redis.io'],
 ['Docker','#2496ED','https://www.docker.com'],
 ['Nginx','#009639','https://nginx.org'],
 ['Caddy','#6E7781','https://caddyserver.com'],
 ['OpenAI','#10A37F','https://platform.openai.com'],
 ['Gemini','#4E82EE','https://ai.google.dev'],
 ['OpenRouter','#6D64BB','https://openrouter.ai'],
 ['Vanilla JS','#D9B60A','https://developer.mozilla.org/docs/Web/JavaScript'],
];
function techStrip(){const seq=hidden=>`<div class="techloop-seq"${hidden?' aria-hidden="true"':''}>${TECH_STACK.map(([name,color,href])=>`<a class="techloop-item" style="--c:${color}" href="${href}" target="_blank" rel="noreferrer noopener">${name}</a>`).join('')}</div>`;
return `<section class="panel techloop-panel"><h2>Технології</h2><div class="techloop" role="region" aria-label="Використані технології"><div class="techloop-track">${seq(false)}${seq(true)}</div></div></section>`}

function balanceStrip(){const b=state.balances;if(!b)return '';const usd=v=>v==null?null:`$${Number(v).toFixed(2)}`;const row=(name,x)=>{if(!x.configured)return `<div><small>${name}</small><b class="muted-note">ключ не задано</b></div>`;const main=usd(x.balance)??usd(x.spend_30d)??'—';const capt=x.balance!=null?'на рахунку':'витрачено студією за 30 днів';return `<div><small>${name} · ${capt}${x.note?` ${hint(x.note)}`:''}</small><b>${main}</b></div>`};return `<div class="metrics">${row('OpenAI',b.openai)}${row('Gemini',b.gemini)}${row('OpenRouter',b.openrouter)}</div>`}
function secretsPanel(){if(!state.me?.is_root)return '';const k=state.secrets;if(!k)return `<section class="panel"><h2>Ключі та провайдер</h2><div class="empty">Завантаження…</div></section>`;const src=v=>v==='database'?'<span class="key-src db">збережено в БД</span>':v==='env'?'<span class="key-src env">з .env</span>':'<span class="key-src none">не задано</span>';const or=k.llm_provider==='openrouter';return `<section class="panel"><div class="panel-tools"><h2>Ключі та провайдер ${hint('Доступно лише головному адміністратору. Ключ зберігається в базі й перекриває значення з .env. API і worker підхоплюють новий ключ протягом ~15 секунд без перезапуску.')}</h2><div class="row"><button class="btn secondary" onclick="testSecrets(this)">Перевірити зв’язок</button></div></div>${balanceStrip()}<form class="secrets-form" onsubmit="saveSecrets(event)"><label>Провайдер тексту<select name="llm_provider" onchange="state.secrets.llm_provider=this.value;render()">${[['openai','OpenAI'],['openrouter','OpenRouter'],['local','Локальний сервер']].map(([v,l])=>`<option value="${v}" ${k.llm_provider===v?'selected':''}>${l}</option>`).join('')}</select></label><label>OpenAI API key ${src(k.openai_api_key_source)}<input name="openai_api_key" autocomplete="off" spellcheck="false" placeholder="${k.openai_api_key?esc(k.openai_api_key):'sk-…'}"></label><label>Gemini API key ${src(k.gemini_api_key_source)} ${hint('Додає моделі Nano Banana до списку моделей зображень у діалозі створення проєкту. Вони краще зберігають зовнішній вигляд товару і коштують у рази дешевше за gpt-image-1 high.')}<input name="gemini_api_key" autocomplete="off" spellcheck="false" placeholder="${k.gemini_api_key?esc(k.gemini_api_key):'AIza…'}"></label>${or?`<label>OpenRouter API key ${src(k.openrouter_api_key_source)}<input name="openrouter_api_key" autocomplete="off" spellcheck="false" placeholder="${k.openrouter_api_key?esc(k.openrouter_api_key):'sk-or-v1-…'}"></label><label>Модель OpenRouter<input name="openrouter_text_model" value="${esc(k.openrouter_text_model||'')}" spellcheck="false" placeholder="openai/gpt-4o-mini"></label>`:''}${k.llm_provider==='local'?`<label>Базовий URL локального сервера ${hint('OpenAI-сумісний ендпоінт: Ollama — http://IP:11434/v1, vLLM — http://IP:8000/v1, LM Studio — http://IP:1234/v1. Текст піде на нього; зображення завжди лишаються хмарними.')}<input name="local_base_url" value="${esc(k.local_base_url||'')}" spellcheck="false" placeholder="http://192.168.1.50:11434/v1"></label><label>API key локального сервера <em>необовʼязково</em><input name="local_api_key" autocomplete="off" spellcheck="false" placeholder="${k.local_api_key?esc(k.local_api_key):'порожньо, якщо сервер не вимагає'}"></label><label>Моделі локального сервера (через кому)<input name="local_text_models" value="${esc(k.local_text_models||'')}" spellcheck="false" placeholder="qwen2.5:14b, llama3.1:8b"></label><p class="critic-note">Локальні моделі показуються в діалозі створення замість хмарних і рахуються за $0. Якість дотримання формату нижча за gpt-5-mini — стежте за частотою аварійних шаблонів.</p>`:''}<p class="muted-note">Поле порожнє — ключ не змінюється. Щоб прибрати збережений ключ і повернутись до <code>.env</code>, введіть <code>-</code>.</p>${or?'<p class="critic-note">OpenRouter обслуговує лише текст: генерація зображень завжди йде через OpenAI, бо Images Edit з <code>input_fidelity</code> в OpenRouter немає. Ключ OpenAI має лишатись заповненим.</p>':''}<div class="row"><button class="btn primary">Зберегти ключі</button></div></form></section>`}
async function loadSecrets(){if(!state.me?.is_root)return;try{state.secrets=await api('/api/secrets')}catch{state.secrets=null}
try{state.balances=await api('/api/providers/balance')}catch{state.balances=null}}
async function saveSecrets(e){e.preventDefault();const f=new FormData(e.target),body={llm_provider:f.get('llm_provider')};for(const key of ['openai_api_key','gemini_api_key','openrouter_api_key','openrouter_text_model','local_base_url','local_api_key','local_text_models']){if(!f.has(key))continue;const v=(f.get(key)||'').trim();if(key==='openrouter_text_model'||key==='local_base_url'||key==='local_text_models'){body[key]=v;continue}if(!v)continue;body[key]=v==='-'?'':v}try{state.secrets=await api('/api/secrets',{method:'PUT',body:JSON.stringify(body)});e.target.reset();toast('Ключі збережено');await loadSystem();render()}catch(x){toast(x.message,true)}}
async function testSecrets(btn){btn.disabled=true;try{const r=await api('/api/secrets/test',{method:'POST'});toast(r.ok?`${r.provider}: зв’язок є, моделей ${r.models}`:`${r.provider}: ${r.detail}`,!r.ok)}catch(x){toast(x.message,true)}finally{btn.disabled=false}}
async function loadSystem(){try{state.system=await api('/api/system')}catch{state.system=null}}
async function reloadSystem(btn){if(btn){btn.disabled=true}try{await loadSystem();await loadSecrets();toast('Стан оновлено');render()}catch(x){toast(x.message,true)}finally{if(btn)btn.disabled=false}}
async function reloadModels(){try{state.models=await api('/api/models');toast('Список моделей оновлено');render()}catch(x){toast(x.message,true)}}
// render() writes the whole document in one go, so a throw halfway through leaves a
// half-built page and no error anywhere. Surface it, and tell the server once so the
// existing Telegram/webhook alerting sees frontend crashes too.
let crashReported=false;
function reportCrash(what,err){const text=`${what}: ${err&&(err.stack||err.message)||err}`.slice(0,600);console.error(what,err);try{toast('Помилка інтерфейсу — деталі в консолі',true)}catch{}if(crashReported||!state.token)return;crashReported=true;setTimeout(()=>{crashReported=false},60000);fetch('/api/client-error',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify({text,url:location.href,agent:navigator.userAgent})}).catch(()=>{})}
addEventListener('error',e=>reportCrash('Помилка скрипта',e.error||e.message));
addEventListener('unhandledrejection',e=>reportCrash('Необроблена помилка',e.reason));
// --- Лендінги: промо-сторінки кампаній з цінами і кнопками «Купити» ----------
const LANDING_STAGE={queued:'Очікування запуску',probe:'Проби товарів',images:'Генерація тематичного фону',generate:'Генерація сторінки',done:'Готово',fallback:'Аварійний шаблон',error:'Помилка'};
async function loadLandings(){try{state.landings=await api('/api/landings')}catch{state.landings=[]}}
async function openLanding(id){try{state.landingSelected=await api(`/api/landings/${id}`);render()}catch(x){toast(x.message,true)}}
function landingsPage(){if(state.landingSelected)return landingView();shell(`<header class="pagehead"><div><small class="eyebrow">ПРОМО-СТОРІНКИ</small><h1>Лендінги</h1><p>Акційні сторінки з товарами, цінами та кнопками «Купити» — за зразком artline.ua/solution.</p></div><div>${can('project.create')?`<button class="btn primary" onclick="state.landingHeroUrl='';newLanding.showModal()">+ Новий лендінг</button>`:''}</div></header>${state.landings.length?`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Назва</th><th>Період</th><th>Товарів</th><th>Статус</th><th>Вартість</th><th>Створено</th></tr></thead><tbody>${state.landings.map(x=>`<tr onclick="openLanding('${x.id}')" style="cursor:pointer"><td><b>${esc(x.name)}</b>${x.campaign_title?`<br><small>${esc(x.campaign_title)}</small>`:''}</td><td>${esc(x.period||'—')}</td><td>${x.product_count||0}</td><td>${badge(x.status)}<br><small>${LANDING_STAGE[x.stage]||esc(x.stage)}</small></td><td>${money(x.estimated_cost)}</td><td>${dt(x.created_at)}</td></tr>`).join('')}</tbody></table></div></section>`:'<div class="empty">Лендінгів ще немає. Потрібні лише посилання на товари або сторінку акції.</div>'}<dialog id="newLanding"><form method="dialog" onsubmit="if(event.submitter?.value==='create'){createLanding(event)}"><div class="dialog-head"><div><small class="eyebrow">НОВИЙ ЛЕНДІНГ</small><h2>Промо-сторінка кампанії</h2></div><button value="close" aria-label="Закрити">×</button></div><label>Назва (внутрішня)<input name="name" required maxlength="200" placeholder="Bambu Lab — річниця"></label><label>Заголовок кампанії<input name="campaign_title" maxlength="300" placeholder="Знижки до −50% на Bambu Lab"></label><label>Підзаголовок<input name="campaign_subtitle" maxlength="300" placeholder="До 4-ї річниці бренду в Україні"></label><div class="row"><label style="flex:1">Період<input name="period" maxlength="100" placeholder="15.06–15.07"></label><label>Мова<select name="language"><option value="ua">Українська</option><option value="ru">Російська</option></select></label></div><label>Посилання на товари — по одному в рядок<textarea name="product_urls" rows="5" placeholder="https://artline.ua/uk/product/..."></textarea></label><label>Посилання на категорії — по одному в рядок <em>сітка карток-категорій, як на сторінках акцій</em><textarea name="category_urls" rows="4" placeholder="https://artline.ua/uk/catalog/monitory/sort=sale&#10;https://artline.ua/uk/catalog/klaviatury/sort=sale"></textarea></label><label>Або сторінка акції <em>товари витягнуться автоматично</em><input name="listing_url" placeholder="https://artline.ua/uk/sales/..."></label><div class="row"><label style="flex:1">Стиль лендінгу<select name="style_id">${landingStyles().map(s=>`<option value="${s.id}" ${s.name==='ARTLINE Landing'?'selected':''}>${esc(s.name)}</option>`).join('')||'<option value="">ARTLINE Landing (вбудований)</option>'}</select></label><label>Текстова модель<select name="text_model"><option value="">За замовчуванням</option>${(state.models.text_models||[]).map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('')}</select></label></div>${paletteSelect()}<fieldset><legend>Фон hero</legend><div class="language-grid"><label class="check"><input type="radio" name="hero_mode" value="ai" checked onchange="landingHeroModeChanged(this.value)"> AI-фон за темою акції (платно)</label><label class="check"><input type="radio" name="hero_mode" value="custom" onchange="landingHeroModeChanged(this.value)"> Власне фото</label><label class="check"><input type="radio" name="hero_mode" value="none" onchange="landingHeroModeChanged(this.value)"> Без фону — фірмовий градієнт</label></div><div id="landingHeroUpload" class="row" style="display:none;align-items:center;gap:10px"><input type="file" accept="image/*" onchange="uploadLandingHero(this)"><span id="landingHeroStatus" class="muted-note">Файл не обрано</span></div></fieldset><p class="dialog-note">Ціни й фото тягнуться з реальних сторінок товарів при створенні — модель не може їх вигадати. AI-фон — це атмосферна сцена за темою акції (без товару й тексту). Вартість: одна текстова генерація ($0.01–0.05) + одне зображення в режимі AI-фону. Шаблон промпта — стиль «ARTLINE Landing», його можна правити в розділі Стилі.</p><div class="row"><button class="btn primary" value="create">Створити й запустити</button></div></form></dialog>`)}
function landingHeroModeChanged(mode){const box=document.getElementById('landingHeroUpload');if(box)box.style.display=mode==='custom'?'flex':'none'}
async function uploadLandingHero(input){const file=input.files?.[0];if(!file)return;const status=document.getElementById('landingHeroStatus');if(status)status.textContent='Завантаження…';try{const r=await fetch('/api/uploads/image',{method:'POST',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':'application/octet-stream'},body:file});const d=await r.json().catch(()=>null);if(!r.ok)throw Error(d?.detail||`HTTP ${r.status}`);state.landingHeroUrl=d.url;if(status)status.textContent=`Готово: ${file.name} (${d.width}×${d.height})`}catch(x){state.landingHeroUrl='';if(status)status.textContent='Помилка: '+x.message;toast(x.message,true)}}
async function createLanding(e){const f=new FormData(e.target);const urls=String(f.get('product_urls')||'').split('\n').map(s=>s.trim()).filter(Boolean);const catUrls=String(f.get('category_urls')||'').split('\n').map(s=>s.trim()).filter(Boolean);const heroMode=String(f.get('hero_mode')||'ai');if(heroMode==='custom'&&!state.landingHeroUrl){toast('Завантажте файл фону або оберіть інший режим hero',true);return}try{const d=await api('/api/landings',{method:'POST',body:JSON.stringify({name:f.get('name'),campaign_title:f.get('campaign_title'),campaign_subtitle:f.get('campaign_subtitle'),period:f.get('period'),language:f.get('language'),product_urls:urls,category_urls:catUrls,listing_url:f.get('listing_url'),text_model:f.get('text_model'),palette_id:f.get('palette_id')||null,hero_mode:heroMode,custom_hero_url:heroMode==='custom'?(state.landingHeroUrl||''):'',style_id:f.get('style_id')||null})});toast('Лендінг створено — генерація запущена');await loadLandings();state.landingSelected=await api(`/api/landings/${d.id}`);render()}catch(x){toast(x.message,true)}}
function landingDocument(html){return html||''}
function openLandingPreview(){const html=state.landingSelected?.html;if(!html)return toast('Сторінка ще не згенерована',true);const win=window.open('about:blank','_blank');if(!win)return toast('Браузер заблокував нову вкладку',true);win.document.open();win.document.write(html);win.document.close()}
async function rerunLanding(button){if(!state.landingSelected)return;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Запуск…'}try{state.landingSelected=await api(`/api/landings/${state.landingSelected.id}/run`,{method:'POST'});toast('Перегенерацію запущено');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function saveLandingHtml(button){const editor=document.getElementById('landingHtmlEditor');if(!editor||!state.landingSelected)return;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Збереження…'}try{state.landingSelected=await api(`/api/landings/${state.landingSelected.id}`,{method:'PUT',body:JSON.stringify({html:editor.value})});toast('Збережено');render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
async function downloadLanding(){if(!state.landingSelected)return;try{const response=await fetch(`/api/landings/${state.landingSelected.id}/page.html`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){let detail=`HTTP ${response.status}`;try{detail=(await response.json()).detail||detail}catch{}throw Error(detail)}const blob=await response.blob(),match=/filename="([^"]+)"/.exec(response.headers.get('Content-Disposition')||''),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=match?.[1]||'landing.html';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(x){toast(x.message,true)}}
async function deleteLanding(){if(!state.landingSelected)return;if(!confirm('Видалити лендінг безповоротно?'))return;try{await api(`/api/landings/${state.landingSelected.id}`,{method:'DELETE'});state.landingSelected=null;await loadLandings();render()}catch(x){toast(x.message,true)}}
function landingShareUrl(l){return l&&l.share_token?`${location.origin}/p/${l.share_token}`:''}
function landingShareBanner(l){if(!l.public)return '';const u=landingShareUrl(l);return `<section class="panel"><div class="panel-tools"><h2>Публічне посилання</h2><span class="muted-note">Відкривається без входу в студію, пошуком не індексується.</span></div><div class="row" style="gap:8px;align-items:center"><input id="landingShareUrl" readonly value="${esc(u)}" style="flex:1"><button class="btn secondary" onclick="copyLandingShare(this)">Копіювати</button><a class="btn ghost" href="${esc(u)}" target="_blank" rel="noopener">Відкрити</a>${can('project.edit_html')?`<button class="btn ghost" onclick="rotateLandingShare(this)">Новий токен</button>`:''}</div></section>`}
async function landingShare(body,button,okText){if(!state.landingSelected)return;const original=button?.textContent;if(button){button.disabled=true;button.textContent='…'}try{state.landingSelected=await api(`/api/landings/${state.landingSelected.id}/share`,{method:'POST',body:JSON.stringify(body)});await loadLandings();toast(okText);render()}catch(x){toast(x.message,true)}finally{if(button){button.disabled=false;button.textContent=original}}}
function toggleLandingShare(makePublic,button){landingShare({public:!!makePublic},button,makePublic?'Опубліковано — посилання нижче':'Публікацію скасовано, посилання більше не відкривається')}
function rotateLandingShare(button){if(!confirm('Стара адреса перестане відкриватись у всіх, кому її вже надіслали. Видати нову?'))return;landingShare({public:true,rotate:true},button,'Видано нове посилання')}
async function copyLandingShare(button){const field=document.getElementById('landingShareUrl');if(!field)return;const original=button?.textContent;try{await navigator.clipboard.writeText(field.value)}catch{field.select();document.execCommand('copy')}if(button){button.textContent='Скопійовано';setTimeout(()=>{button.textContent=original},1500)}}
function landingView(){const l=state.landingSelected;shell(`<header class="pagehead"><div><button class="btn ghost" onclick="state.landingSelected=null;render()">← Лендінги</button><h1 style="margin-top:8px">${esc(l.name)}</h1><p>${badge(l.status)} <small>${LANDING_STAGE[l.stage]||esc(l.stage)}</small> · ${money(l.estimated_cost)} · ${l.product_count||0} товарів${l.category_count?` · ${l.category_count} категорій`:''}${l.text_model?` · ${esc(l.text_model)}`:''}</p></div><div class="row">${can('project.create')?`<button class="btn secondary" onclick="rerunLanding(this)">Перегенерувати</button>`:''}<button class="btn secondary" onclick="downloadLanding()">Скачати HTML</button><button class="btn secondary" onclick="openLandingPreview()">Відкрити окремо</button>${can('project.edit_html')?`<button class="btn ${l.public?'ghost':'secondary'}" onclick="toggleLandingShare(${l.public?'false':'true'},this)">${l.public?'Скасувати публікацію':'Опублікувати'}</button>`:''}${can('project.delete')?`<button class="btn ghost" onclick="deleteLanding()">Видалити</button>`:''}</div></header>${landingShareBanner(l)}${l.error?`<div class="fallback-banner"><b>Помилка генерації.</b> ${esc(l.error)}</div>`:''}${l.fallback_reason?`<div class="fallback-banner"><b>Це аварійний шаблон.</b> AI-генерація не вдалася — сторінку зібрано детерміновано. Причина: ${esc(l.fallback_reason)}</div>`:''}${(l.categories||[]).length?`<section class="panel"><h2>Категорії (${l.categories.length})</h2><div class="table-wrap"><table><thead><tr><th>Категорія</th><th>Зображення</th></tr></thead><tbody>${l.categories.map(c=>`<tr><td><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.name)}</a></td><td>${c.image?'є':'—'}</td></tr>`).join('')}</tbody></table></div></section>`:''}${(l.products||[]).length?`<section class="panel"><h2>Товари (${l.products.length})</h2><div class="table-wrap"><table><thead><tr><th>Товар</th><th>Ціна</th></tr></thead><tbody>${l.products.map(p=>`<tr><td><a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.name)}</a></td><td>${esc(p.price_text||'—')}</td></tr>`).join('')}</tbody></table></div></section>`:''}${l.html?`<section class="panel preview-panel"><div class="panel-tools"><h2>Перегляд</h2></div><div class="preview" style="height:72vh"><iframe title="Лендінг" sandbox="allow-same-origin" scrolling="yes" style="width:100%;height:100%;border:0;background:#fff" srcdoc="${esc(landingDocument(l.html))}"></iframe></div></section>${can('project.edit_html')?`<section class="panel"><div class="panel-tools"><h2>HTML</h2><button class="btn primary" onclick="saveLandingHtml(this)">Зберегти</button></div><textarea id="landingHtmlEditor" class="code" rows="18">${esc(l.html)}</textarea></section>`:''}`:(l.status==='queued'||l.status==='processing')?'<div class="empty">Генерація триває — сторінка зʼявиться тут автоматично.</div>':''}`)}
function render(){if(!state.token)return loginView();if(state.selected){workspace();animateProgressBars();enhanceSelects();syncUrl();return}if(!allowedPages().includes(state.page))state.page=allowedPages()[0]||'projects';({projects:projectsPage,landings:landingsPage,infographic:infographicPage,styles:stylesPage,media:mediaPage,usage:usagePage,users:usersPage,settings:settingsPage}[state.page]||projectsPage)();animateProgressBars();enhanceSelects();syncUrl()}
boot().catch(e=>{console.error(e);toast(e.message,true);render()});
